MultiLanguageSpellData['mx'][400807] = {name = "[q4]Faltriquera de especias resplandeciente", additional_info = "Hechizo de 3.5 seg\nComponentes:\nEspecias sin sabor\nVendedora:\nComerciante Hag'arth\nZona:\nEl Confín Prohibido\nCosto:\n10\n\n[q4]Faltriquera de especias resplandeciente\nCuriosidades artesanales\n[q]\"¡El ingrediente que faltaba era amor! El aroma es sensacional. Esto es una muestra maravillosa del Confín Prohibido. Puede activar un enfrentamiento especial.\""}
MultiLanguageSpellData['mx'][400808] = {name = "[q4]Tridente ceremonial antiguo", additional_info = "Hechizo de 3.5 seg\nComponentes:\nTridente dañado\nVendedora:\nComerciante Hag'arth\nZona:\nEl Confín Prohibido\nCosto:\n10\n\n[q4]Tridente ceremonial antiguo\nCuriosidades artesanales\n[q]\"Este tridente no está hecho de materiales aptos para el combate, parece tener características ritualistas. Ten cuidado cuando lo coloques en el Confín Prohibido. Puede activar un enfrentamiento especial.\""}
MultiLanguageSpellData['mx'][400809] = {name = "[q4]Marcador de cristal resplandeciente", additional_info = "Hechizo de 3.5 seg\nComponentes:\nCristal sin brillo\nVendedora:\nComerciante Hag'arth\nZona:\nEl Confín Prohibido\nCosto:\n10\n\n[q4]Marcador de cristal resplandeciente\nCuriosidades artesanales\n[q]\"Este marcador brillante ruega que lo coloquen en un buen libro, como los que hay en el Confín Prohibido. Puede activar un encuentro especial.\""}
MultiLanguageSpellData['mx'][400810] = {name = "[q4]Caja de voz gnómica", additional_info = "Hechizo de 3.5 seg\nComponentes:\nCaja de voz gnómica averiada\nVendedora:\nComerciante Hag'arth\nZona:\nEl Confín Prohibido\nCosto:\n10\n\n[q4]Caja de voz gnómica\nCuriosidades artesanales\n[q]\"¿Cómo llegó un artilugio gnómico al Confín Prohibido? Necesitarás un zumbógrafo para hacer que funcione. Puede activar un encuentro especial.\""}
MultiLanguageSpellData['mx'][400811] = {name = "[q4]Runa disipadora arcana", additional_info = "Hechizo de 3.5 seg\nComponentes:\nRuna escrita con prisa\nVendedora:\nComerciante Hag'arth\nZona:\nEl Confín Prohibido\nCosto:\n10\n\n[q4]Runa disipadora arcana\nCuriosidades artesanales\n[q]\"Después de limpiar las líneas, ves que esta runa sirve para disipar resguardos como los que se usan en el Confín Prohibido. Puede activar un encuentro especial.\""}
MultiLanguageSpellData['mx'][400812] = {name = "[q4]Diapasón armonizador para cristales", additional_info = "Hechizo de 3.5 seg\nComponentes:\nDiapasón de cristal\nVendedora:\nComerciante Hag'arth\nZona:\nEl Confín Prohibido\nCosto:\n10\n\n[q4]Diapasón armonizador para cristales\nCuriosidades artesanales\n[q]\"Golpear el cristal indicado con esto en el Confín Prohibido podría producir una nota melodiosa. Puede activar un encuentro especial.\""}
MultiLanguageSpellData['mx'][400813] = {name = "Fricción temporal", additional_info = "[q]Canaliza el calor de las líneas temporales inestables durante el evento La furia de la tormenta en el Futuro Primalista para eliminar una acumulación de Congelamiento cada 11 segundos."}
MultiLanguageSpellData['mx'][400814] = {name = "[q4]Cuero prístino reforzado", additional_info = "Hechizo de 3.5 seg\nComponentes:\nPelambre prístina\nVendedora:\nComerciante Hag'arth\nZona:\nEl Confín Prohibido\nCosto:\n10\n\n[q4]Cuero prístino reforzado\nCuriosidades artesanales\n[q]\"Los colmillarr morqut usan estos parches de cuero reforzado para enmendar algunos pellejos dañados en el Confín Prohibido. Puede activar un encuentro especial.\""}
