MultiLanguageSpellData['mx'][401124] = {name = "Ejecución ferviente", additional_info = "Rango ilimitado\nInstante\n[q]Neltharion corrompe la fe del paladín y lo obliga a invocar un martillo de la Luz cada 6 s durante 30 s. El martillo consagra el suelo e inflige 10 p. de daño sagrado a todo lo que se encuentre en él. Después de 5 s, el martillo golpea el suelo e inflige 50 p. más de daño sagrado."}
MultiLanguageSpellData['mx'][401125] = {name = "Bestias corrompidas", additional_info = "Rango ilimitado\nInstante\n[q]Neltharion obliga al cazador a llamar a mascotas corrompidas de su establo y las obliga a atacar.\n\n Al sacrificar una bestia corrupta, Oscuridad desatada potenciará al cazador."}
MultiLanguageSpellData['mx'][401126] = {name = "Traición salvaje", additional_info = "Rango ilimitado\nInstante\n[q]Neltharion corrompe la traición natural del pícaro y lo hace usar Paso de las sombras contra un aliado cada 10 s y luego arrojar dagas contra todos los objetivos en 10 m para infligir 20 p. de daño físico. Además, aflige a todos los objetivos con Veneno salvaje ."}
MultiLanguageSpellData['mx'][401127] = {name = "Grito desesperado", additional_info = "Rango ilimitado\nInstante\n[q]La corrupción de Neltharion hace flaquear la fe del sacerdote y lo obliga a que lance un Grito desesperado cada 6 s durante 30 s, lo que inflige 7 p. de daño de las sombras cada 1 s a los jugadores y criaturas en un radio de 8 m y hace que huyan aterrorizados durante 6 s.\n\n El sacerdote obtiene una aplicación de Palabra de las sombras: perfidia por cada objetivo golpeado, hasta un máximo de 5."}
MultiLanguageSpellData['mx'][401128] = {name = "Agarre salvaje", additional_info = "Rango ilimitado\nInstante\n[q]Neltharion toma el control de los poderes de no-muerto del caballero de la muerte y lo obliga a crear parches de Pestilencia salvaje y a aplicar atracción letal a los aliados en su ubicación cada 10 s durante 30 s."}
MultiLanguageSpellData['mx'][401129] = {name = "Tótem de elemental de sombra", additional_info = "Rango ilimitado\nInstante\n[q]Neltharion obliga al chamán a invocar tótems para vincular elementales de las sombras que luego atacarán.\n\n Cuando derrota a un elemental, el chamán se potencia con Oscuridad desatada ."}
MultiLanguageSpellData['mx'][401130] = {name = "Magia salvaje", additional_info = "Rango ilimitado\nInstante\n[q]Neltharion corrompe las energías arcanas del mago y lo obliga a lanzar Magia salvaje cada 10 s durante 30 s, lo que inflige 20 p. de daño arcano a los jugadores y criaturas en un radio de 10 m cada 0.5 s durante 4 s."}
MultiLanguageSpellData['mx'][401131] = {name = "Invocación salvaje", additional_info = "Rango ilimitado\nInstante\n[q]Neltharion obliga al brujo a invocar alucinaciones de bestias del Vació voraces que atacan al brujo durante 25 s.\n\n Cuando mata a una de las bestias, el brujo se potencia con Oscuridad desatada ."}
MultiLanguageSpellData['mx'][401132] = {name = "Espíritu, agua y descomposición", additional_info = "Rango ilimitado\nInstante\n[q]Neltharion corrompe la esencia del monje y hace que desprenda espíritus durante 30 s.\n\n Cuando derrota a uno de los espíritus, el monje se potencia con Oscuridad desatada ."}
MultiLanguageSpellData['mx'][401133] = {name = "Cambio salvaje", additional_info = "Rango ilimitado\nInstante\n[q]Neltharion se aprovecha de la conexión con la naturaleza del druida y lo obliga a hacer un Cambio de forma aleatorio cada 10 s durante 30 s. La violencia salvaje del cambio hace que el druida desate un Apaleo salvaje y le otorga Fervor de cambiaformas ."}
