MultiLanguageSpellData['mx'][405830] = {name = "Aliento de Pirosombra", additional_info = "Instante\n[q]Exhala llamas en la dirección del objetivo actual en un radio de 45 m, lo que inflige 25 p. de daño de pirosombra a los jugadores que están en un cono frente al taumaturgo cada 1 s durante 3 s."}
