MultiLanguageSpellData['mx'][409646] = {name = "Compensación de expedición", additional_info = "Instante\n[q]Rannan recompensa a quienes lo ayudan en su expedición según los objetivos de investigación completados. Ahora recibirás [un regalo del investigador ][sin compensación] por tus esfuerzos hasta el momento."}
MultiLanguageSpellData['mx'][409647] = {name = "Llamas gemelas", additional_info = "Alcance de 100 m\nInstante\n[q]Envuelve a los enemigos en Llamas incineradoras o Llamas corruptas .\n\n Llamas incineradoras\nInflige 271054 p. de daño de fuego a los enemigos en un radio de 10 m cada 1 s durante 14 s.\n\n Entrar a las Llamas corruptas elimina este efecto.\n\n Entrar a las Llamas incineradoras de otro jugador provoca una violenta explosión que inflige 2710541 p. de daño de fuego a ambos jugadores.\n\n Llamas corruptas\nInflige 271054 p. de daño de pirosombra a los enemigos en un radio de 10 m cada 1 s durante 14 s.\n\n Entrar a las Llamas incineradoras elimina este efecto.\n\n Entrar a las Llamas corruptas de otro jugador provoca una violenta explosión que inflige 2710541 p. de daño de pirosombra a ambos jugadores."}
