MultiLanguageSpellData['mx'][414323] = {name = "Grifo negro voraz", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"La guerra corrompió a estas criaturas antaño orgullosas. El aleteo de sus alas susurra ahora presagios de una muerte inminente.\"\nAlianza\nBotín:\nFallas temporales\nVendedora:\nCeladora Krizzik\nZona:\nReserva de Fuerte Tyr\nCosto:\n3000\n\nHorda\nObjeto:\nRegalo del grifo negro voraz"}
MultiLanguageSpellData['mx'][414324] = {name = "Albatros dedos de oro", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Elevándose por un portal del tiempo lejano, esta variante aviar nunca antes vista nació en un mundo de orden.\"\nBotín:\nFallas temporales\nVendedora:\nSorotis\nZona:\nReserva de Fuerte Tyr\nCosto:\n3000"}
MultiLanguageSpellData['mx'][414326] = {name = "Dragón tormenta vil", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"La Legión Ardiente derrotó a los dragones en un portal del tiempo lejano. Estos Vermis de energía vil hedionda prefirieron la corrupción y la servidumbre a la destrucción.\"\nBotín:\nFallas temporales\nVendedora:\nFalara Arrullanoche\nZona:\nReserva de Fuerte Tyr\nCosto:\n3000"}
MultiLanguageSpellData['mx'][414327] = {name = "Sabueso de azufre", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira un sabueso de azufre que se puede montar.\n[q]\"El Imperio Negro subyugó a estos sabuesos humildes y odiosos. Totalmente obedientes, siguen sirviendo a los fuertes.\"\nBotín:\nFallas temporales\nVendedora:\nProveedora Qorra\nZona:\nReserva de Fuerte Tyr\nCosto:\n3000"}
MultiLanguageSpellData['mx'][414328] = {name = "Gigante perfeccionado", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira un gigante perfeccionado.\n[q]\"La perfección, así como la belleza, está en el ojo del espectador. Pero la vista puede mejorarse con una cirugía.\"\nBotín:\nFallas temporales\nVendedora:\nAdra Taladra\nZona:\nReserva de Fuerte Tyr\nCosto:\n3000"}
MultiLanguageSpellData['mx'][414330] = {name = "Protección de línea temporal", additional_info = "Canalizado (Hechizo de 6 seg)\n[q]Cromi crea una burbuja de tiempo expandida y reduce un 97% el daño infligido a los jugadores durante 6 s.\n\n Cuando Protección de línea temporal termina, Cromi se vuelve Agotada ."}
