MultiLanguageSpellData['mx'][414564] = {name = "[q4]Ropa maldita", additional_info = "Hechizo de 3.5 seg\nComponentes:\nChatarra asolada por la guerra (50), Tela vil (20), Esencia de no-muerto (6), Runa oscura (2), Runa congelada\n[q]Este objeto maldito se aferra a la primera alma que encuentra, por lo que solo puede crearse para otros a través de un pedido de fabricación.\nDescubrimiento:\nNaxxramas\n\n[q4]Ropa maldita\nSe liga al recogerlo\n[q2]Uso: Repara un equipo de cruzado difunto con materiales corruptos y le restaura, parcialmente, su gloria antigua.\n\n El objeto resultante queda ligado a la tropa, y un mago, sacerdote o brujo que esté dispuesto a conseguir los componentes necesarios puede purificar la profanación."}
MultiLanguageSpellData['mx'][414565] = {name = "[q4]Cuero lánguido", additional_info = "Hechizo de 3.5 seg\nComponentes:\nChatarra asolada por la guerra (50), Cuero encantado (40), Esencia de no-muerto (6), Runa oscura (2), Runa congelada\n[q]Este objeto maldito se aferra a la primera alma que encuentra, por lo que solo puede crearse para otros a través de un pedido de fabricación.\nDescubrimiento:\nNaxxramas\n\n[q4]Cuero lánguido\nSe liga al recogerlo\n[q2]Uso: Repara un equipo de cruzado difunto con materiales corruptos y le restaura, parcialmente, su gloria antigua.\n\n El objeto resultante queda ligado a la tropa, y un druida o pícaro que esté dispuesto a conseguir los componentes necesarios puede purificar la profanación."}
MultiLanguageSpellData['mx'][414566] = {name = "[q4]Escamas de la plaga", additional_info = "Hechizo de 3.5 seg\nComponentes:\nChatarra asolada por la guerra (50), Cuero encantado (40), Esencia de no-muerto (6), Runa oscura (2), Runa congelada\n[q]Este objeto maldito se aferra a la primera alma que encuentra, por lo que solo puede crearse para otros a través de un pedido de fabricación.\nDescubrimiento:\nNaxxramas\n\n[q4]Escamas de la plaga\nSe liga al recogerlo\n[q2]Uso: Repara un equipo de cruzado difunto con materiales corruptos y le restaura, parcialmente, su gloria antigua.\n\n El objeto resultante queda ligado a la tropa, y un cazador o chamán que esté dispuesto a conseguir los componentes necesarios puede purificar la profanación."}
