MultiLanguageSpellData['mx'][421378] = {name = "Treinta metros de cuerda", additional_info = "[q]Brann arroja su cuerda para liberar a los jugadores de los efectos de aturdimientos, ataduras y frenado, y otorga inmunidad a ese tipo de efectos durante 4 s."}
MultiLanguageSpellData['mx'][421379] = {name = "Channeling Fire Missiles - Pylon 3 [ DNT]", additional_info = nil}
MultiLanguageSpellData['mx'][421380] = {name = "Bálsamo purificador", additional_info = "[q]Brann lanza dardos sedantes a los enemigos potenciados, lo que elimina 1 efecto de Enfurecer y 1 efecto mágico."}
MultiLanguageSpellData['mx'][421382] = {name = "Huevo épico de Brann", additional_info = "[q]Brann invoca un huevo de demosaurio. Ojalá eclosione."}
MultiLanguageSpellData['mx'][421383] = {name = "Ráfaga de agua", additional_info = nil}
MultiLanguageSpellData['mx'][421387] = {name = "Correa de mono", additional_info = "[q]Tus hechizos y habilidades tienen una probabilidad de llamar al mono mascota de Brann, Glibb, para que te acompañe durante 15 s con bananas en la mano.\n\n Aspecto del mono\nLa presencia de Glibb te potencia, lo que aumenta 845 p. la velocidad, la evasión y el robo de vida.\n\n Mono malo\nGlibb hace un berrinche que inflige una tremenda cantidad de daño físico a los enemigos cercanos con una probabilidad de aturdirlos durante 3 s."}
MultiLanguageSpellData['mx'][421389] = {name = "Trampa de hielo", additional_info = "[q]Después de que 3 o más enemigos ataquen a un jugador, Brann les arrojará una trampa de hielo que reducirá su velocidad de movimiento un 50% y, por momentos, los congelará en el lugar durante 3 s. La trampa dura 15 s."}
MultiLanguageSpellData['mx'][421395] = {name = "Suministros de emergencia", additional_info = "[q]Cuando un jugador cae por debajo del 30% de salud, Brann sanará un 25% de su salud máxima al instante. Solo puede ocurrir una vez cada 3 min."}
MultiLanguageSpellData['mx'][421397] = {name = "Arnés de batalla de Grifadin", additional_info = "[q]Brann invoca a su leal compañero grifo para bombardear a los enemigos cercanos e infligirles un daño considerable cada 1 s durante 10 s."}
MultiLanguageSpellData['mx'][421398] = {name = "Haz de fuego", additional_info = "Alcance de 300 m\nHechizo de 2 seg\n[q]Yescal dispara a la plataforma con haces de fuego que infligen 2538328 p. de daño de fuego a los jugadores en un radio de 15 m del impacto. El impacto crea varios haces que se mueven e infligen 1450473 p. de daño de fuego a los jugadores que quedan atrapados entre ellos cada 1."}
MultiLanguageSpellData['mx'][421399] = {name = "Rayo solar", additional_info = nil}
MultiLanguageSpellData['mx'][421400] = {name = "Carga perforadora", additional_info = "Alcance de 20 mHechizo de 1 seg 11 seg de reutilización\n[q]El taumaturgo se prepara para un gran ataque contra su objetivo actual e inflige 11 p. de daño físico a cualquiera que esté en el camino del ataque."}
MultiLanguageSpellData['mx'][421402] = {name = "Fuego primigenio", additional_info = "Alcance de 30 mHechizo de 2 seg 3 seg de reutilización\n[q]Inflicts 5 Fire damage to an enemy.\n Inflicts 2 Fire damage to an enemy every 2 sec for 4 s."}
