MultiLanguageSpellData['mx'][421419] = {name = "Plena floración", additional_info = "Rango ilimitado\nInstante\n[q]Cuando alcanza un 100% de energía, Nymue libera una abrumadora oleada de energía vital que inflige 797760 p. de daño de naturaleza a los jugadores en un radio de 16 m y les otorga Inflorescencia .\n\n Luego, la oleada fluye hacia afuera y se combina para formar 2 celadores del ciclo poderosos."}
MultiLanguageSpellData['mx'][421421] = {name = "Cultivo fatal", additional_info = "Alcance de 500 m\nInstante\n[q]Nudorraíz hace crecer Raíces fatídicas que absorben poder de la tierra, lo que reduce un 99% el daño que recibe y hace que emita pulsos que infligen 43514 p. de daño de pirosombra cada 5.2 s.\n\n El cuerpo de Nudorraíz expulsa un Carbón aplastante cada 8 s.\n\n Esta habilidad corrompe el suelo debajo de Nudorraíz, despierta a las criaturas durmientes y crea un Mantillo tóxico .\n\n Destruir todas las raíces fatídicas aflige a Nudorraíz con una Agonía desarraigada ."}
MultiLanguageSpellData['mx'][421422] = {name = "Ventana de construcción: Continuación de las notas de Eadward", additional_info = nil}
MultiLanguageSpellData['mx'][421427] = {name = "Carbón aplastante", additional_info = "Rango ilimitado\nInstante\n[q]Trozos de carbón ardiente vuelan desde Nudorraíz e infligen 36262 p. de daño de pirosombra en un radio de 5 m de las zonas de impacto y dejan a cada jugador Calcinado por ascuas .\n\n Cada trozo de carbón que no golpea a un jugador entra en erupción cuando cae al suelo, lo que inflige 108785 p. de daño de pirosombra a todos los jugadores."}
