MultiLanguageSpellData['mx'][422850] = {name = "Death Knight Blood 10.2 Class Set 2pc", additional_info = "[q]Consumir poder rúnico hace que tu próximo Golpe en el corazón aplique Descomposición cinérea, lo que reduce un 10% el daño que te infligen y aumenta un 20% el daño que infliges a los objetivos afectados durante 8 s."}
MultiLanguageSpellData['mx'][422851] = {name = "Death Knight Blood 10.2 Class Set 4pc", additional_info = "[q]El daño de ejecución de Segador de almas y el daño de Extremidad de abominación aplican Descomposición cinérea a los objetivos enemigos, y el daño directo de Golpe en el corazón y Hervor de sangre prolongan Descomposición cinérea durante 1.0 s."}
MultiLanguageSpellData['mx'][422852] = {name = "Death Knight Frost 10.2 Class Set 2pc", additional_info = "[q]El alcance de Seguidilla escalofriante aumenta 4 m y puede rebotar contra ti. Cada vez que Seguidilla escalofriante rebota, tu daño aumenta un 4% durante 12 s. Se acumula hasta 5 veces."}
MultiLanguageSpellData['mx'][422853] = {name = "Death Knight Frost 10.2 Class Set 4pc", additional_info = "[q]Seguidilla escalofriante puede rebotar 3 veces más y, cada vez que rebota, tienes un 35% de probabilidad de ganar una runa, reducir 5 s el tiempo de reutilización de Seguidilla escalofriante o reducir 6 s el tiempo de reutilización de Potenciar arma de runas."}
MultiLanguageSpellData['mx'][422854] = {name = "Death Knight Unholy 10.2 Class Set 2pc", additional_info = "[q]Apocalipsis invoca un mago de los muertos más. La Descarga de las sombras de tu mago de los muertos ahora dispara una salva de Descargas de las sombras a un máximo de 4 enemigos cercanos."}
MultiLanguageSpellData['mx'][422855] = {name = "Death Knight Unholy 10.2 Class Set 4pc", additional_info = "[q]Cada runa que gastas aumenta la duración de tu magi activo en 0.5 s y tu magi ahora también lanzará Amplificar daño, lo que aumentará un 5% el daño que infliges durante 10 s."}
MultiLanguageSpellData['mx'][422856] = {name = "Helada blanca", additional_info = nil}
MultiLanguageSpellData['mx'][422857] = {name = "Demon Hunter Havoc 10.2 Class Set 2pc", additional_info = "[q]Danza de hojas activa automáticamente Lanzar guja sobre tu objetivo principal y le inflige un 100% de daño. Además, cada corte tiene un 50% de probabilidad de Lanzar guja a un enemigo e infligirle un 35% de daño."}
MultiLanguageSpellData['mx'][422858] = {name = "Distintivo esmeralda de la amistad de Pip", additional_info = "Aproximadamente 2 activaciones por minuto\n[q]Te unes al Equipo de ensueño, obtienes ( 266 / 12) p. de la maestría de Pip, la versatilidad de Urctos o el golpe crítico de Aerwynn basado en tu mejor amigo actual.\n\n Tus hechizos y habilidades tienen una probabilidad de agregar un mejor amigo nuevo aleatorio, lo que te otorga su bonificación pasiva y la potenciará a 266 p. antes de reducirse durante 12 segundos.\n(12s de reutilización)"}
MultiLanguageSpellData['mx'][422859] = {name = "Demon Hunter Havoc 10.2 Class Set 4pc", additional_info = "[q]Lanzar guja reduce 2.0 s el tiempo de reutilización restante de La cacería, y el efecto de daño con el tiempo de La cacería dura 6 s más."}
MultiLanguageSpellData['mx'][422860] = {name = "Demon Hunter Vengeance 10.2 Class Set 2pc", additional_info = "[q]Cuando atacas a un objetivo bajo el efecto de Sigilo de la llama, tu daño y sanación aumentan un 2%, y tu aguante aumenta un 2% durante 8 s. Puede acumularse un máximo de 5 veces.\n(750ms de reutilización)"}
MultiLanguageSpellData['mx'][422861] = {name = "Demon Hunter Vengeance 10.2 Class Set 4pc", additional_info = "[q]El daño periódico de Sigilo de la llama tiene una probabilidad de estallar, lo que destroza un fragmento de alma adicional del objetivo e inflige ([60.72% of Attack Power]) p. más de daño. Cada 40 p. de furia que gastas reduce 1.0 s su tiempo de reutilización."}
MultiLanguageSpellData['mx'][422862] = {name = "Druid Balance 10.2 Class Set 2pc", additional_info = "[q]Cuando Eclipse termina o cuando entras en combate, te sumerges en un estado onírico, lo que reduce un 40% el tiempo de lanzamiento de tus siguientes 2 Fuegos estelares o Cóleras y aumenta un 100% su daño."}
MultiLanguageSpellData['mx'][422863] = {name = "Druid Balance 10.2 Class Set 4pc", additional_info = "[q]Oleada de estrellas o Lluvia de estrellas aumentan la bonificación de daño arcano o de naturaleza de tu Eclipse actual un 2% más, hasta un 10%."}
MultiLanguageSpellData['mx'][422864] = {name = "Druid Guardian 10.2 Class Set 2pc", additional_info = "[q]La ira que gastas durante Ira del Durmiente alimenta el crecimiento de Espinas oníricas, que te rodean para protegerte cuando termina Ira del Durmiente, y absorben un 25% del daño que te infligen mientras duran las espinas, hasta (660 / 100 * Poder de ataque) p. de daño por cada 20 p. de ira que gastes."}
MultiLanguageSpellData['mx'][422865] = {name = "Druid Guardian 10.2 Class Set 4pc", additional_info = "[q]Cada 40 p. de ira que gastas mientras Ira del Durmiente está activa extiende la duración en 1.0 s, hasta un máximo de 5.0. Espinas oníricas se transforma en Espinas ardientes, que hace que un 100% del daño absorbido se refleje hacia el atacante."}
MultiLanguageSpellData['mx'][422866] = {name = "Druid Restoration 10.2 Class Set 2pc", additional_info = "[q]Tu Nutrir y el de tu guardiana de la arboleda ahora sanan a 2 aliados más que se encuentren en un radio de 40 m con un 40% de efectividad."}
MultiLanguageSpellData['mx'][422867] = {name = "Druid Restoration 10.2 Class Set 4pc", additional_info = "[q]Ahora, al consumir Lanzamiento libre, tu Recrecimiento también lanza Nutrir a un aliado herido cercano con un 200% de efectividad, y da preferencia a los que tienen tus efectos de sanación con el tiempo."}
MultiLanguageSpellData['mx'][422868] = {name = "Evoker Augmentation 10.2 Class Set 2pc", additional_info = "[q]Cada tercer Presagio dura un 100% más."}
MultiLanguageSpellData['mx'][422869] = {name = "Evoker Augmentation 10.2 Class Set 4pc", additional_info = "[q]Lanzar Presagio mejora tu siguiente Erupción y le agrega fisuras más pequeñas por cada Presagio que tengas activo. Cada una inflige ([110% of Spell Power]) p. de daño y prolonga Poder de ébano durante 0.2 s."}
MultiLanguageSpellData['mx'][422870] = {name = "Evoker Devastation 10.2 Class Set 2pc", additional_info = "[q]Mientras Furia dracónica esté activa, obtienes Trance Esmeralda cada 6 s, lo que aumenta un 5% tu daño infligido. Este efecto se acumula hasta 5 veces.\n(Probabilidad de que accione: 15%, 500ms de reutilización)"}
MultiLanguageSpellData['mx'][422871] = {name = "Evoker Devastation 10.2 Class Set 4pc", additional_info = "[q]Cuando Furia dracónica termina, Trance esmeralda continúa durante 5 s por acumulación y te otorga Ráfaga esencial cada 5 s."}
MultiLanguageSpellData['mx'][422872] = {name = "Evoker Preservation 10.2 Class Set 2pc", additional_info = "[q]Los hechizos potenciados lanzan hasta 3 Llamas vivas a los enemigos o aliados con un 50% de efectividad."}
MultiLanguageSpellData['mx'][422873] = {name = "Evoker Preservation 10.2 Class Set 4pc", additional_info = "[q]Llama viva tiene una probabilidad de aplicar Eco con un 70% de efectividad a los aliados sanados o a un aliado cercano que aún no esté bajo el efecto de Eco.\n(Probabilidad de que accione: 33%)"}
