MultiLanguageSpellData['mx'][422878] = {name = "Hunter Survival 10.2 Class Set 2pc", additional_info = "[q]Furia del águila aumenta un 15% la probabilidad de golpe crítico tuya y de tu mascota y un 15% el daño crítico infligido durante 12 s."}
MultiLanguageSpellData['mx'][422879] = {name = "Hunter Survival 10.2 Class Set 4pc", additional_info = "[q]Furia del águila lanza sin costo una Bomba de fuego salvaje a tu objetivo actual con un 100% de efectividad, hace que tu siguiente Bomba de fuego salvaje no active su tiempo de reutilización y aumenta el daño que inflige Bomba de fuego salvaje a tu objetivo principal un 40% durante 12 s."}
MultiLanguageSpellData['mx'][422880] = {name = "Mage Arcane 10.2 Class Set 2pc", additional_info = "[q]Consumir Lanzamiento libre aumenta el daño con hechizos un 2% durante 20 s y se acumula hasta un 10%."}
MultiLanguageSpellData['mx'][422881] = {name = "Mage Arcane 10.2 Class Set 4pc", additional_info = "[q]Después de consumir Lanzamiento libre 3 veces, tu siguiente Misiles arcanos consume Batería arcana e inflige un 150% más de daño a tu objetivo principal y les dispara hasta a 4 enemigos cercanos, lo que inflige un 100% más de daño."}
MultiLanguageSpellData['mx'][422882] = {name = "Mage Fire 10.2 Class Set 2pc", additional_info = "[q]Cuando Piroexplosión y Fogonazo asestan un golpe crítico, obtienes Ira abrasadora, que aumenta un 4% tu daño de golpe crítico durante 12 s y se acumula hasta un 20%."}
MultiLanguageSpellData['mx'][422883] = {name = "Mage Fire 10.2 Class Set 4pc", additional_info = "[q]Activar Combustión aumenta un 150% la bonificación de daño de golpe crítico de Ira abrasadora durante 12 s."}
MultiLanguageSpellData['mx'][422884] = {name = "Mage Frost 10.2 Class Set 2pc", additional_info = "[q]El daño de Pica glacial aumenta un 16% y explota cuando destroza a un objetivo congelado, lo que inflige un 15% de su daño infligido a los enemigos cercanos. Inflige menos daño a partir de 8 objetivos."}
MultiLanguageSpellData['mx'][422885] = {name = "Mage Frost 10.2 Class Set 4pc", additional_info = "[q]Lanzar Pica glacial tiene un 40% de probabilidad de activar Congelación cerebral."}
MultiLanguageSpellData['mx'][422886] = {name = "Monk Brewmaster 10.2 Class Set 2pc", additional_info = "[q]Aliento de fuego inflige un 40% más de daño como daño de pirosombra y hace que sanes por un 50% de todo el daño de fuego infligido."}
MultiLanguageSpellData['mx'][422887] = {name = "Monk Brewmaster 10.2 Class Set 4pc", additional_info = "[q]Tus ataques contra objetivos bajo el efecto de Aliento de fuego tienen una probabilidad de infligir un 15% más de daño como pirosombra, y cada Brebaje celestial también otorga una absorción de Aplazar igual al 100% del daño de pirosombra que has infligido, lo que hace que el daño demorado de Aplazar sea anulado."}
MultiLanguageSpellData['mx'][422889] = {name = "Monk Mistweaver 10.2 Class Set 2pc", additional_info = "[q]Niebla renovadora aplica Armonía de chi a su objetivo inicial, lo que aumenta un 25% la sanación que recibe de ti durante 8 s."}
MultiLanguageSpellData['mx'][422890] = {name = "Monk Mistweaver 10.2 Class Set 4pc", additional_info = "[q]Un 20% de la sanación que realizas a objetivos con Armonía de chi se almacena y luego se dispersa de forma equitativa entre tus aliados con Niebla renovadora cuando Armonía de chi se desvanece o se renueva."}
MultiLanguageSpellData['mx'][422891] = {name = "Monk Windwalker 10.2 Class Set 2pc", additional_info = "Aproximadamente 2.5 activaciones por minuto\n[q]Las Patadas giratorias de la grulla que no tienen costo otorgan Refuerzo oscuro, lo que aumenta un 250% el daño de tu siguiente Patada oscura. Las habilidades cuerpo a cuerpo tienen una probabilidad otorgarte Refuerzo oscuro."}
MultiLanguageSpellData['mx'][422892] = {name = "Monk Windwalker 10.2 Class Set 4pc", additional_info = "[q]Las Patadas oscuras potenciadas por Refuerzo oscuro reducen 3.0 s el tiempo de reutilización de Puños de furia, Patada del sol naciente, Golpe del Señor del viento y Puñetazo de dragón giratorio.\n Aumenta un 4% el daño de Puños de furia, Patada del sol naciente, Golpe del Señor del viento y Puñetazo de dragón giratorio."}
MultiLanguageSpellData['mx'][422893] = {name = "Paladin Holy 10.2 Class Set 2pc", additional_info = "[q]Cuando Resplandor de Luz se disipa o se restablece, crea una Reverberación sagrada en su objetivo que sana a un aliado ([108% of Spell Power]) p. o inflige ([96% of Spell Power]) p. de daño a un enemigo durante 8 s. Varios efectos de Reverberación sagrada pueden superponerse hasta un máximo de 6 veces."}
MultiLanguageSpellData['mx'][422894] = {name = "Paladin Holy 10.2 Class Set 4pc", additional_info = "[q]Ahora Amanecer aumenta un 25% la celeridad durante 6 s y reduce su tiempo de reutilización 15 s.\n(250ms de reutilización)"}
MultiLanguageSpellData['mx'][422895] = {name = "Paladin Protection 10.2 Class Set 2pc", additional_info = "[q]Sentencia otorga una acumulación de Santificación, lo que reduce tu daño recibido un 2.0% por acumulación. Al alcanzar 5 acumulaciones, tu siguiente lanzamiento de Consagración se potencia, lo que aumenta un 200% su daño y sanación y un 30% su radio. Las acumulaciones de Santificación se reinician cuando termina tu Consagración potenciada."}
MultiLanguageSpellData['mx'][422896] = {name = "Paladin Protection 10.2 Class Set 4pc", additional_info = "[q]Cuando estás en una Consagración potenciada, tus habilidades tienen una probabilidad de infligir un 40% más de daño o de sanación como fuego."}
MultiLanguageSpellData['mx'][422899] = {name = "Priest Discipline 10.2 Class Set 2pc", additional_info = "[q]El daño de Punición y Penitencia aumenta un 20% y Punición prolonga 2.0 s la duración de una Expiación activa."}
MultiLanguageSpellData['mx'][422900] = {name = "Priest Discipline 10.2 Class Set 4pc", additional_info = "[q]Punición tiene un 100% de probabilidad de lanzarse una vez más durante Pacto de las sombras, lo que inflige ([80% of Spell Power]) p. de daño de las sombras."}
MultiLanguageSpellData['mx'][422901] = {name = "Priest Holy 10.2 Class Set 2pc", additional_info = "[q]Palabra sagrada: serenidad otorga 18 s de Renovar a su objetivo. Palabra sagrada: santificar otorga 6 s de Renovar a los aliados que sana."}
MultiLanguageSpellData['mx'][422902] = {name = "Priest Holy 10.2 Class Set 4pc", additional_info = "[q]La sanación de Renovar tiene una probabilidad de causar que tu próxima Palabra sagrada: santificar o Palabra sagrada: serenidad no consuman una carga al lanzarlas y cuesten un 50% menos de maná. Este efecto acumula hasta 2 cargas."}
MultiLanguageSpellData['mx'][422903] = {name = "Priest Shadow 10.2 Class Set 2pc", additional_info = "[q]Palabra de las sombras: muerte se activa 2 vez más con un 15% de efectividad. Se vuelve a activar 1 vez más con un 15% de efectividad si Portavoz de la muerte está activo o tu objetivo tiene menos de un [[([85% of Spell Power]) + 30]][([85% of Spell Power])]% de salud."}
MultiLanguageSpellData['mx'][422904] = {name = "Priest Shadow 10.2 Class Set 4pc", additional_info = "[q]Cada vez que recibes daño de Palabra de las sombras: muerte, obtienes una acumulación de Tormento de la muerte, lo que aumenta un 225% el daño inicial de tu siguiente lanzamiento de Palabra de las sombras: dolor o un 50% el daño de tu siguiente Fragor de sombra, que se acumula hasta un máximo de 12 veces."}
MultiLanguageSpellData['mx'][422905] = {name = "Rogue Assassination 10.2 Class Set 2pc", additional_info = "[q]Cada 10 p. de energía que gastas, otorga Peste natural, lo que genera un 1.0% de velocidad de ataque y un 1.0% de daño de naturaleza durante 6 s. Pueden superponerse varias aplicaciones de Peste natural, hasta un máximo de 12 veces."}
MultiLanguageSpellData['mx'][422906] = {name = "Rogue Assassination 10.2 Class Set 4pc", additional_info = "[q]Envenenar se potencia y hace que una Explosión venenosa inflija ([90% of Attack Power]) p. de daño de naturaleza a todos los enemigos cercanos cuando se lanza con Envenenar activo. Inflige menos daño a partir de 5 objetivos. Si Explosión venenosa inflige daño a un solo objetivo, aumenta un 30%."}
MultiLanguageSpellData['mx'][422907] = {name = "Rogue Outlaw 10.2 Class Set 2pc", additional_info = "[q]Golpe siniestro tiene un 10% más de probabilidad de golpear una vez más."}
MultiLanguageSpellData['mx'][422908] = {name = "Rogue Outlaw 10.2 Class Set 4pc", additional_info = "[q]Lanzar huesos además restablece una potenciación aleatoria de combate de Lanzar huesos que tengas actualmente."}
MultiLanguageSpellData['mx'][422909] = {name = "Rogue Subtlety 10.2 Class Set 4pc", additional_info = "[q]Tus clones umbríos infligen un 20% de daño aumentado con todos los ataques y te otorgan 2 puntos de combo por clon cuando los invocas."}
MultiLanguageSpellData['mx'][422910] = {name = "Rogue Subtlety 10.2 Class Set 2pc", additional_info = "[q]Usar Eviscerar, Ruptura o Polvo negro tiene una probabilidad de invocar a un clon umbrío que imita tu remate y genera un 70% más de daño de las sombras."}
MultiLanguageSpellData['mx'][422911] = {name = "Shaman Elemental 10.2 Class Set 2pc", additional_info = "[q]Ola primordial también lanza una explosión elemental al objetivo con una efectividad de un 70% y otorga efectos adicionales de las tres explosiones elementales durante 10.0 s."}
MultiLanguageSpellData['mx'][422912] = {name = "Shaman Elemental 10.2 Class Set 4pc", additional_info = "[q]Una Ráfaga de lava quema a tu objetivo y le inflige un 10% más de daño durante 4 s. Además, después de consumir Ola primordial, tus próximos 2 lanzamientos de Ráfaga de lava también golpean hasta a 3 objetivos más afectados por tu Choque de llamas por un 65% del daño normal."}
MultiLanguageSpellData['mx'][422913] = {name = "Shaman Enhancement 10.2 Class Set 2pc", additional_info = "[q]Ola primordial invoca un espíritu feral de relámpago que aumenta un 20% el daño de naturaleza que infliges durante 15 s."}
MultiLanguageSpellData['mx'][422914] = {name = "Shaman Enhancement 10.2 Class Set 4pc", additional_info = "[q]Invocar un espíritu feral reduce el tiempo de reutilización de Ola primordial en 7.0 s."}
MultiLanguageSpellData['mx'][422915] = {name = "Shaman Restoration 10.2 Class Set 2pc", additional_info = "[q]Sanación en cadena, Oleada de sanación y Ola de sanación marcan a su objetivo inicial con un Reservorio de marea, lo que hace que reciba un 15% de toda la sanación de Mareas vivas que inflijas durante 15 s."}
MultiLanguageSpellData['mx'][422916] = {name = "Shaman Restoration 10.2 Class Set 4pc", additional_info = "[q]La sanación de Mareas vivas aumenta un 25%. Si Mareas vivas está activa en el mismo objetivo que Reservorio de marea, su efecto de sanación con el tiempo tiene un 6% de probabilidad de generar un nuevo efecto de Mareas vivas sobre un aliado cercano."}
MultiLanguageSpellData['mx'][422917] = {name = "Warlock Affliction 10.2 Class Set 2pc", additional_info = "[q]Podredumbre de alma inflige un 15% más de daño y dura 4 s más."}
MultiLanguageSpellData['mx'][422918] = {name = "Warlock Affliction 10.2 Class Set 4pc", additional_info = "[q]Podredumbre de alma otorga 3 astillas de fuego umbrío que aumentan un 50% el daño que inflige tu siguiente Rapto maléfico, o un 60% el daño de tu siguiente Semilla de corrupción. Además, las astillas de fuego umbrío hacen que Rapto maléfico extienda 2 s la duración de tus efectos de daño con el tiempo y de Poseer."}
MultiLanguageSpellData['mx'][422919] = {name = "Warlock Demonology 10.2 Class Set 2pc", additional_info = "[q]Consumir un Núcleo demoníaco aplica una Marca de fatalidad que explota después de 20 s e inflige ([268.747% of Spell Power]) p. de daño de las sombras a los enemigos cercanos o [([268.747% of Spell Power]) * (2.25)] p. de daño de las sombras a un solo enemigo. Mano de Gul'dan reduce la duración de tus Marcas de fatalidad 1 s por fragmento de alma gastado."}
MultiLanguageSpellData['mx'][422920] = {name = "Warlock Demonology 10.2 Class Set 4pc", additional_info = "[q]Cuando se termina Marca de fatalidad, tienes una probabilidad de invocar un demonio de la perdición que lanza 5 Salvas de Descarga de fatalidad antes de marcharse. Cada Salva de Descarga de fatalidad inflige [(1.553369999\n * (Poder con Hechizos * 1) * 1 * (1 + Versatilidad)) * 1.169617819] p. de daño de las sombras hasta a 4 enemigos o [((1.553369999\n * (Poder con Hechizos * 1) * 1 * (1 + Versatilidad)) * 1.169617819) * (2.1)] p. de daño de las sombras a un solo enemigo."}
MultiLanguageSpellData['mx'][422921] = {name = "Warlock Destruction 10.2 Class Set 2pc", additional_info = "[q]Las Descargas de fallas dimensionales ahora infligen un 25% del daño infligido a los enemigos cercanos. El daño periódico de Inmolar tiene una probabilidad de otorgar una carga de Falla dimensional."}
MultiLanguageSpellData['mx'][422922] = {name = "Warlock Destruction 10.2 Class Set 4pc", additional_info = "[q]Ahora Falla dimensional puede invocar una poderosa Falla llameante que dispara 20 Descargas abrasadoras que infligen ([56.9622% of Spell Power]) p. de daño de fuego y ([22.793% of Spell Power]) p. de daño de fuego más durante 10 s a los enemigos cercanos."}
MultiLanguageSpellData['mx'][422923] = {name = "Warrior Arms 10.2 Class Set 2pc", additional_info = "Aproximadamente 2 activaciones por minuto\n[q]Aumenta un 30% el daño de Desgarrar, y Muerte súbita se puede activar con el daño de sangrado de Desgarrar."}
MultiLanguageSpellData['mx'][422924] = {name = "Warrior Arms 10.2 Class Set 4pc", additional_info = "[q]Muerte súbita también hace que tu siguiente Ejecutar golpee el suelo con fuerza y activa un Atronar que inflige un 200% más de daño. Además, el objetivo de Ejecutar sangra por un 50% del daño de Ejecutar durante 5 s. Si se vuelve a aplicar este sangrado, el daño restante se aplica al nuevo sangrado.\n(500ms de reutilización)"}
MultiLanguageSpellData['mx'][422925] = {name = "Warrior Fury 10.2 Class Set 2pc", additional_info = "[q]Furia de Odyn inflige un 50% más de daño y hace que tus siguientes 3 Sed de sangre inflijan un 150% más de daño y tengan un 100% más de probabilidad de golpe crítico contra su objetivo principal."}
MultiLanguageSpellData['mx'][422926] = {name = "Warrior Fury 10.2 Class Set 4pc", additional_info = "[q]Los golpes críticos de Sed de sangre reducen 2.5 s el tiempo de reutilización de Furia de Odyn.\n(500ms de reutilización)"}
MultiLanguageSpellData['mx'][422927] = {name = "Warrior Protection 10.2 Class Set 2pc", additional_info = "[q]Consumir ira tiene una probabilidad de hacer que tu siguiente Embate con escudo consuma las acumulaciones de sangrado de tu objetivo, lo que inflige al instante un 40% del daño restante de Heridas profundas y Desgarrar y un 100% del daño de Rugido atronador. Además, reduce tu daño recibido un 10% durante 5 s."}
MultiLanguageSpellData['mx'][422928] = {name = "Warrior Protection 10.2 Class Set 4pc", additional_info = "[q]Por cada efecto de sangrado de un objetivo que hayas consumido, tu daño recibido se reduce un 2% adicional. Cuando Embate con escudo consume un sangrado, el tiempo de reutilización de Atronar se reinicia y el tiempo de reutilización de Rugido atronador se reduce 3.0 s."}
