MultiLanguageSpellData['mx'][423590] = {name = "Ecos de furia", additional_info = "Instante\n[q]Sanción iracunda te otorga Ecos de furia, lo que hace que tu próximo lanzamiento de Veredicto del templario o Tormenta divina inflija daño una segunda vez con un 25% de efectividad. Este efecto no consume Sentencia.\n(100ms de reutilización)"}
