MultiLanguageSpellData['mx'][424616] = {name = "Santificación", additional_info = "Instante\n[q]Sentencia otorga una acumulación de Santificación, lo que reduce tu daño recibido un 2.0% por acumulación. Al alcanzar 5 acumulaciones, tu siguiente lanzamiento de Consagración se potencia, lo que aumenta un 200% su daño y sanación y un 30% su radio. Las acumulaciones de Santificación se reinician cuando termina tu Consagración potenciada."}
