MultiLanguageSpellData['mx'][426603] = {name = "Sueño aletargado", additional_info = "Instante\n[q]Al recibir daño, hay una probabilidad de que florezca un Sueño aletargado que te da un escudo de 2084 p. durante 15 s y hace que un Sueño floreciente marque a un aliado que esté dentro de un radio de 30 m.\n\n Moverse a 5 m de un aliado marcado con un Sueño floreciente hace que el sueño despierte y les otorgue un escudo de 1389 p. a ti y a tu aliado durante 15 s."}
