MultiLanguageSpellData['mx'][429634] = {name = "Poder colosal", additional_info = "[q0]Talento\n[q]Protección\n Poder colosal aumenta un 10% el daño que inflige tu siguiente Demoler, lo que se acumula un máximo de 5 veces.\n\n Embate con escudo otorga una acumulación de Poder colosal, y Revancha otorga una acumulación de Poder colosal si golpea 3 o más objetivos.\n\nArmas\n Poder colosal aumenta un 10% el daño que inflige tu siguiente Demoler, lo que se acumula un máximo de 5 veces.\n\n Golpe mortal otorga una acumulación de Poder colosal, y Rajar otorga una acumulación de Poder colosal si golpea 3 o más objetivos."}
MultiLanguageSpellData['mx'][429635] = {name = "La sombra del coloso", additional_info = "[q]Tu Poder colosal intimida a tus enemigos y aumenta tus probabilidades de golpe crítico y bloqueo crítico un 1% por acumulación durante 6 s contra los enemigos afectados por tu Choque colosal."}
MultiLanguageSpellData['mx'][429636] = {name = "Dominio del coloso", additional_info = "[q0]Talento\n[q]Armas\n Poder colosal ahora se acumula un máximo de 10 veces. Si vas a obtener una acumulación de Poder colosal y ya tienes el máximo de acumulaciones, el tiempo de reutilización de Demoler se reduce\n 2 s.\n\n Los enemigos afectados por Demoler reciben hasta un 10% más de daño de ti y te infligen hasta un 10% menos de daño durante 10 s, según la cantidad de acumulaciones de Poder colosal consumidas por Demoler.\n\nProtección\n Poder colosal ahora se acumula un máximo de 10 veces. Si vas a obtener una acumulación de Poder colosal y ya tienes el máximo de acumulaciones, el tiempo de reutilización de Demoler se reduce\n 4 s.\n\n Los enemigos afectados por Demoler reciben hasta un 20% más de daño de ti y te infligen hasta un 10% menos de daño durante 10 s, según la cantidad de acumulaciones de Poder colosal consumidas por Demoler."}
