MultiLanguageSpellData['mx'][429945] = {name = "[q4]Emblema del despertar de vermis encantado", additional_info = "Hechizo de 3 seg\nHerramientas: Vara de encantamiento con runas\nComponentes:\nPolvo cromático (60), Esquirla vibrante (10), Cristal resonante (2), Dracotista , Emblema del despertar de vermis naciente\nMisión:\nUn último esfuerzo: Las Islas Dragón\nMisión:\nUn último esfuerzo: Cavernas Zaralek y fallas temporales\nMisión:\nUn último esfuerzo: Sueño Esmeralda\n\n[q4]Emblema del despertar de vermis encantado\nSe liga al recogerlo\nComponente de fabricación opcional\n[q2]+30 Dificultad de fórmula:\n[q2]Otorga la siguiente propiedad: Fija el nivel de objeto entre 502 y 515 según la calidad de fabricación.\n[q]Puede usarse con: Recetas de las Islas Dragón para equipamiento épico fabricado con una chispa del despertar.\n[q]\"Un componente poderoso creado por encantadores.\""}
MultiLanguageSpellData['mx'][429946] = {name = "Jaula de las sombras", additional_info = "Rango ilimitado\nInstante\n[q]El coloso oscuro envuelve a varios jugadores en sombras que, después de 4 s, hacen erupción e infligen 362618 p. de daño de las sombras a los jugadores en un radio de 5 m.\n\n Los jugadores que están en la zona de erupción quedan aturdidos y sufren 36262 p. de daño de las sombras cada 2 s."}
MultiLanguageSpellData['mx'][429947] = {name = "[q4]Emblema del despertar de Aspecto encantado", additional_info = "Hechizo de 3 seg\nHerramientas: Vara de encantamiento con runas\nComponentes:\nPolvo cromático (80), Esquirla vibrante (15), Cristal resonante (4), Dracotista (2), Emblema del despertar de Aspecto naciente\nMisión:\nUn último esfuerzo: Las Islas Dragón\nMisión:\nUn último esfuerzo: Cavernas Zaralek y fallas temporales\nMisión:\nUn último esfuerzo: Sueño Esmeralda\n\n[q4]Emblema del despertar de Aspecto encantado\nSe liga al recogerlo\nComponente de fabricación opcional\n[q2]+50 Dificultad de fórmula:\n[q2]Otorga la siguiente propiedad: Fija el nivel de objeto entre 512 y 525 según la calidad de fabricación.\n[q]Puede usarse con: Recetas de las Islas Dragón para equipamiento épico fabricado con una chispa del despertar.\n[q]\"Un componente poderoso creado por encantadores.\""}
MultiLanguageSpellData['mx'][429948] = {name = "[q4]Emblema del despertar de vástago encantado", additional_info = "Hechizo de 3 seg\nHerramientas: Vara de encantamiento con runas\nComponentes:\nPolvo cromático (30), Esquirla vibrante (5), Cristal resonante , Emblema del despertar de vástago naciente\nMisión:\nUn último esfuerzo: Las Islas Dragón\nMisión:\nUn último esfuerzo: Cavernas Zaralek y fallas temporales\nMisión:\nUn último esfuerzo: Sueño Esmeralda\n\n[q4]Emblema del despertar de vástago encantado\nSe liga al recogerlo\nComponente de fabricación opcional\n[q2]+160 Dificultad de fórmula:\n[q2]Otorga la siguiente propiedad: Fija el nivel de objeto entre 473 y 486 según la calidad de fabricación.\n[q]Puede usarse con: Recetas de las Islas Dragón para la mayoría de los equipos raros (azules).\n[q]\"Un componente poderoso creado por encantadores.\""}
