MultiLanguageSpellData['mx'][431038] = {name = "Maestría de pirofrío", additional_info = "[q0]Talento\n[q]Tus hechizos de fuego que infligen daño generan 1 acumulación de Maestría de fuego y tus hechizos de Escarcha que infligen daño generan 1 acumulación de Maestría de escarcha.\n\n Maestría de fuego aumenta un 2% tu celeridad y Maestría de escarcha aumenta un 2% tu maestría durante 14 s. Cada una se acumula hasta 6 veces.\n\n Añadir acumulaciones no restablece la duración."}
MultiLanguageSpellData['mx'][431039] = {name = "Maestría de escarcha", additional_info = "Instante\n[q]Tus hechizos de fuego que infligen daño generan 1 acumulación de Maestría de fuego y tus hechizos de Escarcha que infligen daño generan 1 acumulación de Maestría de escarcha.\n\n Maestría de fuego aumenta un 2% tu celeridad y Maestría de escarcha aumenta un 2% tu maestría durante 14 s. Cada una se acumula hasta 6 veces.\n\n Añadir acumulaciones no restablece la duración."}
MultiLanguageSpellData['mx'][431040] = {name = "Maestría de fuego", additional_info = "Instante\n[q]Tus hechizos de fuego que infligen daño generan 1 acumulación de Maestría de fuego y tus hechizos de Escarcha que infligen daño generan 1 acumulación de Maestría de escarcha.\n\n Maestría de fuego aumenta un 2% tu celeridad y Maestría de escarcha aumenta un 2% tu maestría durante 14 s. Cada una se acumula hasta 6 veces.\n\n Añadir acumulaciones no restablece la duración."}
