MultiLanguageSpellData['mx'][432117] = {name = "Singularidad cósmica", additional_info = "{100 p. de energía} {Alcance de 175 m}\nHechizo de 7 seg 6 seg de reutilización\n[q]Ki'katal, la Cosechadora atrae a todos los jugadores y comienza a crear una distorsión espacial. Cuando la canalización termina, todos los jugadores que están en un radio de 10 m sufren 7273348 p. de daño de las sombras y son repelidos."}
