MultiLanguageSpellData['mx'][432451] = {name = "Huevos nerubianos", additional_info = "Instante\n[q]Los huevos nerubianos explotan con el contacto y generan telarañas. Las telarañas reducen la velocidad de movimiento un 50% y hacen aparecer periódicamente emboscadores mientras estás en ellas."}
MultiLanguageSpellData['mx'][432452] = {name = "Frasco sañoso de bola de demolición", additional_info = "Instante\n[q]Los golpes de gracia aumentan un 8% el daño que infliges y un 4% el daño que recibes durante 20 s. Se acumula hasta 5 veces. Si te asesinan mientras está activo este efecto, tu atacante toma una parte de este poder.\n\n Aumenta un 15% el honor recibido.\n\nDura 1 h y persiste después de la muerte. Consumir un frasco idéntico añade 1 h más."}
