MultiLanguageSpellData['mx'][432596] = {name = "Salva de caos", additional_info = "Rango ilimitado\nInstante\n[q]Demonología\nGastar un fragmento de alma en un hechizo de daño otorga Ritual diabólico durante 20 s. Mientras Ritual diabólico está activo, cada fragmento de alma gastado en un hechizo de daño reduce 1 s su duración.\n\n Cuando Ritual diabólico expira, obtienes Arte demoníaco, lo que hace que tu siguiente Mano de Gul'dan invoque un señor supremo, una madre del caos o un señor del foso para desatar un ataque devastador contra tus enemigos.\n\nDestrucción\nLanzar Descarga de caos, Lluvia de fuego o Quemadura de las sombras otorga Ritual diabólico durante 20 s. Si Ritual diabólico ya está activo, su duración se reduce 1 s.\n\n Cuando Ritual diabólico expira, obtienes Arte demoníaco, lo que hace que tu siguiente Descarga de caos, Lluvia de fuego o Quemadura de las sombras invoque un señor supremo, una madre del caos o un señor del foso para desatar un ataque devastador contra tus enemigos."}
MultiLanguageSpellData['mx'][432597] = {name = "Golpe vil", additional_info = "Alcance de 10 m\nHechizo de 1 seg\n[q]El sátiro golpea a su objetivo con cuchillas imbuidas de energía vil y le inflige 10 p. de daño de fuego."}
MultiLanguageSpellData['mx'][432598] = {name = "Barrido", additional_info = "{Instante} {3 seg de reutilización}\n[q]Realiza un barrido a los enemigos cercanos que inflige un 12% de su salud máxima como daño físico."}
