MultiLanguageSpellData['mx'][432602] = {name = "Bendición de invierno", additional_info = "{1% del maná base} {Alcance de 40 m}\n{Instante} {45 seg de reutilización}\n[q]Bendice a un sanador aliado durante 30 s, lo que restaura un 1% de maná cada 2 s.\n\nBendición de las estaciones: Se convierte en la Bendición de primavera después de utilizarla.\n(500ms de reutilización)"}
MultiLanguageSpellData['mx'][432603] = {name = "Granizo negro", additional_info = "Rango ilimitado\nInstante\n[q]Bombardea el área con cometas negros e inflige 4848899 p. de daño de las sombras a los enemigos en un radio de 4.5 m de cada impacto."}
