MultiLanguageSpellData['mx'][432768] = {name = "Forma feérica", additional_info = "{Instante} {16 seg de reutilización}\n[q]- Beneficio al taumaturgo\n- Elimina el control de masas\n- Movilidad\n\nTiempo de reutilización de 16 s\n Te transformas en una criatura feérica con inmunidad a los perjuicios dañinos y más velocidad de movimiento durante un período breve.\n\n No puedes atacar mientras dura la transformación."}
MultiLanguageSpellData['mx'][432769] = {name = "Forma feérica", additional_info = "{Instante} {14 seg de reutilización}\n[q]- Beneficio al taumaturgo\n- Elimina el control de masas\n- Movilidad\n\nTiempo de reutilización de 14 s\n Te transformas en una criatura feérica con inmunidad a los perjuicios dañinos y más velocidad de movimiento durante un período breve.\n\n No puedes atacar mientras dura la transformación."}
