MultiLanguageSpellData['mx'][432772] = {name = "Crisálida de chi", additional_info = "Alcance de 40 m\nInstante\n[q]Recibes una descarga de energía que potencia el siguiente hechizo que lances:\n\nNiebla envolvente : Sana ([312% of Spell Power]) p. de inmediato y su lanzamiento es instantáneo.\nNiebla renovadora : La duración aumenta 10 s.\nVivificar : No cuesta maná.\nPatada del sol naciente : Reduce 9 s el tiempo de reutilización.\nExpulsar daño : Convierte un 25% más de sanación en daño y crea una Crisálida de chi que absorbe [[Total Health] * 16 / 100 * (1 + Versatilidad)] p. de daño. [ Té de enfoque del trueno : Relámpago crepitante de jade : La repulsión se aplica de inmediato.\nRodar : Restituye una carga y te sana ([240% of Attack Power]) p ]"}
MultiLanguageSpellData['mx'][432774] = {name = "Cruce vil", additional_info = "Alcance de 8 m\nHechizo de 1.5 seg\n[q]Golpea al objetivo con cuchillas imbuidas de energía vil e inflige 10 p. de daño de fuego."}
MultiLanguageSpellData['mx'][432775] = {name = "Manantial congelado", additional_info = "Alcance de 100 m\n{Instante} {2 min de reutilización}\n[q]Imbuye tus habilidades con los poderes del globo para obtener 50 cargas de Manantial congelado. Infligir daño consume una carga que inflige 23 p. más de daño de escarcha y aplica Escarcha del manantial, lo que reduce la velocidad de movimiento del enemigo un 2% por acumulación.\n\n Cuando Manantial congelado se consume por completo, todos los objetivos afectados con Escarcha del manantial estallan, lo que inflige 76 p. de daño de escarcha por acumulación dividido entre todos los objetivos cercanos."}
MultiLanguageSpellData['mx'][432777] = {name = "Tomo de poder inestable", additional_info = "Aproximadamente 1.5 activaciones por minuto\n[q]Tus hechizos que infligen daño tienen una probabilidad de crear de 1 a 3 ilusiones arcanas de ti mismo que canalizan durante 3 s antes de desatar Tromba arcana en la ubicación de tu objetivo para infligir hasta ( 1343 * 1.1) p. de daño arcano a todos los enemigos que estén en el área."}
MultiLanguageSpellData['mx'][432778] = {name = "Intelecto Arcano", additional_info = "Alcance de 40 m\nInstante\n[q]Imbuye al objetivo con luminosidad y aumenta su intelecto un 5% durante 1 h.\n\n Si el objetivo está en tu grupo o tu banda, también afectará a todos los miembros del grupo o banda."}
