MultiLanguageSpellData['mx'][434151] = {name = "Incitar terror", additional_info = "[q0]Talento\n[q]Profano\n Golpe vampírico y hacen que tus objetivos reciban un 1% más de daño de las sombras, hasta un máximo de 5% durante 15 s.\n\n Golpe vampírico obtiene el beneficio de Incitar terror con un 400% de efectividad.\n\nSangre\n Golpe vampírico y Golpe en el corazón hacen que tus objetivos reciban un 1% más de daño de las sombras, hasta un máximo de 5% durante 15 s.\n\n Golpe vampírico obtiene el beneficio de Incitar terror con un 400% de efectividad."}
MultiLanguageSpellData['mx'][434152] = {name = "Don de los San'layn", additional_info = "[q0]Talento\n[q]Sangre\n Cuando Arma de runa danzante está activa, obtienes Don de los San'layn.\n\n Don de los San'layn aumenta un 200% la efectividad de tu Esencia de la Reina de Sangre, y Golpe vampírico reemplaza a tu Golpe en el corazón mientras dure la habilidad.\n\nProfano\n Cuando Transformación oscura está activa, obtienes Don de los San'layn.\n\n Don de los San'layn aumenta un 100% la efectividad de tu Esencia de la Reina de Sangre, y Golpe vampírico reemplaza a tu mientras dure la habilidad."}
MultiLanguageSpellData['mx'][434153] = {name = "Don de los San'layn", additional_info = "Instante\n[q]Sangre\nCuando Arma de runa danzante está activa, obtienes Don de los San'layn.\n\n Don de los San'layn aumenta un 200% la efectividad de tu Esencia de la Reina de Sangre, y Golpe vampírico reemplaza a tu Golpe en el corazón mientras dure la habilidad.\n\nProfano\nCuando Transformación oscura está activa, obtienes Don de los San'layn.\n\n Don de los San'layn aumenta un 100% la efectividad de tu Esencia de la Reina de Sangre, y Golpe vampírico reemplaza a tu mientras dure la habilidad."}
MultiLanguageSpellData['mx'][434155] = {name = "Hojas fásicas", additional_info = "Rango ilimitado\nInstante\n[q]Sikran marca a los jugadores y se abalanza sobre cada uno de los objetivos marcados, lo que inflige 3741605 p. de daño físico a todos los que encuentra en su camino.\n\n Además, reduce un 50% la sanación que reciben los jugadores golpeados e inflige 474896 p. más de daño de las sombras cada 2 s durante 20 s.\n\n Los objetivos marcados dejan un Simulacro cósmico cuando los golpean."}
