MultiLanguageSpellData['mx'][435103] = {name = "Corcel del viento elegante", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Los corceles del viento son extremadamente gentiles y fáciles de entrenar... si logras atraparlos.\"\nEvento de mundo:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['mx'][435105] = {name = "Misión de seguimiento", additional_info = nil}
MultiLanguageSpellData['mx'][435107] = {name = "Corcel del viento del bosque", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"El pelaje de este corcel del viento no solo tiene el color de su hogar forestal, también suele tener pedazos de corteza y hojas.\"\nEvento de mundo:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['mx'][435108] = {name = "Corcel del viento de tormenta matutina", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Se dice que cuando un relámpago cae sobre el sol, una brillante bestia con roja armadura baja de los cielos. El corcel del viento de tormenta matutina nunca ha escuchado estas leyendas y ha estado siempre aquí.\"\nEvento de mundo:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['mx'][435109] = {name = "Surfeaviento emplumado", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Revise la velocidad del viento y la elevación actuales antes de montar. Evite árboles y objetos altos. No se realizarán devoluciones o reembolsos por cometas dañadas”. - Manual de instrucciones para surfeavientos\nEvento de mundo:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['mx'][435110] = {name = "Extracción", additional_info = nil}
MultiLanguageSpellData['mx'][435114] = {name = "Sin dueño", additional_info = nil}
MultiLanguageSpellData['mx'][435115] = {name = "Quilen guardián", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Cuando Quan el Implacable cayó en batalla, sus leales sabuesos esperaron su regreso. Han pasado miles de años, y aún esperan con paciencia.\"\nEvento de mundo:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['mx'][435118] = {name = "Quilen de mármol", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Creada por un hechicero mogu que le dio vida a su roca mascota favorita.\"\nEvento de mundo:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['mx'][435119] = {name = "Remolino de telaraña", additional_info = "Alcance de 300 m\nInstante\n[q]Ulgrax escupe telarañas a un jugador y a sus aliados en un radio de 10 m, lo que inflige 17331401 p. de daño de naturaleza que se dividen equitativamente entre todos los jugadores y los ata a Ulgrax.\n\n Los jugadores atados sufren 575632 p. de daño de naturaleza cada 2 s y son atraídos hacia Ulgrax. La fuerza con la que Ulgrax atrae a los jugadores se reduce con cada jugador atado."}
MultiLanguageSpellData['mx'][435123] = {name = "Grulla de montar dorada", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Se dice que, una vez, un emperador pagó una gran suma por una grulla de oro. Cuando descubrió que la grulla tan solo estaba pintada para parecerse al precioso metal, se escondió en su recámara durante una semana.\"\nEvento de mundo:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['mx'][435124] = {name = "Grulla de montar lujosa", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Un ave majestuosa, pero bastante quisquillosa con la comida.\"\nEvento de mundo:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['mx'][435125] = {name = "Grulla de montar tropical", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Los habitantes nativos del Bosque de Jade usan sus colores para camuflarse.\"\nEvento de mundo:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['mx'][435126] = {name = "Grulla de montar plateada", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Esta ave tan alta es una de las grullas más agraciadas y elegantes, un poco más que la grulla de bronce, pero no tanto como la grulla dorada.\"\nEvento de mundo:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['mx'][435127] = {name = "Grulla de montar rosa", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Esta ave brillante y colorida suele confundirse con un flamenco o un marabú.\"\nEvento de mundo:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['mx'][435128] = {name = "Grulla de montar pálida", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Y miré, y vi... ¿una grulla blanca?\"\nEvento de mundo:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['mx'][435129] = {name = "Sazón del chef", additional_info = "Alcance de 100 m\nInstante\n[q]El chef condimenta a todos los jugadores con sal, lo que inflige 4 p. de daño físico cada 1.5 s y aumenta todo el daño recibido un 10% durante 9 s.\n\n Este efecto se acumula."}
MultiLanguageSpellData['mx'][435130] = {name = "Sazón del chef", additional_info = "Alcance de 100 m\nInstante\n[q]El chef condimenta a todos los jugadores con sal, lo que inflige 4 p. de daño físico cada 1.5 s y aumenta todo el daño recibido un 10% durante 9 s.\n\n Este efecto se acumula."}
MultiLanguageSpellData['mx'][435131] = {name = "Cabra de montar nevada", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Las cabras montesas de la Cima Kun-Lai son famosas por escalar las cumbres más altas en busca de frijoles de kafa y sal para lamer.\"\nEvento de mundo:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['mx'][435132] = {name = "¡Cómeme!", additional_info = nil}
MultiLanguageSpellData['mx'][435133] = {name = "Cabrita de montar roja", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Lo que a esta cabra la falta en tamaño, le sobra en tenacidad.\"\nEvento de mundo:\nMists of Pandaria: Remix"}
MultiLanguageSpellData['mx'][435134] = {name = "¡Cómeme!", additional_info = nil}
