MultiLanguageSpellData['mx'][435136] = {name = "Latigazo venenoso", additional_info = "Alcance de 20 m\nHechizo de 2 seg\n[q]Ulgrax lanza veneno a todos los jugadores e inflige 1726895 p. de daño de naturaleza y 978574 p. de daño de naturaleza más cada 1 s durante 6 s."}
MultiLanguageSpellData['mx'][435138] = {name = "Ácido digestivo", additional_info = "Alcance de 300 m\nHechizo de 2 seg\n[q]Ulgrax vomita Ácido digestivo sobre varios jugadores, que inflige 1726895 p. de daño de naturaleza cada 2 s durante 6 s.\n\n Cuando se elimina, el veneno sale expulsado de la piel de la víctima, inflige 1151263 p. de daño de naturaleza a los jugadores que están en un radio de 7 m y disuelve las telarañas que haya dejado Red de acechador ."}
MultiLanguageSpellData['mx'][435140] = {name = "Into the Machine - Abandon", additional_info = nil}
MultiLanguageSpellData['mx'][435141] = {name = "Pacto del Libramorte", additional_info = "[q]Cuando sufres un efecto dañino equivalente al 2% de tu salud máxima, instantáneamente lanzas Pacto de la muerte con un 25% de efectividad. Solo puede ocurrir cada 50 min.\n\n Cuando una Marca de la parca explota, los tiempos de reutilización de este efecto y de Pacto oscuro se reducen 25 s."}
MultiLanguageSpellData['mx'][435142] = {name = "Into the Machine - Abandon - Teleport", additional_info = nil}
MultiLanguageSpellData['mx'][435143] = {name = "Hojas fásicas", additional_info = "Rango ilimitado\nCanalizado (Hechizo de 1.5 seg)\n[q]Sikran marca a los jugadores y se abalanza sobre cada uno de los objetivos marcados, lo que inflige 3741605 p. de daño físico a todos los que encuentra en su camino.\n\n Además, reduce un 50% la sanación que reciben los jugadores golpeados e inflige 474896 p. más de daño de las sombras cada 2 s durante 20 s.\n\n Los objetivos marcados dejan un Simulacro cósmico cuando los golpean."}
MultiLanguageSpellData['mx'][435144] = {name = "Fragmentos empaladores", additional_info = "[q]Cada vez que el escudo de Permaescarcha recibe daño, tiene una probabilidad de esparcir fragmentos helados a los enemigos cercanos, infligirles ([5% of Attack Power]) p. de daño de escarcha y reducir un 5% el daño que te infligen los objetivos durante 5 s."}
MultiLanguageSpellData['mx'][435145] = {name = "Vociferador de cielos sangriento", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Este dinosaurio aún alberga la furia de sus ancestros durante la invasión zandalari.\"\nEvento de mundo:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['mx'][435146] = {name = "Pterrorala nocturno", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Los eruditos interpretan el chirrido infernal de esta criatura como \"¡témanme, soy la noche!\"\"\nEvento de mundo:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['mx'][435147] = {name = "Pterrordáctilo de jade", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Esta montura, la favorita de los zandalari, canta muy bien, o eso piensa.\"\nEvento de mundo:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['mx'][435148] = {name = "Golpe abrasador", additional_info = "Alcance de 8 m\nHechizo de 1.5 seg\n[q]Inflige 4848899 p. de daño sagrado y 484890 p. más de daño sagrado cada 1 s durante 10 s."}
MultiLanguageSpellData['mx'][435149] = {name = "Gigante de cobalto", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Lo que comenzó siendo una máquina minera y maderera que se podía montar se convirtió en caos cuando los ingenieros se preguntaron si podían hacer que fuera más genial.\"\nEvento de mundo:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['mx'][435150] = {name = "Gigante férreo vil", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Esta máquina de guerra fue robada de una línea temporal en la que Garrosh Grito Infernal se unió a la Legión Ardiente. No hace falta decir que esa línea temporal ya casi no existe.\"\nEvento de mundo:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['mx'][435151] = {name = "Ojo del enjambre", additional_info = "Rango ilimitado\nInstante\n[q]Al alcanzar 100 p. de energía, Anub’zekt invoca un enjambre gigantesco para que rodeen la arena. Cuando están dentro del enjambre de insectos picadores, los jugadores obtienen acumulaciones de Enjambre implacable rápidamente."}
MultiLanguageSpellData['mx'][435152] = {name = "Ácido digestivo", additional_info = "Alcance de 300 m\nInstante\n[q]Ulgrax vomita Ácido digestivo sobre varios jugadores, que inflige 1726895 p. de daño de naturaleza cada 2 s durante 6 s.\n\n Cuando se elimina, el veneno sale expulsado de la piel de la víctima, inflige 1151263 p. de daño de naturaleza a los jugadores que están en un radio de 7 m y disuelve las telarañas que haya dejado Red de acechador ."}
MultiLanguageSpellData['mx'][435153] = {name = "Tigre de montar del Shadopan púrpura", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Cuando despiertes a un tigre, usa una vara larga. Mejor aún, dile a un amigo que lo despierte por ti\". —Proverbio pandaren\nEvento de mundo:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['mx'][435155] = {name = "Sosteniendo miel ardiente", additional_info = nil}
MultiLanguageSpellData['mx'][435156] = {name = "Expulsión de luz", additional_info = "Alcance de 40 m\nInstante\n[q]Una ráfaga de luz abandona el cuerpo del resucitado y e inflige 1212225 p. de daño sagrado a todos los jugadores en un radio de 60 m."}
MultiLanguageSpellData['mx'][435160] = {name = "Surcarríos Mushan", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"Los mushan son bestias voraces. Es posible domesticarlos, pero demandarán que se les dé un segundo, tercer y hasta un cuarto desayuno todos los días.\"\nEvento de mundo:\nWoW Remix: Mists of Pandaria"}
MultiLanguageSpellData['mx'][435161] = {name = "Bestia mushan cueropálido", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira esta montura.\n[q]\"El mushan cueropálido es la más sabrosa de las bestias mushan, pero odia que se lo recuerden.\"\nEvento de mundo:\nWoW Remix: Mists of Pandaria"}
