MultiLanguageSpellData['mx'][435391] = {name = "[q3]Embellecimiento del iris", additional_info = "Hechizo de 2 seg\nHerramientas: Herramientas de joyero\nComponentes:\nGemas pulverizadas (40), Prisma invertido (5)\nBotín:\nCriaturas de mundo\n\n[q3]Embellecimiento del iris\nJuguete\n[q2]Uso: Concentra un haz de luz de colores a través de una gema hacia una criatura indefensa. (10 Min Reutilización)\n[q]\"El mundo ya es cruel. No tiene por qué ser feo también.\""}
MultiLanguageSpellData['mx'][435393] = {name = "Estabilización", additional_info = "Alcance de 15 mCanalizado (Hechizo de 3 seg) 3 seg de reutilización\nHerramientas: Cronoestabilizador\n[q]Intenta cerrar una falla inestable en el tiempo."}
MultiLanguageSpellData['mx'][435397] = {name = "Palabra de las sombras: dolor", additional_info = "Alcance de 30 m\nInstante\n[q]Hace que enemigos aleatorios en un radio de 30 m sufran 8 p. de daño de las sombras durante 12 s."}
