MultiLanguageSpellData['mx'][435401] = {name = "Exponer", additional_info = "Alcance de 100 m\nHechizo de 1 seg\n[q]Sikran corta a su objetivo, lo que inflige 5756315 p. de daño físico y expone una debilidad que aumenta un 200% el daño físico recibido durante 6 s."}
