MultiLanguageSpellData['mx'][435473] = {name = "Farol permaardor", additional_info = "Aproximadamente 30 activaciones por minuto\n[q]Tus habilidades y hechizos dañinos a distancia tienen una probabilidad alta de avivar la llama del farol, lo que otorga una acumulación de Luz del farol hasta un máximo de 15 veces.\n\n Después de 30 s de obtener acumulaciones, Luz del farol se consume para atraer esa cantidad de luciérnagas que cargan y explotan contra el próximo objetivo que atacas, lo que inflige ( 1 * 82 ) p. de daño de fuego por luciérnaga."}
MultiLanguageSpellData['mx'][435474] = {name = "Aceleración veloz", additional_info = "Instante\n[q]Increases the caster's attacking and casting speed by 30% for 5 s.\n Increases the movement speed of the caster by 50% for 5 s."}
MultiLanguageSpellData['mx'][435475] = {name = "Trampa abisal", additional_info = "{Instante} {1 min de reutilización}\n[q]Coloca una trampa abisal a tus pies. Cuando un enemigo se acerca a menos de 3 metros, crea una burbuja de agua gigante durante 10 s. Todos los enemigos dentro de la burbuja reciben ( 1 * 105 ) p. de daño de escarcha por segundo.\n\n La trampa permanecerá durante 1 min y luego se desactivará automáticamente."}
MultiLanguageSpellData['mx'][435476] = {name = "Temporal Displacement", additional_info = "Instante\n[q]Sientes que te desconectaste de esta línea temporal."}
MultiLanguageSpellData['mx'][435478] = {name = "Artefacto explosivo", additional_info = "Instante\n[q][NYI - Needs trigger] Explode flames outwards in front of you, inflicting 8 Fire damage to any enemy caught in the effect."}
MultiLanguageSpellData['mx'][435479] = {name = "Flauta de fungi fraterno", additional_info = "Aproximadamente 1 activaciones por minuto\n[q]Los hechizos y las habilidades tienen una probabilidad de desenterrar a un fungi fraterno colorido que sana 2437 p. a los aliados, te otorga 237 p. de maná, o inflige [ 555 * (3)] p. de daño de naturaleza durante 3 s a un enemigo cercano.\n(1s de reutilización)"}
MultiLanguageSpellData['mx'][435482] = {name = "Tejedor de cadenas de seda", additional_info = "{Instante} {1 min de reutilización}\n[q]Despliegas una infinidad de telarañas atrapantes en frente de ti que enredan a tus enemigos, lo que reduce un 30% el daño que te infligen hasta 2837 p. de daño total y reduce su velocidad de ataque un 15% durante 15 s.\n\n [La reducción de velocidad de ataque es menos efectiva contra enemigos de nivel 80 o superior.]"}
MultiLanguageSpellData['mx'][435485] = {name = "Bomba de mechaferra", additional_info = "Instante\n[q]¡Tienes una bomba! ¡Rápido, deshazte de ella!"}
MultiLanguageSpellData['mx'][435486] = {name = "Regicidio", additional_info = "Rango ilimitado\nInstante\n[q]Los fantasmas del inframundo se lanzan desde las sombras hacia los jugadores objetivo e infligen 4029421 p. de daño de las sombras a los jugadores que están en su camino."}
MultiLanguageSpellData['mx'][435487] = {name = "Suero de placer ilimitado", additional_info = "{Instante} {1 min de reutilización}\n[q]Consume el suero para aumentar tus sentidos al máximo durante 3 s, lo que te otorga un 100% de reducción de daño hasta un total de X p. de daño.\n Si se reduce el daño de esta forma, lanzarás un contraataque que inflige Y p. de daño físico a tu atacante.\n\n Si lanzas un contraataque durante los primeros 1.5 s del efecto, lanzarás un contraataque perfecto que inflige un 100% más de daño.\n\n Solo puede ocurrir un contraataque o contraataque perfecto por uso."}
