MultiLanguageSpellData['mx'][436456] = {name = "Salto heroico", additional_info = "[q]Aprendes el siguiente hechizo.\n\n Salto heroico\nSalta por los aires hacia una ubicación objetivo y azota el suelo con fuerza destructiva, lo que inflige ([23.5% of Spell Power] + [23.5% of Attack Power]) p. de daño físico a todos los enemigos en un radio de 8 m."}
