MultiLanguageSpellData['mx'][436459] = {name = "Ventaja de arcanista", additional_info = "[q]Tus ataques consumen una parte de tu escudo de absorción para infligir daño arcano equivalente a la cantidad consumida. (Tiempo de reutilización de 10 s)"}
MultiLanguageSpellData['mx'][436460] = {name = "Fervor", additional_info = "[q]Mientras tienes más del 80% de salud, tus ataques consumen salud para infligir una cantidad de daño sagrado equivalente a la cantidad de salud consumida. (Tiempo de reutilización de 1 s)"}
MultiLanguageSpellData['mx'][436461] = {name = "Marca de arrogancia", additional_info = "[q]Los atacantes sufren una Marca de arrogancia que inflige daño de las sombras cada 2 s durante 10 s y se acumula hasta 5 veces."}
MultiLanguageSpellData['mx'][436462] = {name = "Oportunista", additional_info = "[q]Otorga un 50% de probabilidad de golpe crítico durante 4 s después de dañar a un enemigo aturdido."}
MultiLanguageSpellData['mx'][436463] = {name = "Golpe rápido", additional_info = "[q]Tus habilidades cuerpo a cuerpo tienen un 100% de probabilidad de provocar de 4 a 7 ataques automáticos más. (Tiempo de reutilización de 10 s)"}
MultiLanguageSpellData['mx'][436464] = {name = "Matar", additional_info = "[q]Cuando atacas a un enemigo que tiene menos del 10% de salud, intentarás usar Matar, lo que inflige una cantidad de daño de las sombras equivalente al 100% de tu salud máxima.\n\n Solo intentarás Matar a un enemigo una vez."}
