MultiLanguageSpellData['mx'][438593] = {name = "Hora de picotear", additional_info = "Alcance de 100 m\nInstante\n[q]Benk Zumbeja invoca barriles con miel deliciosa. La colisión inflige 12122247 p. de daño físico a los jugadores que están en un radio de 3 m del impacto.\n\n El aroma de la miel atrae a una cenizabeja voraz cada 30 s."}
MultiLanguageSpellData['mx'][438595] = {name = "Fuego excesivo", additional_info = "[q0]Talento\n[q]Fuego\n Lanzar Meteoro hace que tu siguiente Explosión de fuego explote con una Ráfaga de pirofrío que inflige ([265.6% of Spell Power]) p. de daño de pirofrío a los enemigos cercanos. El daño se reduce si golpea a más de 8 objetivos.\n\n Ráfaga de pirofrío reduce 5 s el tiempo de reutilización de Llamas del fénix.\n\nEscarcha\n Lanzar Tormenta de cometas hace que tu siguiente Lanza de hielo explote con una Ráfaga de pirofrío que inflige ([265.6% of Spell Power]) p. de daño de pirofrío a los enemigos cercanos. El daño se reduce si golpea a más de 8 objetivos.\n\n Ráfaga de pirofrío tiene una probabilidad de un 50% de otorgar Congelación cerebral."}
