MultiLanguageSpellData['mx'][439658] = {name = "Distorsión de llama de las sombras", additional_info = "Alcance de ataques cuerpo a cuerpo\nCanalizado (Hechizo de 0 seg)\n[q]Una ira ancestral se combina con el poder de la llama de las sombras para crear distorsiones violentas en el espacio cercano que infligen 3 p. de daño de pirosombra cada 5.2 s a quienes se acerquen demasiado a ellas."}
MultiLanguageSpellData['mx'][439660] = {name = "Distorsión de llama de las sombras", additional_info = "Alcance de ataques cuerpo a cuerpo\nInstante\n[q]Una ira ancestral se combina con el poder de la llama de las sombras para crear distorsiones violentas en el espacio cercano que infligen 3 p. de daño de pirosombra cada 1 s a quienes se acerquen demasiado a ellas."}
