MultiLanguageSpellData['mx'][439668] = {name = "Ídolo de la Madre Tierra", additional_info = "[q]Los hechizos y habilidades de Brann tienen una probabilidad de despertar al ídolo, lo que protege a un jugador herido un 15% de la salud que le falte."}
MultiLanguageSpellData['mx'][439669] = {name = "Ídolo de hierro irrompible", additional_info = "[q]Cuando la salud de cualquier jugador cae por debajo del 40% durante el combate, el ídolo despierta e inflige daño físico moderado a los enemigos cercanos y los provoca durante 4 s. Solo puede ocurrir cada 2 min."}
MultiLanguageSpellData['mx'][439673] = {name = "Tormenta ácida", additional_info = "Rango ilimitado\nCanalizado (Hechizo de 4 seg)\n[q]Nezarox invoca un granizo venenoso durante 4 s y lanza proyectiles que infligen 575632 p. de daño de naturaleza y aplican Veneno persistente a los jugadores que están en un radio de 4 m de cada impacto."}
MultiLanguageSpellData['mx'][439674] = {name = "Ídolo tocado por la luz", additional_info = "[q]Cuando un jugador utiliza una habilidad defensiva con un tiempo de reutilización de 30 s o más, el ídolo se activa y sana al jugador un (100 / 100)% de su salud máxima cada 1 s durante 10 s."}
MultiLanguageSpellData['mx'][439675] = {name = "Invocar a Miral Mitones Mortales", additional_info = "Instante\n[q]Un lince te ayuda en combate."}
