MultiLanguageSpellData['mx'][439680] = {name = "Singularidad cósmica", additional_info = "Alcance de 100 m\nInstante\n[q]Ki'katal, la Cosechadora atrae a todos los jugadores y comienza a crear una distorsión espacial. Cuando la canalización termina, todos los jugadores que están en un radio de 10 m sufren 7273348 p. de daño de las sombras y son repelidos."}
MultiLanguageSpellData['mx'][439683] = {name = "Singularidad cósmica", additional_info = "Alcance de 300 m\nInstante\n[q]Ki'katal, la Cosechadora atrae a todos los jugadores y comienza a crear una distorsión espacial. Cuando la canalización termina, todos los jugadores que están en un radio de 10 m sufren 7273348 p. de daño de las sombras y son repelidos."}
MultiLanguageSpellData['mx'][439686] = {name = "Tajo sombrío", additional_info = "Alcance de 100 m\nInstante\n[q]Nx realiza un corte en la dirección de su objetivo actual, lo que inflige 4848899 p. de daño físico y 4848899 p. de daño de las sombras a los jugadores que están en un cono frente a él y deja una Sombra resonante ."}
MultiLanguageSpellData['mx'][439687] = {name = "Tajo sombrío", additional_info = "Alcance de 100 m\nInstante\n[q]Nx realiza un corte en la dirección de su objetivo actual, lo que inflige 4848899 p. de daño físico y 4848899 p. de daño de las sombras a los jugadores que están en un cono frente a él y deja una Sombra resonante ."}
MultiLanguageSpellData['mx'][439688] = {name = "Reliquia aerodinámica", additional_info = "[q]Mientras están fuera de combate, la velocidad de movimiento del grupo aumenta un 10%. Al entrar en combate, la celeridad del grupo aumenta un 5% durante 8 s."}
MultiLanguageSpellData['mx'][439690] = {name = "Reliquia buscadora arcaica", additional_info = "[q]Cuando Brann usa Herramientas de recolección , hay un 20% de probabilidad de desenterrar un artefacto poderoso que otorga a tu grupo una bendición muy fuerte.\n\n Herramientas de recolección\nBrann utiliza sus herramientas de recolección para ayudar a los jugadores a encontrar más oro, menas, hierbas, pescado, cueros y tesoros."}
