MultiLanguageSpellData['mx'][439763] = {name = "Proceso de eliminación", additional_info = "Alcance de 300 m\nInstante\n[q]Izo reúne todas las anomalías en el lugar donde se encuentra y las aplasta violentamente contra su objetivo una por una, lo que inflige 4848899 p. de daño de las sombras y 5818679 p. de daño físico a los jugadores en un radio de 10 m un total de 3 veces durante 3 s."}
