MultiLanguageSpellData['mx'][439779] = {name = "Hebras de hilera", additional_info = "Rango ilimitado\nInstante\n[q]Rasha'nan lanza redes a los objetivos marcados, lo que inflige 2014711 p. de daño de naturaleza a los jugadores que están en un radio de 0 m, ata a todos los jugadores golpeados y crea Redes pegajosas . La atadura inflige 575632 p. de daño de naturaleza cada 1 s y atrae a la víctima.\n\n Estirar esta atadura 0 m la rompe y crea Hebras rotas de hilera ."}
