MultiLanguageSpellData['mx'][440042] = {name = "Alma oscurecida", additional_info = "[q]Aflicción\n El daño periódico que inflige Corrupción tiene una probabilidad de hacer que el objetivo sufra ([46.9878% of Spell Power]) p. de daño de pirosombra durante 15 s.\n\n Rapto maléfico consume Alma oscurecida e inflige el daño restante de forma instantánea.\n\nDemonología, Destrucción\n El daño periódico que inflige Inmolar tiene una probabilidad de hacer que el objetivo sufra ([46.9878% of Spell Power]) p. de daño de pirosombra durante 15 s.\n\n Descarga de caos consume Alma oscurecida e inflige el daño restante de forma instantánea. El daño que inflige Lluvia de fuego consume 1 s de Alma oscurecida."}
MultiLanguageSpellData['mx'][440043] = {name = "Alma ennegrecida", additional_info = "[q0]Talento\n[q]Gastar fragmentos de alma en hechizos que infligen daño corrompe aún más a los enemigos afectados por tu Marchitar, lo que aumenta su cantidad de acumulaciones en 1.\n\n Cada vez que Marchitar obtiene una acumulación, tiene una probabilidad de colapsar, lo que consume una acumulación cada 1 s e inflige ([76.6411% of Spell Power]) p. de daño de pirosombra a su huésped hasta que queda 1 acumulación."}
MultiLanguageSpellData['mx'][440044] = {name = "Ferocidad de Xalan", additional_info = "[q0]Talento\n[q]Aflicción\n El daño de fuego que infligen tus hechizos y habilidades aumenta un 6% y tus hechizos de fuego obtienen un 10% más de probabilidad de golpe crítico de todas las fuentes.\n\nDestrucción\n El daño de fuego que infligen tus hechizos y habilidades aumenta un 8% y tus hechizos de fuego obtienen un 10% más de probabilidad de golpe crítico de todas las fuentes."}
MultiLanguageSpellData['mx'][440045] = {name = "Marca de Peroth'arn", additional_info = "[q0]Talento\n[q]Destrucción\n El daño infligido por el golpe crítico de Marchitar aumenta un 10%.\n\n Marchitar tiene una probabilidad de ganar una acumulación cuando asesta un golpe crítico. Las acumulaciones obtenidas de esta forma no activan Alma ennegrecida.\n\nAflicción\n El daño infligido por el golpe crítico de Marchitar aumenta un 25%.\n\n Marchitar tiene una probabilidad de ganar una acumulación cuando asesta un golpe crítico. Las acumulaciones obtenidas de esta forma no activan Alma ennegrecida."}
MultiLanguageSpellData['mx'][440046] = {name = "Marca de Xavius", additional_info = "[q0]Talento\n[q][ Agonía : El daño de Agonía aumenta un 20% / El daño de Marchitar aumenta un 25%.]\n Alma ennegrecida inflige un 2% de daño aumentado por cada acumulación de Marchitar."}
MultiLanguageSpellData['mx'][440047] = {name = "Actividad del despertar semanal", additional_info = "Instante\n[q]Completar esta misión puede otorgarte como recompensa una chispa semanal para fabricar objetos.\n\nYa has recibido tu chispa semanal para fabricar objetos."}
