MultiLanguageSpellData['mx'][442495] = {name = "Eclipse", additional_info = "Rango ilimitado\nInstante\n[q]Ky'veza cubre secciones de la sala con olas de oscuridad, lo que inflige 8634473 p. de daño de las sombras a cualquier jugador atrapado dentro."}
MultiLanguageSpellData['mx'][442497] = {name = "Enfrentamiento intenso", additional_info = "[q0]Talento\n[q]Guja de atracador genera 20 p. de furia."}
MultiLanguageSpellData['mx'][442498] = {name = "Contaminación oscura", additional_info = "Rango ilimitado\nInstante\n[q]Aflicción\nEl daño periódico que inflige Corrupción tiene una probabilidad de hacer que el objetivo sufra ([46.9878% of Spell Power]) p. de daño de pirosombra durante 15 s.\n\n Rapto maléfico consume Alma oscurecida e inflige el daño restante de forma instantánea.\n\nDemonología, Destrucción\nEl daño periódico que inflige Inmolar tiene una probabilidad de hacer que el objetivo sufra ([46.9878% of Spell Power]) p. de daño de pirosombra durante 15 s.\n\n Descarga de caos consume Alma oscurecida e inflige el daño restante de forma instantánea. El daño que inflige Lluvia de fuego consume 1 s de Alma oscurecida."}
MultiLanguageSpellData['mx'][442501] = {name = "Cargaférrea tejida", additional_info = "Rango ilimitadoHechizo de 3 seg 5 seg de reutilización\n[q]El taumaturgo desata una ráfaga de telaraña hacia adelante, lo que inflige 1726895 p. de daño de naturaleza a los jugadores golpeados y los repele."}
MultiLanguageSpellData['mx'][442502] = {name = "Hambre de espada de guerra", additional_info = "[q0]Talento\n[q]Venganza\n Cuando consumes un fragmento de alma, tu siguiente inflige ([40% of Attack Power]) p. más de daño físico.\n\nCaos\n Cuando consumes un fragmento de alma, tu siguiente Golpe de caos inflige ([40% of Attack Power]) p. más de daño físico.\n\n Hoja mácula consume un máximo de 5 fragmentos de alma cercanos."}
