MultiLanguageSpellData['mx'][442566] = {name = "Quitina penumbrosa", additional_info = "Alcance de 5 m\nHechizo de 2.5 seg\n[q]Una amplia variedad de insectos de Khaz Algar se ha dedicado a fabricar armaduras parecidas a mallas más resistentes con exoesqueletos quitinosos en lugar de escamas."}
MultiLanguageSpellData['mx'][442567] = {name = "Cuero tormentoso", additional_info = "Alcance de 5 m\nHechizo de 2.5 seg\n[q]Se pueden encontrar muchas criaturas en Khaz Algar. El cuero extraído de ellas se puede utilizar, en grandes cantidades, para fabricar suministros, armaduras y componentes."}
MultiLanguageSpellData['mx'][442569] = {name = "Caparazón de día sombrío", additional_info = "Alcance de 5 m\nHechizo de 2.5 seg\n[q]Al desollar criaturas con quitina, un desollador puede encontrarse con un caparazón de día sombrío magnifico.\n\n Estos caparazones son una muestra de quitina más robusta y completa, y pueden utilizarse para fabricar las piezas más desafiantes."}
MultiLanguageSpellData['mx'][442572] = {name = "Pellejo atronador", additional_info = "Alcance de 5 m\nHechizo de 2.5 seg\n[q]Los desolladores que recolecten cueros de criaturas tienen una pequeña probabilidad de encontrar pieles atronadoras notables.\n\n Este es un material extremadamente raro que puede usarse para todo tipo de proyectos en diversas profesiones."}
MultiLanguageSpellData['mx'][442573] = {name = "Asesinato", additional_info = "Rango ilimitado\nInstante\n[q]El etéreo marca a varios jugadores para asesinarlos. Después de 8 s, el etéreo realiza un paso de las sombras rápido hacia cada objetivo para eviscerarlos. Inflige 4605052 p. de daño de las sombras en un radio de 5 m e inyecta Ruina de la reina.\n\n La figura sombría del etéreo resuena y crea un Fantasma del inframundo en cada ubicación."}
