MultiLanguageSpellData['mx'][442644] = {name = "[q2]Cebo de pez arcoíris especular", additional_info = "Hechizo de 2 seg\nComponentes:\nLeucisco holgazán (2)\nEspecialización:\nFaena - Amigo pescador\n\n[q2]Cebo de pez arcoíris especular\n[q2]Uso: Aumenta la probabilidad de pescar pez arcoíris especular durante 30 min.\nNecesitas ser de nivel 70"}
MultiLanguageSpellData['mx'][442645] = {name = "[q2]Cebo de lobina de río serena", additional_info = "Hechizo de 2 seg\nComponentes:\nPerca sangrienta (2)\nEspecialización:\nFaena - Amigo pescador (10)\n\n[q2]Cebo de lobina de río serena\n[q2]Uso: Aumenta la probabilidad de pescar lobinas de río serenas durante 30 min.\nNecesitas ser de nivel 70"}
MultiLanguageSpellData['mx'][442646] = {name = "[q2]Cebo de lucio dórnico", additional_info = "Hechizo de 2 seg\nComponentes:\nEsturión cristalino (2)\nEspecialización:\nFaena - Amigo pescador (20)\n\n[q2]Cebo de lucio dórnico\n[q2]Uso: Aumenta la probabilidad de pescar lucios dórnicos durante 30 min.\nNecesitas ser de nivel 70"}
MultiLanguageSpellData['mx'][442647] = {name = "[q2]Cebo de pez martillo de Arathor", additional_info = "Hechizo de 2 seg\nComponentes:\nBermejuela bismuto (2)\nEspecialización:\nFaena - Amigo pescador (30)\n\n[q2]Cebo de pez martillo de Arathor\n[q2]Uso: Aumenta la probabilidad de pescar peces martillo de Arathor durante 30 min.\nNecesitas ser de nivel 70"}
MultiLanguageSpellData['mx'][442648] = {name = "[q2]Cebo de buscapescadores atroz", additional_info = "Hechizo de 2 seg\nComponentes:\nLeucisco holgazán , Perca sangrienta , Esturión cristalino , Bermejuela bismuto\nEspecialización:\nFaena - Amigo pescador (40)\n\n[q2]Cebo de buscapescadores atroz\n[q2]Uso: Cubre tu anzuelo con carnada de buscapescadores para garantizar la pesca en cualquier estanque de pesca de las Minas Resonantes o Cristalia.\n\n Esta carnada dura 30 min y se acumula hasta 50 veces.\nNecesitas ser de nivel 70"}
MultiLanguageSpellData['mx'][442649] = {name = "[q3]Infusión: Cristal", additional_info = "Hechizo de 2 seg\nComponentes:\nCebo de criatura esquiva , Polvo cristalino (3)\nEspecialización:\nCebos - Infusor impresionante\n\n[q3]Cebo de criatura cristalina\nSe liga al recogerlo\n[q2]Uso: Coloca la carnada, y al poco tiempo atrae a cualquier criatura esquiva. ¿Quién sabe qué puede aparecer?\n\n Reduce el tiempo de reutilización de carnada para criatura esquiva mediante el desuello de criaturas en Khaz Algar.\n\n Solo se puede usar en exteriores de Khaz Algar.\nNecesitas ser de nivel 70\n[q]\"Una carnada muy tentadora que hace que las criaturas esquivas salgan de su escondite. Infundida con poder cristalino.\""}
MultiLanguageSpellData['mx'][442650] = {name = "[q3]Infusión: Esporas", additional_info = "Hechizo de 2 seg\nComponentes:\nCebo de criatura esquiva , Esporas viridiscentes (3)\nEspecialización:\nCebos - Infusor impresionante (20)\n\n[q3]Cebo para criatura esporafundida\nSe liga al recogerlo\n[q2]Uso: Coloca la carnada, y al poco tiempo atrae a cualquier criatura esquiva. ¿Quién sabe qué puede aparecer?\n\n Reduce el tiempo de reutilización de carnada para criatura esquiva mediante el desuello de criaturas en Khaz Algar.\n\n Solo se puede usar en exteriores de Khaz Algar.\nNecesitas ser de nivel 70\n[q]\"Una carnada muy tentadora que hace que las criaturas esquivas salgan de su escondite. Infundida con esporas mágicas.\""}
MultiLanguageSpellData['mx'][442651] = {name = "[q3]Infusión: Retorcimiento", additional_info = "Hechizo de 2 seg\nComponentes:\nCebo de criatura esquiva , Muestra retorcida\nEspecialización:\nCebos - Infusor impresionante (40)\n\n[q3]Cebo para criatura retorcida\nSe liga al recogerlo\n[q2]Uso: Coloca la carnada, y al poco tiempo atrae a cualquier criatura esquiva. ¿Quién sabe qué puede aparecer?\n\n Reduce el tiempo de reutilización de carnada para criatura esquiva mediante el desuello de criaturas en Khaz Algar.\n\n Solo se puede usar en exteriores de Khaz Algar.\nNecesitas ser de nivel 70\n[q]\"Una carnada muy tentadora que hace que las criaturas esquivas salgan de su escondite. Infundida con una esencia que destila energía maligna.\""}
MultiLanguageSpellData['mx'][442652] = {name = "[q2]Cebo para criatura esquiva", additional_info = "Hechizo de 2 seg\nComponentes:\nSimplemente bife (10)\nEspecialización:\nCebos\n\n[q2]Cebo de criatura esquiva\nSe liga al recogerlo\n[q2]Uso: Coloca la carnada, y al poco tiempo atrae a cualquier criatura esquiva. ¿Quién sabe qué puede aparecer?\n\n Reduce el tiempo de reutilización de carnada para criatura esquiva mediante el desuello de criaturas en Khaz Algar.\n\n Solo se puede usar en exteriores de Khaz Algar.\nNecesitas ser de nivel 70\nRequiereDesuello de Khaz Algar\n(1)\n[q]\"Una carnada muy tentadora que hace que las criaturas esquivas salgan de su escondite.\""}
MultiLanguageSpellData['mx'][442653] = {name = "¿Qué es eso?", additional_info = "Alcance de 18 m\nInstante\n[q]El taumaturgo detecta algo extraño."}
MultiLanguageSpellData['mx'][442654] = {name = "[q2]Aroma de cebo de bestias", additional_info = "Hechizo de 2 seg\nComponentes:\nSimplemente bife (3), Especias granuladas (5)\nEspecialización:\nCebos (20)\n\n[q2]Aroma de cebo de bestias\nSe liga al recogerlo\n[q2]Uso: Abre la botella, lo que deja salir un aroma que inmediatamente atrae a todas las bestias desollables que no estén ocupadas en un radio de 60 m de ti.\n\n Solo se puede usar en exteriores en Khaz Algar. (5 Min Reutilización)\nNecesitas ser de nivel 60\nRequiereDesuello de Khaz Algar\n(1)"}
MultiLanguageSpellData['mx'][442655] = {name = "[q4]Cebo de bestia suprema", additional_info = "Hechizo de 2 seg\nComponentes:\nCaldo de carne condimentada\nEspecialización:\nCebos - Maestría en rastreo (40)\n\n[q4]Cebo de bestia suprema\nSe liga al recogerlo\n[q2]Uso: Coloca el cebo y haz que una criatura elusiva suprema salga de su escondite.\n\n Solo se puede usar en los Páramos Rugientes, dentro de las Minas Resonantes.\nNecesitas ser de nivel 70\nRequiereDesuello de Khaz Algar\n(1)\n[q]\"Un cebo excepcional diseñado y fabricado según especificaciones estrictas para atraer a una bestia poderosa.\""}
