MultiLanguageSpellData['mx'][442792] = {name = "Emblema de terráneo estimado", additional_info = "Aproximadamente 3 activaciones por minuto\n[q]Tus hechizos y habilidades tienen una oportunidad de animar a todos a tu alrededor y otorgar 107 p. de versatilidad divididos entre tú y tus aliados cercanos.\n\n La versatilidad aumenta por cada aliado afectado, hasta un máximo de 5 aliados."}
MultiLanguageSpellData['mx'][442794] = {name = "Festín de carne", additional_info = "Canalizado (Hechizo de 0 seg)\n[q]Disfruta de la carne."}
MultiLanguageSpellData['mx'][442795] = {name = "Desborde sanguinario", additional_info = nil}
MultiLanguageSpellData['mx'][442799] = {name = "Desborde sanguinario", additional_info = "Alcance de 300 m\nInstante\n[q]El contenido de la lata de sangre negra gotea en el suelo de la sala y forma un charco que crece lentamente. Cada 0.5 s, el charco inflige 287816 p. de daño de las sombras y absorbe los próximos 490734 p. de sanación recibidos a los jugadores que están bajo este efecto.\n\n Los huevos experimentales que tocan un charco activan una Reacción cáustica ."}
MultiLanguageSpellData['mx'][442801] = {name = "Mecha de fuego salvaje", additional_info = "Alcance de 50 m\nInstante\n[q]Tus ataques cuerpo a cuerpo tienen una probabilidad de prender fuego al objetivo, lo que inflige ( 53 * 11) p. de daño de fuego durante 11 s.\n\n Activar este efecto cuando el objetivo ya está ardiendo renueva la duración y también hace que se propague a un enemigo cercano."}
MultiLanguageSpellData['mx'][442802] = {name = "Desborde sanguinario", additional_info = "Alcance de 300 m\nInstante\n[q]Cuando Desborde sanguinario toca algún huevo, hace que eclosione y causa una mutación en la criatura en su interior."}
MultiLanguageSpellData['mx'][442804] = {name = "Maldición del sátiro", additional_info = "{1% del maná base} {Alcance de 40 m}\nInstante\n[q]Aumenta un 20% el tiempo entre los ataques del enemigo y un 30% el tiempo de lanzamiento de todos los hechizos durante 2 min.\n\nMaldición: Un brujo solo puede tener una Maldición activa por objetivo."}
