MultiLanguageSpellData['mx'][443445] = {name = "Comunicación rutinaria", additional_info = "[q0]Talento\n[q]Elemental\n Los lanzamientos de Descarga de relámpagos, Ráfaga de lava, Cadena de relámpagos, Hielofuria y Choque de escarcha tienen un 8% de probabilidad de invocar a un ancestro a tu lado durante 6 s.\n\nRestauración\n Mareas vivas tiene un 15% de probabilidad de invocar a un ancestro a tu lado durante 6 s."}
MultiLanguageSpellData['mx'][443446] = {name = "Llamado final", additional_info = "[q0]Talento\n[q]Elemental\n Cuando un ancestro parte, lanza Explosión elemental sobre un enemigo cercano.\n\nRestauración\n Cuando un ancestro parte, lanza Hidroburbuja sobre un aliado herido cercano.\n\n Hidroburbuja\nEnvuelve a tu objetivo con una burbuja de agua protectora durante 15 s.\n\n El escudo absorbe los próximos 0 p. de daño entrantes, pero el monto de absorción decae completamente a lo largo de su duración."}
MultiLanguageSpellData['mx'][443447] = {name = "Supremacía de vorágine", additional_info = "[q0]Talento\n[q]Elemental\n Aumenta un 25% el daño de Choque de tierra, Explosión elemental y Terremoto.\n\n Aumenta la sanación de Oleada de sanación y Sanación en cadena un 25%.\n\nRestauración\n Aumenta un 25% la sanación de Ola de sanación, Oleada de sanación, Manantial, Diluvio y Sanación en cadena."}
MultiLanguageSpellData['mx'][443448] = {name = "Capacidad primordial", additional_info = "[q0]Talento\n[q]Elemental\n Aumenta tu Vorágine máxima en 25 p.\n\nRestauración\n Aumenta tu maná máximo un 10%.\n\n Maremotos ahora se puede acumular hasta 4 veces."}
