MultiLanguageSpellData['mx'][443450] = {name = "Llamada de los ancestros", additional_info = "[q0]Talento\n[q]Restauración\n Obtener el beneficio de Ondulación llama a un ancestro para que te acompañe durante 6 s.\n\n Lanzar Desatar vida llama a un ancestro para que te acompañe durante 12 s.\n\n Cada vez que lanzas un hechizo de sanación o daño, el ancestro lanzará un hechizo similar.\n\nElemental\n Ola primordial llama a un ancestro para que te acompañe durante 6 s. Cada vez que lanzas un hechizo de sanación o daño, el ancestro lanzará un hechizo similar."}
MultiLanguageSpellData['mx'][443451] = {name = "Ofrenda del más allá", additional_info = "[q0]Talento\n[q]Elemental\n Cuando se invoca a un ancestro, el tiempo de reutilización de Elemental de fuego y Elemental de tormenta se reduce 5 s.\n\nRestauración\n Cuando se invoca a un ancestro, el tiempo de reutilización de Mareas vivas se reduce 3 s."}
