MultiLanguageSpellData['mx'][443455] = {name = "Plegaria de furia purgada", additional_info = "Instante\n[q]La próxima vez que recibas un golpe, liberarás Furia purgada .\n\nFuria purgada :\nInflige 2625000 p. de daño físico a los enemigos en un radio de 8 m y los aturde durante 3 s."}
