MultiLanguageSpellData['mx'][443526] = {name = "Premonición de consuelo", additional_info = "Alcance de 100 m\nInstante\n[q]Tu siguiente hechizo de sanación sobre un solo objetivo le otorga a tu objetivo un escudo que absorbe 0 p. de daño y reduce el daño que recibe un 15% durante 15 s."}
MultiLanguageSpellData['mx'][443527] = {name = "Cera grabada con llamarakon", additional_info = "Aproximadamente 2 activaciones por minuto\n[q]Tus hechizos tienen una probabilidad de imbuir la cera, lo que hace que se convierta en una vela ardiente durante 15 s. Aumenta 122 p. tu versatilidad y aumenta 32 p. más mientras permanezcas bajo su luz."}
