MultiLanguageSpellData['mx'][443529] = {name = "Buril del Rey Vela", additional_info = "Alcance de 40 m\n{Instante} {1.5 min de reutilización}\n[q]Esculpe una copia de cera de tu objetivo, que absorbe un 50% del daño recibido. La absorción calienta la cera, lo que hace que se derrita tras absorber 6705 p. de daño."}
MultiLanguageSpellData['mx'][443530] = {name = "Remanente de oscuridad", additional_info = "Aproximadamente 2 activaciones por minuto\n[q]Tus habilidades tienen una probabilidad de llamar a la oscuridad, lo que aumenta tu [Primary Stat] 19 p., hasta un máximo de ( 19 * 5) p.\n\n Al alcanzar la potencia máxima, la oscuridad se libera e inflige ( 1 * 1789 * 15 / 3) p. de daño de las sombras que se divide entre los enemigos cercanos durante 15 s para luego desvanecerse en el remanente."}
MultiLanguageSpellData['mx'][443531] = {name = "Luz reforzada", additional_info = "{Instante} {2 min de reutilización}\n[q]Levanta tu sello a la luz y aumenta 260 p. tu estadística secundaria más alta durante 20 s. Tu acto inspira a los miembros de tu grupo que tengan un sello, lo que les otorga 7 p. de la misma estadística durante 20 s."}
MultiLanguageSpellData['mx'][443532] = {name = "Atado a la oscuridad", additional_info = "Instante\n[q][ Sangre : Hervor de sangre inflige un 10% más de daño /\n\nEscarcha\nExplosión aullante potenciada con Helada blanca inflige un 60% más de daño a su objetivo principal ] y ahora es de friosombra.\n\n El daño de friosombra aplica 2 acumulaciones a Marca de la parca y 4 acumulaciones cuando es un golpe crítico."}
MultiLanguageSpellData['mx'][443533] = {name = "Tomo de devoción de la Luz", additional_info = "[q]Avanzas hasta los 50 Versos de la resiliencia interior y lees a medida que te atacan.\n Resiliencia interior aumenta 136 p. tu armadura y otorga a tus ataques una probabilidad de invocar un resguardo que absorbe 3376 p. de daño mágico. Cuando terminas, pasas los pasajes hasta llegar a otro capítulo.\n\nVálido solo para especializaciones de tanque.\n(500ms de reutilización)"}
MultiLanguageSpellData['mx'][443534] = {name = "Radiancia", additional_info = "Instante\n[q]Eres radiante, lo que aumenta la efectividad de tu Verso."}
MultiLanguageSpellData['mx'][443535] = {name = "Tomo de devoción de la Luz", additional_info = "{Instante} {1.5 min de reutilización}\n[q]Examina los pasajes del tomo con un aumento de Resplandor ."}
MultiLanguageSpellData['mx'][443536] = {name = "Cristal luminoso llameante", additional_info = "Alcance de 35 m\n{Instante} {2 min de reutilización}\n[q]Invoca a un engendro de luz explosivo que sacrifica su salud para desatar Ráfagas de luz, e inflige 1446 p. de daño sagrado dividido entre los enemigos cercanos cada 2 s mientras viva."}
MultiLanguageSpellData['mx'][443537] = {name = "Piedra del pacto del Vacío", additional_info = "Aproximadamente 2 activaciones por minuto\n[q]Tus ataques tienen una probabilidad de invocar el pacto, lo que causa una explosión que inflige ( 1 * 897 ) p. de daño de las sombras repartidos entre los enemigos cercanos. También aumenta 36 p. tu celeridad durante 10 s.\n\n Si mueres, el pacto se rompe y se produce una explosión violenta."}
MultiLanguageSpellData['mx'][443538] = {name = "Cristal de potenciamiento de Anub'ikkaj", additional_info = "Aproximadamente 1.55 activaciones por minuto\n[q]Tus hechizos y habilidades tienen una probabilidad de liberar un potenciador emergente del cristal, lo que aumenta 131 p. una estadística secundaria aleatoria durante 20 s."}
MultiLanguageSpellData['mx'][443539] = {name = "Campanada de Mereldar", additional_info = "Alcance de 50 m\nInstante\n[q]Libera una descarga de luz sagrada sobre el objetivo que inflige ( 1 * 1368 ) p. de daño sagrado. Los siguientes 5 aliados que ataquen al objetivo recibirán la Bendición de Mereldar, que aumenta 62 p. su versatilidad durante 10 s."}
MultiLanguageSpellData['mx'][443541] = {name = "Sacocría ara-kara", additional_info = "Aproximadamente 2.5 activaciones por minuto\n[q]Tus habilidades tienen una probabilidad de agitar el saco y liberar un huevo que te otorga 15 p. de [Primary Stat]. Cada huevo eclosiona después de 1 min. La nueva cría ataca a tu siguiente objetivo y le inflige ( 1 * 80 * 8 / 1) p. de daño de naturaleza durante 8 s.\n(100ms de reutilización)"}
MultiLanguageSpellData['mx'][443544] = {name = "Módulo refractor de agresión", additional_info = "[q]Tus habilidades de provocación activan la energía refractante del módulo, lo que te protege de un 50% del daño recibido, hasta 7648 p. Esto solo puede ocurrir una vez cada 1 min.\n\nVálido solo para especializaciones de tanque.\n(1m de reutilización)"}
MultiLanguageSpellData['mx'][443545] = {name = "Glándula de Enjambre implacable", additional_info = "Aproximadamente 6 activaciones por minuto\n[q]La glándula libera feromonas que atraen a un Enjambre implacable de insectos que te rodean. Cuando recibes daño, tienes una alta probabilidad de contraatacar a los atacantes, lo que inflige ( 69 * 6 / 1) p. de daño de naturaleza durante 6 s y reduce 96 p. el daño que recibes."}
MultiLanguageSpellData['mx'][443549] = {name = "Edicto del cosechador", additional_info = "Alcance de 100 m\nInstante\n[q]Tus habilidades y hechizos que infligen daño tienen una probabilidad de enviar un orbe de sangre negra volátil que flota hacia tu objetivo y que, al impactar, explota e inflige ( 1 * 1418 ) p. de daño de las sombras repartidos entre todos los enemigos cercanos. Si interceptas el orbe, podrás desviar su poder y aumentar 156 p. tu maestría durante 15 s."}
MultiLanguageSpellData['mx'][443552] = {name = "Oración opresiva", additional_info = "{Instante} {2 min de reutilización}\n[q]Ondea la laringe en el aire para liberar un coro atormentador, que inflige ( 1 * 1480 * 3 / 1) p. de daño de las sombras durante 3 s dividido entre los enemigos cercanos. Tus susurros se unen al coro, lo que aumenta su daño antes de silenciarse."}
MultiLanguageSpellData['mx'][443553] = {name = "Repulsión de Arremetida de alce", additional_info = "Rango ilimitado\nInstante\n[q]Carga hacia el objetivo para así azotarlo y derribarlo."}
MultiLanguageSpellData['mx'][443556] = {name = "Instrumentos de colmillos gemelos", additional_info = "{Instante} {2 min de reutilización}\n[q]Abre la faltriquera y saca la hoja de las sombras de Nx para golpear rápidamente a los enemigos que tengas delante, lo que inflige ( 1 * 585 ) p. de daño de las sombras a todos los enemigos golpeados.\n\n Puedes usar la faltriquera hasta dos veces más durante 20 s antes de que se selle para recargar mágicamente su contenido."}
MultiLanguageSpellData['mx'][443557] = {name = "Coaglam viscoso", additional_info = "[q]Tu sanación excesiva atrae la energía de las sombras cercanas a tu grupo, que se acumula hasta llegar a 213 p. de sanación y restaura la salud del objetivo cuando recibe daño."}
MultiLanguageSpellData['mx'][443558] = {name = "Membrana coagulada", additional_info = "Alcance de 46 m\n{Instante} {1 min de reutilización}\n[q]Canaliza el poder del coaglam y concentra toda la energía de las sombras actual para escudar a tu objetivo."}
MultiLanguageSpellData['mx'][443559] = {name = "Creación con cirros", additional_info = "Aproximadamente 2 activaciones por minuto\n[q]Tus hechizos tienen una probabilidad de inspirarte a experimentar en un aliado, lo que lo potencia de formas impredecibles durante 20 s."}
MultiLanguageSpellData['mx'][443560] = {name = "Rápido y doloroso", additional_info = "[q0]Talento\n[q]Sangre\n Si tu Ruptura de alma no golpea a ningún enemigo, obtienes un 10% de fuerza durante 8 s.\n\n Oleada de almas tiene un 100% más de efectividad en el objetivo principal de tu Marca de la parca.\n\nEscarcha\n Si tu Ruptura de alma no golpea a ningún enemigo, obtienes un 5% de fuerza durante 8 s.\n\n Oleada de almas tiene un 50% más de efectividad en el objetivo principal de tu Marca de la parca."}
