MultiLanguageSpellData['mx'][443564] = {name = "Muerte dolorosa", additional_info = "[q]Escarcha\nDespués de que Marca de la parca explota, tu siguiente 2 Asolar o Guadaña de escarcha cuesta 1 runas e invoca 2 guadaña para que golpee a tus enemigos.\n\n La primera guadaña golpea a tu objetivo por ([407.975% of Attack Power]) p. de daño de friosombra y tiene una probabilidad de un 100% de otorgar Máquina de matar, la segunda guadaña golpea a todos los enemigos alrededor de tu objetivo por ([178.723% of Attack Power]) p. de daño de friosombra [y aplica Fiebre de Escarcha]. Inflige menos daño a más de 8 objetivos.\n\nSangre\nDespués de que Marca de la parca explota, tu siguiente 2 Rasgamédulas cuesta 1 runas e invoca 2 guadaña para que golpee a tus enemigos.\n\n La primera guadaña golpea a tu objetivo por ([349.069% of Attack Power]) p. de daño de friosombra y tiene una probabilidad de un 100% de segar una Tormenta ósea durante 2.0 s, la segunda guadaña golpea a todos los enemigos alrededor de tu objetivo por ([186.17% of Attack Power]) p. de daño de friosombra [y aplica Fiebre de Escarcha]. Inflige menos daño a más de 8 objetivos."}
MultiLanguageSpellData['mx'][443565] = {name = "Lanzar antorcha", additional_info = "Alcance de20\n-[q2]30\nm\nHechizo de 1.5 seg\n[q]Quema el cuerpo de un defensor caído. ¡No dejes nada que los nerubianos puedan profanar!"}
MultiLanguageSpellData['mx'][443566] = {name = "Presteza de Chi-Ji", additional_info = "[q0]Talento\n[q]Tu velocidad de movimiento aumenta un 75% durante Conducto celestial y un 15% durante 3 s después de recibir ayuda de cualquier Celestial."}
