MultiLanguageSpellData['mx'][443739] = {name = "Hechicería astillada", additional_info = "[q0]Talento\n[q]Escarcha\n Cuando consumes Escalofrío invernal o Dedos de escarcha, conjuras una Astilla de escarcha.\n\nAstilla de escarcha :\nConjura magia de escarcha pura en un proyectil afilado que inflige ([34.32% of Spell Power]) p. de daño de escarcha.\n\n Las Astillas de escarcha se clavan en su objetivo e infligen ([34.2% of Spell Power]) p. de daño de escarcha durante 18 s. Este efecto se acumula.\n\n\nArcano\n Cuando consumes Precisión abisal, conjuras 2 Astillas arcanas.\n\nAstilla arcana :\nConjura magia arcana pura en un proyectil afilado que inflige ([40.4% of Spell Power]) p. de daño arcano.\n\n Se clavan Astillas arcanas en su objetivo, lo que inflige ([40.4352% of Spell Power]) p. de daño arcano durante 18 s. Este efecto se acumula."}
MultiLanguageSpellData['mx'][443740] = {name = "Astilla de escarcha clavada", additional_info = "Alcance de 100 m\nInstante\n[q]Conjura magia de escarcha pura en un proyectil afilado que inflige ([34.32% of Spell Power]) p. de daño de escarcha.\n\n Las Astillas de escarcha se clavan en su objetivo e infligen ([34.2% of Spell Power]) p. de daño de escarcha durante 18 s. Este efecto se acumula."}
MultiLanguageSpellData['mx'][443741] = {name = "Protección de Sseratus", additional_info = nil}
MultiLanguageSpellData['mx'][443742] = {name = "Tormenta de astillas", additional_info = "[q0]Talento\n[q]Arcano\n Siempre que tienes 8 o más Astillas arcanas clavadas activas, automáticamente lanzas una Tormenta de astillas a tu objetivo.\n\nTormenta de astillas :\n Destroza todas las Astillas arcanas clavadas, lo que inflige su daño periódico restante instantáneamente.\n\n Conjura una Astilla arcana por cada Astilla destrozada, y luego las disparas todas juntas en un aluvión devastador que inflige [([40.4% of Spell Power]) arcano][([34.32% of Spell Power]) de escarcha] a tu objetivo por cada Astilla en la Tormenta de astillas.\n\n Tormenta de astillas tiene un 8% de probabilidad de otorgarte Lanzamiento libre.\n\nEscarcha\n Siempre que tienes 8 o más Astillas de escarcha clavadas activas, automáticamente lanzas una Tormenta de astillas a tu objetivo.\n\nTormenta de astillas :\n Destroza todas las Astillas de escarcha clavadas, lo que inflige su daño periódico restante instantáneamente.\n\n Conjura una Astilla de escarcha por cada Astilla destrozada, y luego las disparas todas juntas en un aluvión devastador que inflige [([40.4% of Spell Power]) arcano][([34.32% of Spell Power]) de escarcha] a tu objetivo por cada Astilla en la Tormenta de astillas.\n\n Tormenta de astillas tiene un 10% de probabilidad de otorgarte Congelación cerebral."}
