MultiLanguageSpellData['mx'][443949] = {name = "[q0]Cubremuñecas de plumas de cuervo", additional_info = "Hechizo de 2 seg 3\nComponentes:\nTormenta embotellada (10), Colmillo de bestia magnífica , Pellejo cubierto de esporas (2), Banda de armadura quitinosa , Chispa (#256)\nComponentes opcionales:\nInfunde con poder (#284) , Armadura de cuero (#286) , Autenticidad del artesano (#346) , Aumento mayor (#384)\nBotín:\nLa troupe de teatro\n\n[q4]Cubremuñecas de plumas de cuervo\nSe liga al recogerlo\nMuñecas Cuero\n1571 armadura\n+1.198 [Agilidad o Intelecto]+5.483 aguante\n[q2]+ 468 Versatilidad\n[q2]Aumenta tu índice de maestría + 351 p.\nDurabilidad 55 / 55\nNecesitas ser de nivel 80\n\n[q]Furia del corventoso (0/3)\n[q0]Jubón de frente de tormenta desgastado\nGarfas de trueno turbador\nCubremuñecas de plumas de cuervo"}
MultiLanguageSpellData['mx'][443950] = {name = "[q4]Garfas de trueno turbador", additional_info = "Hechizo de 2 seg 3\nComponentes:\nTormenta embotellada (10), Colmillo de bestia magnífica , Pellejo cubierto de esporas (2), Banda de armadura quitinosa , Chispa (#256)\nComponentes opcionales:\nInfunde con poder (#284) , Armadura de cuero (#286) , Autenticidad del artesano (#346) , Aumento mayor (#384)\nBotín:\nMonstruosidad de piedra del Vacío\nZona:\nEl Corvento\n\n[q4]Garfas de trueno turbador\nSe liga al recogerlo\nManos Cuero\n1767 armadura\n+1.597 [Agilidad o Intelecto]+7.311 aguante\n[q2]Aumenta tu índice de celeridad + 624 p.\n[q2]+ 468 Versatilidad\nDurabilidad 55 / 55\nNecesitas ser de nivel 80\n\n[q]Furia del corventoso (0/3)\n[q0]Jubón de frente de tormenta desgastado\nGarfas de trueno turbador\nCubremuñecas de plumas de cuervo"}
MultiLanguageSpellData['mx'][443951] = {name = "[q4]Jubón de frente de tormenta desgastado", additional_info = "Hechizo de 2 seg 3\nComponentes:\nTormenta embotellada (10), Colmillo de bestia magnífica , Pellejo cubierto de esporas (3), Banda de armadura quitinosa , Chispa (#256)\nComponentes opcionales:\nInfunde con poder (#284) , Armadura de cuero (#286) , Autenticidad del artesano (#346) , Aumento mayor (#384)\nEspecialización:\nFortaleza perfecta - Baluartes bestiales\n\n[q4]Jubón de frente de tormenta desgastado\nSe liga al recogerlo\nPecho Cuero\n3142 armadura\n+2.129 [Agilidad o Intelecto]+9.748 aguante\n[q2]Aumenta tu índice de golpe crítico + 832 p.\n[q2]Aumenta tu índice de maestría + 624 p.\nDurabilidad 165 / 165\nNecesitas ser de nivel 80\n\n[q]Furia del corventoso (0/3)\n[q0]Jubón de frente de tormenta desgastado\nGarfas de trueno turbador\nCubremuñecas de plumas de cuervo"}
