MultiLanguageSpellData['mx'][443954] = {name = "Conductos de escape", additional_info = "Alcance de 100 m\nInstante\n[q]Brokk canaliza energía dentro de la maquinaria que hay debajo de él para activar sus conductos de ventilación termales durante 6 s, que infligen 969780 p. de daño de fuego a todos los jugadores cada 1 s y lanzan una y otra vez Chatarra llameante en el área.\n\n Mientras dura el efecto, los conductos infligen 9697798 p. de daño de fuego cada 1 s a los jugadores que se paran encima."}
MultiLanguageSpellData['mx'][443957] = {name = "Atrapahechizos", additional_info = "[q]Reduce un 75% el daño mágico recibido y redirige hacia ti el siguiente hechizo dañino que tenga como objetivo a un aliado en un radio de 40 m de ti.\n\n 3 s después de recibir daño mágico o redirigir un hechizo, este efecto estará anulado durante 20 s."}
MultiLanguageSpellData['mx'][443958] = {name = "[q0]Hebilla de abeja laboriosa", additional_info = "Hechizo de 2 seg 3\nComponentes:\nPelo de cenizabeja ardiente (10), Colmillo de bestia magnífica , Pellejo cubierto de esporas (2), Banda de armadura quitinosa , Chispa (#256)\nComponentes opcionales:\nInfunde con poder (#284) , Armadura de malla (#287) , Autenticidad del artesano (#346) , Aumento mayor (#384)\nBotín:\nGoldie Bonbarón\nZona:\nHidromielería Cinérea\n\n[q4]Hebilla de abeja laboriosa\nSe liga al recogerlo\nCintura Malla\n2606 armadura\n+1.597 [Agilidad o Intelecto]+7.311 aguante\n[q2]Aumenta tu índice de celeridad + 468 p.\n[q2]Aumenta tu índice de maestría + 624 p.\nDurabilidad 55 / 55\nNecesitas ser de nivel 80\n\n[q]Abrazo de la cenizabeja (0/3)\n[q0]Camisote de polen humeante\nVoladoras de pelo reforzadas\nHebilla de abeja laboriosa"}
