MultiLanguageSpellData['mx'][444248] = {name = "Invocar a Mograine", additional_info = "Instante\n[q]Gastar runas tiene una probabilidad de invocar la ayuda de un jinete durante 10 s.\n\nMograine\n Lanza Muerte y descomposición en su ubicación y sigue su posición.\n\nMelenablanca\n Lanza No-muerte sobre tu objetivo y le inflige ([9.15376% of Attack Power]) p. de daño de friosombra por acumulación cada 3 s durante 24 s. Cada vez que No-muerte inflige daño, obtiene una acumulación. No se puede renovar.\n\nAterratrols\n Lanza Cadenas de hielo sobre tu objetivo que reducen un 40% su velocidad de movimiento y aumenta el daño que les infliges un 5% durante 8 s.\n\nNazgrim\n Mientras Nazgrim está activo, obtienes Conquista apocalíptica, lo que aumenta tu fuerza un 5%."}
MultiLanguageSpellData['mx'][444249] = {name = "Aliento de fuego", additional_info = "Alcance de 100 m\nInstante\n[q]Inhalas y avivas tu llama interna. Exhalas, carbonizas a los enemigos que se encuentren en un cono frente a ti e infliges [(([163.409% of Spell Power])) + (([39.4834% of Spell Power]) * (10 + 0 ))] p. de daño de fuego, que se reduce si hay más de 5 objetivos. [ Arenas del tiempo : Aumenta la duración de los efectos activos de Poder de ébano 2 s ]\n Potenciar causa que el daño infligido sea inmediato y no periódico.\n\nI: Inflige [([163.409% of Spell Power])] p. de daño de forma inmediata y [([39.4834% of Spell Power]) * (10 + 0 )] p. cada (20 + 0 ) s.\n\nII: Inflige [([163.409% of Spell Power]) + (([39.4834% of Spell Power]) * 3)] p. de daño de forma inmediata y [([39.4834% of Spell Power]) * (7 + 0 )] p. cada (14 + 0 ) s.\n\nIII: Inflige [([163.409% of Spell Power]) + (([39.4834% of Spell Power]) * 6)] p. de daño de forma inmediata y [([39.4834% of Spell Power]) * (4 + 0 )] cada (8 + 0 ) s."}
MultiLanguageSpellData['mx'][444250] = {name = "Torrente de relámpagos", additional_info = "Rango ilimitado\nInstante\n[q]Cuando alcanza 100 p. de energía, Kyrioss vela al centro de la sala y se sobrecarga con energía eléctrica, lo que inflige 1212225 p. de daño de naturaleza y los golpea con Descarga a tierra cada 3 s durante 15 s. También desata 4 torrentes de relámpagos. Tocar estos torrentes inflige 19395595 p. de daño de naturaleza y aturde al objetivo durante 6 s."}
MultiLanguageSpellData['mx'][444251] = {name = "Invocar a Melenablanca", additional_info = "Instante\n[q]Gastar runas tiene una probabilidad de invocar la ayuda de un jinete durante 10 s.\n\nMograine\n Lanza Muerte y descomposición en su ubicación y sigue su posición.\n\nMelenablanca\n Lanza No-muerte sobre tu objetivo y le inflige ([9.15376% of Attack Power]) p. de daño de friosombra por acumulación cada 3 s durante 24 s. Cada vez que No-muerte inflige daño, obtiene una acumulación. No se puede renovar.\n\nAterratrols\n Lanza Cadenas de hielo sobre tu objetivo que reducen un 40% su velocidad de movimiento y aumenta el daño que les infliges un 5% durante 8 s.\n\nNazgrim\n Mientras Nazgrim está activo, obtienes Conquista apocalíptica, lo que aumenta tu fuerza un 5%."}
MultiLanguageSpellData['mx'][444252] = {name = "Invocar a Nazgrim", additional_info = "Instante\n[q]Gastar runas tiene una probabilidad de invocar la ayuda de un jinete durante 10 s.\n\nMograine\n Lanza Muerte y descomposición en su ubicación y sigue su posición.\n\nMelenablanca\n Lanza No-muerte sobre tu objetivo y le inflige ([9.15376% of Attack Power]) p. de daño de friosombra por acumulación cada 3 s durante 24 s. Cada vez que No-muerte inflige daño, obtiene una acumulación. No se puede renovar.\n\nAterratrols\n Lanza Cadenas de hielo sobre tu objetivo que reducen un 40% su velocidad de movimiento y aumenta el daño que les infliges un 5% durante 8 s.\n\nNazgrim\n Mientras Nazgrim está activo, obtienes Conquista apocalíptica, lo que aumenta tu fuerza un 5%."}
MultiLanguageSpellData['mx'][444254] = {name = "Invocar a Aterratrols", additional_info = "Instante\n[q]Gastar runas tiene una probabilidad de invocar la ayuda de un jinete durante 10 s.\n\nMograine\n Lanza Muerte y descomposición en su ubicación y sigue su posición.\n\nMelenablanca\n Lanza No-muerte sobre tu objetivo y le inflige ([9.15376% of Attack Power]) p. de daño de friosombra por acumulación cada 3 s durante 24 s. Cada vez que No-muerte inflige daño, obtiene una acumulación. No se puede renovar.\n\nAterratrols\n Lanza Cadenas de hielo sobre tu objetivo que reducen un 40% su velocidad de movimiento y aumenta el daño que les infliges un 5% durante 8 s.\n\nNazgrim\n Mientras Nazgrim está activo, obtienes Conquista apocalíptica, lo que aumenta tu fuerza un 5%."}
MultiLanguageSpellData['mx'][444256] = {name = "Orbes astillantes", additional_info = "[q0]Talento\n[q]Arcano\n Los enemigos dañados por tu Orbe arcano conjuran 2 Astilla arcana, hasta un máximo de 4.\n\n El daño de Orbe arcano aumenta un 25%.\n\nEscarcha\n Los enemigos dañados por tu Orbe congelado conjuran 1 Astilla de escarcha, hasta un máximo de 4.\n\n El daño de Orbe congelado aumenta un 25%."}
MultiLanguageSpellData['mx'][444257] = {name = "Tambores atronadores", additional_info = "{Instante} {5 min de reutilización}\n[q]Aumenta un 15% la celeridad de todos los miembros del grupo y de la banda. Dura 40 s.\n\n Los aliados que reciben este efecto quedan agotados y no pueden volver a beneficiarse de Ansia de sangre, Heroísmo ni ningún otro efecto similar durante 10 min."}
