MultiLanguageSpellData['mx'][444276] = {name = "Jeringa truculenta", additional_info = "Aproximadamente 6 activaciones por minuto\n[q]Tus hechizos de sanación tienen una alta probabilidad de hacer que te inyectes una carga de Suero volátil . Se pueden superponer varias cargas.\n\n Si un aliado cae por debajo del 70% de salud, expulsa una carga para restaurarle 2146 p. de salud. Si no se usan después de 15 s, las cargas se catalizan para otorgarte 58 p. de intelecto en su lugar durante 10 s."}
