MultiLanguageSpellData['mx'][444336] = {name = "[q2]Medallón de Competidor algari", additional_info = "Hechizo de 2 seg 2\nComponentes:\nClave infinita (2), Tinta sombría (3), Tinta cobalto (3), Heráldica de competidor (#255) (3)\nComponentes opcionales:\nAutenticidad del artesano (#346) , Suministros de dibujo (#359)\nVendedor:\nHotharn\nZona:\nDornogal\nCosto:\n7500\nReceta:\nSe puede comprar en la casa de subastas\n\n\n[q2]Medallón de Competidor algari\nSe liga al equiparlo\nÚnico-Equipado: Medallones de Gladiador (1)Abalorio\n+2.024 [Agilidad o Fuerza o Intelecto][q2]Uso: Disipa todos los efectos de reducción de movimiento y todos los efectos que provocan pérdida de control de tu personaje.\nNecesitas ser de nivel 70\n\n[q]Distinción de Gladiador (0/2)\n[q0]Emblema de Gladiador\nMedallón de Gladiador"}
MultiLanguageSpellData['mx'][444337] = {name = "[q2]Insignia de prontitud de Competidor algari", additional_info = "Hechizo de 2 seg 2\nComponentes:\nClave infinita (2), Tinta sombría (5), Tinta cobalto (5), Heráldica de competidor (#255) (5)\nComponentes opcionales:\nAutenticidad del artesano (#346) , Suministros de dibujo (#359)\nVendedor:\nHotharn\nZona:\nDornogal\nCosto:\n7500\nReceta:\nSe puede comprar en la casa de subastas\n\n\n[q2]Insignia de prontitud de Competidor algari\nSe liga al equiparlo\nÚnico-EquipadoAbalorio\n[q2]Aumenta tu índice de celeridad + 1.040 p.\n[q2]Equipar: Tus hechizos y habilidades tienen una probabilidad de otorgar 4519 p. de estadística principal durante 20 s.\nNecesitas ser de nivel 70\n\n[q]Distinción de Gladiador (0/2)\n[q0]Emblema de Gladiador\nMedallón de Gladiador"}
MultiLanguageSpellData['mx'][444338] = {name = "[q2]Emblema de Competidor algari", additional_info = "Hechizo de 2 seg 2\nComponentes:\nClave infinita (2), Tinta sombría (5), Tinta cobalto (5), Heráldica de competidor (#255) (5)\nComponentes opcionales:\nAutenticidad del artesano (#346) , Suministros de dibujo (#359)\nVendedor:\nHotharn\nZona:\nDornogal\nCosto:\n7500\nReceta:\nSe puede comprar en la casa de subastas\n\n\n[q2]Emblema de Competidor algari\nSe liga al equiparlo\nÚnico-EquipadoAbalorio\n+2.024 [Agilidad o Fuerza o Intelecto][q2]Uso: Aumenta 1048184 p. la salud máxima durante 15 s. (2 Min Reutilización)\nNecesitas ser de nivel 70\n\n[q]Distinción de Gladiador (0/2)\n[q0]Emblema de Gladiador\nMedallón de Gladiador"}
