MultiLanguageSpellData['mx'][444621] = {name = "Resguardo de salvación", additional_info = "[q]Aprendes el siguiente hechizo.\n\n Resguardo de salvación\nRestaura salud a un aliado y le otorga un Resguardo de salvación durante 8 s.\n\n Mientras Resguardo de salvación perdura, la sanación del taumaturgo también otorga absorción.\n\n Cuando el Resguardo expira, explota e inflige daño sagrado equivalente a la absorción restante a todos los enemigos en un radio de 40 m, dividido en partes iguales."}
MultiLanguageSpellData['mx'][444622] = {name = "Resguardo de salvación", additional_info = "Alcance de 40 m\n{Instante} {3 min de reutilización}\n[q]Restaura salud a un aliado y le otorga un Resguardo de salvación durante 8 s.\n\n Mientras Resguardo de salvación perdura, la sanación del taumaturgo también otorga absorción.\n\n Cuando el Resguardo expira, explota e inflige daño sagrado equivalente a la absorción restante a todos los enemigos en un radio de 40 m, dividido en partes iguales."}
MultiLanguageSpellData['mx'][444623] = {name = "Symbiosis: Dummy Spell", additional_info = "Hechizo de 3.5 seg\nHerramientas: Juego de caligrafía de virtuoso\n[q]Cuando recibes daño, hay una probabilidad de otorgarte a ti y a un miembro del grupo aliado un escudo de absorción compartido de X p. que dura Y s, si es posible. Si el escudo se gasta, los dos jugadores obtienen X p. de versatilidad durante Y s."}
MultiLanguageSpellData['mx'][444627] = {name = "Vivacity: Dummy Spell", additional_info = "Hechizo de 3.5 seg\nHerramientas: Juego de caligrafía de virtuoso\n[q]Tus hechizos y habilidades tienen una probabilidad de otorgar a tu sigilo un Ritmo de vivacidad, que te ayuda según sea conveniente.\n\n Si se activa con daño\n\n Si estás en combate con varios objetivos, explota e inflige X p. de daño de fuego después de 10 s.\n\n Si tienes más del 90% de salud, obtienes X p. de tu estadística secundaria más alta durante 15 s.\n\n Si tienes menos de 30% de salud, te sana X p. de salud.\n\n Si el objetivo tiene menos de 20% de salud y se puede ejecutar, lo ejecuta.\n\n Si no sucede nada de lo anterior, obtienes Y p. de tu estadística secundaria más baja.\n\n Si se activa con sanación\n\n Si el objetivo tiene menos del 50% de salud, le sana X p. de salud.\n\n Si el objetivo tiene más del 90% de salud, obtienes X p. de tu estadística secundaria más alta durante 15 s.\n\n Si tienes menos del 50% de maná, obtienes X p. de maná.\n\n Si no sucede nada de lo anterior, obtienes Y p. de tu estadística secundaria más baja."}
