MultiLanguageSpellData['mx'][444769] = {name = "Defunción inminente", additional_info = "[q0]Talento\n[q]Cada 3 Golpes de destripador, obtienes Muerte súbita.\n\n Usar Muerte súbita acelera tu siguiente Filotormenta para que golpee 1 vez más (máx. 3). La duración total de Filotormenta no cambia."}
MultiLanguageSpellData['mx'][444770] = {name = "Impulso mortal", additional_info = "[q0]Talento\n[q]Te sanas por un 15% del daño que inflige Muerte súbita."}
MultiLanguageSpellData['mx'][444771] = {name = "Sin piedad", additional_info = "[q0]Talento\n[q]Marcado para ejecución aumenta un 15% la probabilidad de golpe crítico y el daño de golpe crítico de tu siguiente Ejecutar sobre el objetivo."}
MultiLanguageSpellData['mx'][444772] = {name = "Hojas abrumadoras", additional_info = "[q0]Talento\n[q]Cada golpe de Filotormenta aplica Abrumado a todos los enemigos afectados, lo que aumenta el daño que les infliges un 1 % durante 20 s. Se acumula hasta 10 veces."}
MultiLanguageSpellData['mx'][444773] = {name = "Resolución feroz", additional_info = "[q0]Talento\n[q]Armas\n Los golpes críticos de Golpe mortal aumentan un 20% el daño de tu siguiente Golpe mortal.\n\nFuria\n Los golpes críticos de Sed de sangre aumentan un 20% el daño de tu siguiente Sed de sangre."}
MultiLanguageSpellData['mx'][444774] = {name = "Oportunista", additional_info = "[q0]Talento\n[q]Furia\n Cuando Arremetida enfurecida restablece su propio tiempo de reutilización, tu siguiente Arremetida enfurecida inflige un 20% más de daño y un 20% más de daño crítico.\n\nArmas\n Cuando Táctico restablece el tiempo de reutilización de Abrumar, tu siguiente Abrumar inflige un 25% más de daño y un 25% más de daño crítico."}
MultiLanguageSpellData['mx'][444775] = {name = "Provecho de la tormenta", additional_info = "[q0]Talento\n[q]Armas\n Cuando Golpe mortal y Rajar golpean a 3 o más objetivos, tienen un 20% de probabilidad de hacer que desates una ráfaga de acero que golpea a todos los enemigos cercanos, les inflige ([371.11% of Attack Power]) p. de daño físico y les aplica Abrumado. Inflige menos daño si golpea a más de 8 objetivos.\n\nFuria\n Sed de sangre tiene un 20% de probabilidad de hacer que desates una ráfaga de acero que golpea a todos los enemigos cercanos, les inflige ([371.11% of Attack Power]) p. de daño físico y les aplica Abrumado. Inflige menos daño si golpea a más de 8 objetivos.\n\n(Probabilidad de que accione: 20%, 500ms de reutilización)"}
MultiLanguageSpellData['mx'][444776] = {name = "Persecución incansable", additional_info = "[q0]Talento\n[q]Cargar aumenta tu velocidad de movimiento un 70% durante 3 s.\n\n Cargar elimina todos los efectos de reducción de movimiento. Este efecto no puede ocurrir más de una vez cada 30 s."}
MultiLanguageSpellData['mx'][444777] = {name = "Agilidad sañosa", additional_info = "[q0]Talento\n[q]Salto heroico reduce 5 s el tiempo de reutilización de Cargar, y Cargar reduce 2 s el tiempo de reutilización de Salto heroico."}
MultiLanguageSpellData['mx'][444778] = {name = "Ciclón de matanza", additional_info = "[q0]Talento\n[q]Cada golpe de Filotormenta inflige un 10% más de daño dividido entre todos los objetivos."}
MultiLanguageSpellData['mx'][444779] = {name = "Malicia del destripador", additional_info = "[q0]Talento\n[q]Armas\n El daño de Abrumar aumenta un 30%.\n\nFuria\n El daño de Arremetida enfurecida aumenta un 30%."}
MultiLanguageSpellData['mx'][444780] = {name = "Embate implacable", additional_info = "[q0]Talento\n[q]Al Ejecutar a un objetivo que hayas Marcado para ejecución, el tiempo de reutilización de Filotormenta se reduce 5 s y se aplican 2 acumulaciones de Abrumado al objetivo por cada acumulación consumida de Marcado para ejecución.\n\n Puedes usar Zurrar y Descarga tormentosa a la vez que Filotormenta."}
MultiLanguageSpellData['mx'][444784] = {name = "Reflejo fantasmal", additional_info = "[q0]Talento\n[q]Tu Reflejo exacto invoca un clon más.\n Reflejo exacto ahora reduce un 5% más todo el daño recibido."}
MultiLanguageSpellData['mx'][444785] = {name = "Perca sangrienta", additional_info = "Instante\n[q]Un pequeño pez con escamas carmesí que nada por todo Khaz Algar. Cuando se siente amenazado, sus branquias expulsan una tinta viscosa que parece sangre.\n\nEspecial:\n\n Cebo sangriento\n\n Si vuelves a arrojar a este pez a las aguas de Khaz Algar, puedes activar su mecanismo y envolverte en feromonas para pescar mielgas sanguinas esquivas.\n\nÁreas donde puedes encontrar este pez:\n\n - Isla de Dorn\n - Las Minas Resonantes\n - Cristalia\n - Isla de las Sirenas\n - Oasis de K'aresh\n\nEstanques de pesca:\n\n - Cardumen de tiburones tugurio\n - Sangre en el agua\n - Charco de podredumbre purulenta\n - Cardumen de percas sangrientas\n - Superficie calma con ondas\nProfesión:\nPesca"}
MultiLanguageSpellData['mx'][444786] = {name = "Esturión cristalino", additional_info = "Alcance de 5 m\nInstante\n[q]Un cuerpo elegante y alargado que navega sin esfuerzo por las aguas de Khaz Algar. De tamaño mucho mayor que su pariente, la bermejuela bismuto, este pez ancestral tiende a perseguir a los cardúmenes de esos peces para absorber los nutrientes que desprenden.\n\nEspecial:\n\n Percepción\n\n Devuelve este pez al agua y aumenta tu percepción de Khaz Algar.\n\nÁreas donde puedes encontrar este pez:\n\n - Isla de Dorn\n - Las Minas Resonantes\n - Isla de las Sirenas\n\nEstanques de pesca:\n\n - Brillacuática\nProfesión:\nPesca"}
MultiLanguageSpellData['mx'][444787] = {name = "Bermejuela bismuto", additional_info = "Alcance de 5 m\nHechizo de 3.2 seg\n[q]Pequeño y de expresión adusta, sus escamas exteriores duras se asemejan mucho al bismuto. Estas escamas atrapan minerales y otros desechos que luego se transportan por las aguas de Khaz Algar. Es un pez muy común, pero importante para la flora local.\n\nEspecial:\n\n Cebo\n\n Devuelve este pez al agua y aumenta tu habilidad de pesca.\n\nÁreas donde puedes encontrar este pez:\n\n - Isla de Dorn\n - Las Minas Resonantes\n - Isla de las Sirenas\n\nEstanques de pesca:\n\n - Brillacuática\nProfesión:\nPesca"}
MultiLanguageSpellData['mx'][444788] = {name = "Sardinilla mordedora", additional_info = "Alcance de 5 m\nHechizo de 3.2 seg\n[q]Un pececillo desprevenido que podría hacer creer a un pescador inexperto que su valor es insignificante. Sin embargo, se rumorea que estos peces tienden a reunirse en torno a objetos especialmente brillantes y a mordisquear la suciedad que acumulan.\n\nEspecial:\n\n Percepción\n\n Devuelve este pez al agua y aumenta tu percepción de Khaz Algar.\n\nÁreas donde puedes encontrar este pez:\n\n - Isla de Dorn\n - Las Minas Resonantes\n - Cristalia\n - Azj-Kahet\n - Isla de las Sirenas\n - Minahonda\n - Oasis de K'aresh\n\nEstanques de pesca:\n\n - Superficie calma con ondas\nProfesión:\nPesca"}
MultiLanguageSpellData['mx'][444789] = {name = "Miracielo susurrante", additional_info = "Alcance de 5 m\nHechizo de 3.2 seg\n[q]Estos peces son conocidos por formar cardúmenes y deben su nombre a la fricción de sus escamas negro oscuro que se entrechocan. Las vibraciones que crean actúan como un elemento disuasorio para los depredadores y producen un sonido audible que puede oírse fuera del agua.\n\nEspecial:\n\n Susurro de las profundidades\n\n Usa el miracielo susurrante para hacer salir a los celacantos durmientes de las profundidades de Azj-Kahet.\n\nÁreas donde puedes encontrar este pez:\n\n - Isla de Dorn\n - Las Minas Resonantes\n - Cristalia\n - Isla de las Sirenas\n - Oasis de K'aresh\n\nEstanques de pesca:\n\n - Cardumen de miracielos\nProfesión:\nPesca"}
MultiLanguageSpellData['mx'][444790] = {name = "Trucha branquiáurica", additional_info = "Alcance de 5 m\nHechizo de 3.2 seg\n[q]Los surcos de sus branquias brillan con un dorado iridiscente. Los pescadores comparten su fábula para atraer buena fortuna y mares tranquilos.\n\nEspecial:\n\n Percepción\n\n Si pescas este pez, aumentará tu percepción de Khaz Algar.\n\nÁreas donde puedes encontrar este pez:\n\n - Isla de Dorn\n - Las Minas Resonantes\n - Cristalia\n - Azj-Kahet\n - Isla de las Sirenas\n - Minahonda\n - Oasis de K'aresh\n\nEstanques de pesca:\n\n - Brillacuática\n - Charco de podredumbre purulenta\n - Derrame de icor infundido\nProfesión:\nPesca"}
MultiLanguageSpellData['mx'][444791] = {name = "Pez arcoíris especular", additional_info = "Alcance de 5 m\nHechizo de 3.2 seg\n[q]La sangre multicolor que corre por debajo de las escamas translúcidas confiere a este pez un aspecto de arcoíris. Aparte de los usos culinarios de su carne, se sabe que la sangre del pez arcoíris es casi idéntica al pigmento nacarado que utilizan los escribas.\n\nEspecial:\n\n Filete fresco\n\n Utilizar este pescado con la habilidad de cocina puede producir filete fresco.\n\nÁreas donde puedes encontrar este pez:\n\n - Isla de Dorn\n - Las Minas Resonantes\n - Isla de las Sirenas\n - Oasis de K'aresh\n\nEstanques de pesca:\n\n - Brillacuática\nProfesión:\nPesca"}
MultiLanguageSpellData['mx'][444792] = {name = "Leucisco holgazán", additional_info = "Alcance de 5 m\nHechizo de 3.2 seg\n[q]Un pez travieso que se mueve a toda velocidad por Khaz Algar. A veces se lo confunde con una sardinilla mordedora o una perca enana majestuosa. Su velocidad y tamaño hacen que esté donde no debe.\n\nEspecial:\n\n Cebo\n\n Devuelve este pez al agua y aumenta tu habilidad de pesca.\n\nÁreas donde puedes encontrar este pez:\n\n - Isla de Dorn\n - Las Minas Resonantes\n - Cristalia\n - Isla de las Sirenas\n - Oasis de K'aresh\n\nEstanques de pesca:\n\n - Superficie calma con ondas\n - Sangre en el agua\n - Charco de podredumbre purulenta\nProfesión:\nPesca"}
MultiLanguageSpellData['mx'][444793] = {name = "Lucio dórnico", additional_info = "Alcance de 5 m\nHechizo de 3.2 seg\n[q]Una criatura discreta cuyo exterior moteado le permite camuflarse de los ataques desde arriba mientras se alimenta de peces más pequeños abajo. Su exterior grande y carnoso intimida a los esturiones cristalinos cercanos y ofrece una excelente fuente de filete fresco.\n\nEspecial:\n\n Filete fresco\n\n Utilizar este pescado con la habilidad de cocina puede producir filete fresco.\n\nÁreas donde puedes encontrar este pez:\n\n - Isla de Dorn\n - Las Minas Resonantes\n - Cristalia\n - Isla de las Sirenas\n\nEstanques de pesca:\n\n - Superficie calma con ondas\nProfesión:\nPesca"}
MultiLanguageSpellData['mx'][444794] = {name = "Buscapescadores atroz", additional_info = "Alcance de 5 m\nHechizo de 3.2 seg\n[q]Un pez agresivo que tiende a agruparse donde están los pescadores. Su potente aleta caudal y su cuerpo musculoso rompen las olas y crean un rugido sonoro.\n\nEspecial:\n\n Filete fresco\n\n Utilizar este pescado con la habilidad de cocina puede producir filete fresco.\n\nÁreas donde puedes encontrar este pez:\n\n - Isla de Dorn\n - Las Minas Resonantes\n - Cristalia\n - Azj-Kahet\n - Isla de las Sirenas\n\nEstanques de pesca:\n\n - Torrente de buscapescadores\nProfesión:\nPesca"}
MultiLanguageSpellData['mx'][444795] = {name = "Pez martillo de Arathor", additional_info = "Alcance de 5 m\nHechizo de 3.2 seg\n[q]La corona que lleva en la cabeza funciona como un arma poderosa cuando se impulsa con sus enormes aletas. Sus escamas brillan con un tono similar al de los arathi, por lo que no es de extrañar que este pez musculoso lleve ese nombre.\n\nEspecial:\n\n Suelta el martillo\n\nGolpea a tu enemigo con el pez martillo para aturdirlo durante 1 s. Solo se puede usar en exteriores en Khaz Algar.\n\nÁreas donde puedes encontrar este pez:\n\n - Cristalia\n\nEstanques de pesca:\n\n - Sangre en el agua\nProfesión:\nPesca"}
MultiLanguageSpellData['mx'][444796] = {name = "Perca enana majestuosa", additional_info = "Alcance de 5 m\nHechizo de 3.2 seg\n[q]Su pequeño pero poderoso torso está decorado con tonos carmesí y magenta. Este pez agresivo y muy poco común en la corte real protege las aguas donde vive el pez señuelo de la reina de seres como los peces demonio corruptos.\n\nEspecial:\n\n Cebo Real\n\n Ahuyenta a los peces demonio corruptos y crea aguas seguras para los peces señuelo de la reina.\n\nÁreas donde puedes encontrar este pez:\n\n - Cristalia\n - Azj-Kahet\n\nEstanques de pesca:\n\n - Onda real\nProfesión:\nPesca"}
MultiLanguageSpellData['mx'][444797] = {name = "Tiburón tugurio kaheti", additional_info = "Alcance de 5 m\nHechizo de 3.2 seg\n[q]En las profundidades de Azj-Kahet, esta criatura se desliza por el lecho con una figura que apenas se distingue en las turbias profundidades. Este depredador astuto puede hacer que hasta el pescador más experimentado se rinda a sus pies.\n\nEspecial:\n\n Filete fresco\n\n Reciclar este pescado con la habilidad de cocina puede producir una gran cantidad de filete fresco.\n\nÁreas donde puedes encontrar este pez:\n\n - Cristalia\n - Azj-Kahet\n\nEstanques de pesca:\n\n - Sangre en el agua\n - Enjambre de tiburón tugurio\nProfesión:\nPesca"}
MultiLanguageSpellData['mx'][444798] = {name = "Pez costra blanquecino", additional_info = "Alcance de 5 m\nHechizo de 3.2 seg\n[q]A veces se lo confunde con un pez demonio corrupto, pero en realidad este gran pez es el mejor amigo del pescador. El pez costra blanquecino se siente atraído por los minerales de los lechos de agua y tiene la costumbre de tragarse los tesoros que están escondidos.\n\nEspecial:\n\n Estómago de pez costra\n\n Abre el pescado para encontrar un tesoro.\n\nÁreas donde puedes encontrar este pez:\n\n - Azj-Kahet\n - Minahonda\n\nEstanques de pesca:\n\n - Derrame de icor infundido\n - Charco de podredumbre purulenta\nProfesión:\nPesca"}
MultiLanguageSpellData['mx'][444799] = {name = "Mielga sanguina", additional_info = "Alcance de 5 m\nHechizo de 3.2 seg\n[q]Una maestra de las emboscadas, la mielga sanguina acecha pacientemente a los peces más pequeños y, en el momento indicado, cambia la posición de sus aletas carmesí para abalanzarse velozmente. Este pez grande y esquivo es atraído principalmente por los cardúmenes de percas sangrientas.\n\nEspecial:\n\n Filete fresco\n\n Utilizar este pescado con la habilidad de cocina puede producir una gran cantidad de filete fresco.\n\nÁreas donde puedes encontrar este pez:\n\n - Isla de Dorn\n - Las Minas Resonantes\n - Cristalia\n - Azj-Kahet\n - Isla de las Sirenas\n - Oasis de K'aresh\n\nEstanques de pesca:\n\n - Cardumen de percas sangrientas\n - Sangre en el agua\nProfesión:\nPesca"}
MultiLanguageSpellData['mx'][444800] = {name = "Cuervo marino con púas", additional_info = "Alcance de 5 m\nHechizo de 3.2 seg\n[q]Su cuerpo está lleno de espinas filosas que sobresalen desde distintos ángulos y forman una especie de armadura temible. Estas púas sirven tanto de protección como camuflaje en el lecho marino rocoso donde suele habitar. A pesar de su apariencia impactante, se mueve con una elegancia sorprendente, deslizándose sin esfuerzo entre las grietas y cuevas submarinas.\n\nEspecial:\n\n Filete fresco\n\n Utilizar este pescado con la habilidad de cocina puede producir una gran cantidad de filete fresco.\n\nÁreas donde puedes encontrar este pez:\n\n - Isla de Dorn\n - Cristalia\n - Isla de las Sirenas\n\nEstanques de pesca:\n\n - Superficie calma con ondas\n - Brillacuática\n - Cardumen de miracielos\n - Torrente de buscapescadores\nProfesión:\nPesca"}
MultiLanguageSpellData['mx'][444801] = {name = "Pez señuelo de la reina", additional_info = "Alcance de 5 m\nHechizo de 3.2 seg\n[q]Su estilizado cuerpo está decorado con escamas tornasoladas que resplandecen con una gran variedad de colores. Presenta un señuelo bioluminiscente que cuelga de su frente y se asemeja a una gema brillante. Este pez se desliza cómodamente y con elegancia entre las oscuras profundidades de Khaz Algar. Sus sentidos agudos le permiten prosperar en la oscuridad.\n\nEspecial:\n\n Filete fresco\n\n Utilizar este pescado con la habilidad de cocina puede producir una gran cantidad de filete fresco.\n\nÁreas donde puedes encontrar este pez:\n\n - Cristalia\n - Azj-Kahet\n\nEstanques de pesca:\n\n - Onda real\nProfesión:\nPesca"}
MultiLanguageSpellData['mx'][444802] = {name = "Pez demonio maldito", additional_info = "Alcance de 5 m\nInstante\n[q]Su piel pálida y enfermiza deja entrever un cuerpo esquelético, distorsionado por la sangre de los dioses antiguos. Los pescadores de todo Khaz Algar se refieren a este pez como un emisario de la ruina que maldice a cualquiera que tenga la mala fortuna de capturarlo con su caña. Mirar a los ojos a esta criatura no hace más que reafirmar su envilecimiento: cualquier tipo de reflejo es consumido por su abismo.\n\nPescar este pez lanza:\n\n Maldición de pez demonio\n\n Pero no todo está perdido. Si bien los pescadores evitan capturar al pez demonio maldito, los chefs los ven como una oportunidad. Reciclar este pez puede resultar beneficioso para el estómago y tu habilidad de pesca.\n\nÁreas donde puedes encontrar este pez:\n\n - Dondequiera que un pescador algari muy confiado arroje su anzuelo.\n\nEstanques de pesca:\n\n - Cualquier estanque\nProfesión:\nPesca"}
MultiLanguageSpellData['mx'][444803] = {name = "Celacanto despertado", additional_info = "Alcance de 5 m\nInstante\n[q]Una humilde criatura durmiente. Cuando despierta, sus escamas resplandecen con un brillo reflectante, a pesar de estar en contacto con poca luz. Una verdadera majestuosidad que muchos aspirantes a pescadores buscan conseguir.\n\nEspecial:\n\n Filete fresco\n\n Utilizar este pescado con la habilidad de cocina puede producir una gran cantidad de filete fresco.\n\nÁreas donde puedes encontrar este pez:\n\n - Azj-Kahet\n - Oasis de K'aresh\nProfesión:\nPesca"}
MultiLanguageSpellData['mx'][444806] = {name = "Furia de los aldrachi", additional_info = "Instante\n[q]Consumir [ Caos : 6 /\n\nVenganza\n20 ] fragmentos de alma o lanzar La cacería convierte tu próximo Lanzar guja en Guja de atracador.\n\n Guja de atracador :\nLanza una guja mejorada con la esencia de almas consumidas a tu objetivo, lo que inflige ([345% of Attack Power]) p. de daño físico y rebota contra 2 enemigos más.\n\nComienza un patrón de esgrima de guja bien ensayado, lo que mejora tu siguiente [ Caos : Golpe de caos / Fractura / Cortar ] y [ Caos : Danza de hojas /\n\nVenganza\nRajar alma ]\n La habilidad mejorada que lances primero inflige un 10% más de daño, y la segunda inflige un 20% más de daño."}
MultiLanguageSpellData['mx'][444808] = {name = "Pedido de ayuda", additional_info = nil}
MultiLanguageSpellData['mx'][444810] = {name = "Arte de la guja", additional_info = "Alcance de 8 m\nInstante\n[q]Venganza\nCuando consumes un fragmento de alma, tu siguiente inflige ([40% of Attack Power]) p. más de daño físico.\n\nCaos\nCuando consumes un fragmento de alma, tu siguiente Golpe de caos inflige ([40% of Attack Power]) p. más de daño físico.\n\n Hoja mácula consume un máximo de 5 fragmentos de alma cercanos."}
MultiLanguageSpellData['mx'][444811] = {name = "Invocar orbe titánico", additional_info = nil}
MultiLanguageSpellData['mx'][444819] = {name = "Arathi Carry Crate (DEPRECATED)", additional_info = nil}
MultiLanguageSpellData['mx'][444820] = {name = "Trampa de Forestal oscuro", additional_info = "Alcance de 20 m\nHechizo de 1.5 seg\n[q]Alleria lanza una trampa de vacío contra el objetivo, lo que lo incapacita y hace que reciba un 50% de daño aumentado durante 5 s."}
MultiLanguageSpellData['mx'][444822] = {name = "Ovación de terráneos", additional_info = nil}
