MultiLanguageSpellData['mx'][444824] = {name = "Trampa de Forestal oscuro", additional_info = "Rango ilimitado\nInstante\n[q]Alleria lanza una trampa de vacío contra el objetivo, lo que lo incapacita y hace que reciba un 50% de daño aumentado durante 5 s."}
MultiLanguageSpellData['mx'][444826] = {name = "Cadenas de hielo", additional_info = "Alcance de 30 m\nInstante\n[q]Encadena al objetivo con cadenas heladas, lo que reduce su velocidad de movimiento un 40% durante 8 s."}
MultiLanguageSpellData['mx'][444827] = {name = "Barrera reactiva", additional_info = "[q0]Talento\n[q]Escarcha\n Tu Barrera de hielo puede absorber un máximo de un 50% más de daño según tu salud faltante.\n\n Alcanza la máxima efectividad cuando la salud está por debajo del 50%.\n\nArcano\n Tu Barrera prismática puede absorber un máximo de un 50% más de daño según tu salud faltante.\n\n Alcanza la máxima efectividad cuando la salud está por debajo del 50%."}
MultiLanguageSpellData['mx'][444828] = {name = "Cadenas de hielo", additional_info = "Alcance de 100 m\nInstante\n[q]Los enemigos golpeados por Cadenas de hielo sufren de Escarcha intensa, lo que aumenta un 2% el daño que les infliges durante 20 s."}
MultiLanguageSpellData['mx'][444829] = {name = "Llamado de la reina", additional_info = "Hechizo de 3 seg\n[q]Ansurek suelta un alarido abominable que inflige 2878158 p. de daño de las sombras a todos los jugadores y pide ayuda a los acólitos invocados.\n\n Al morir, se convierten en Esencia de acólito ."}
MultiLanguageSpellData['mx'][444830] = {name = "Invocar vigía perdido", additional_info = "Alcance de 300 m\nInstante\n[q]Las criaturas se materializan en la Inmaterialidad a medida que detectan perturbaciones en el horror lazosangriento."}
MultiLanguageSpellData['mx'][444833] = {name = "Llamado de la reina", additional_info = "Instante\n[q]Ansurek suelta un alarido abominable que inflige 2878158 p. de daño de las sombras a todos los jugadores y pide ayuda a los acólitos invocados.\n\n Al morir, se convierten en Esencia de acólito ."}
MultiLanguageSpellData['mx'][444834] = {name = "Furia helada de Aterratrols", additional_info = "Alcance de 30 m\nInstante\n[q]Profano\nCuando golpea las Cadenas de hielo de Aterratrols, estas se rompen e infligen ([140.4% of Attack Power]) p. de daño de friosombra a los enemigos cercanos y los ralentiza un 40% durante 4 s. Inflige menos daño cuando afecta a más de 8 objetivos.\n\nEscarcha\nCuando Asolar y Guadaña de escarcha golpean las Cadenas de hielo de Aterratrols, estas se rompen e infligen ([140.4% of Attack Power]) p. de daño de friosombra a los enemigos cercanos y los ralentiza un 40% durante 4 s. Inflige menos daño cuando afecta a más de 8 objetivos."}
