MultiLanguageSpellData['mx'][445024] = {name = "Torbellino elemental", additional_info = "[q0]Talento\n[q]Restauración\n Motas elementales orbitan alrededor de tu Tótem volátil. Tus habilidades consumen las motas para potenciar sus efectos.\n\nAgua: Tu siguiente Ola de sanación u Oleada de sanación también sana a un aliado dentro de tu Lluvia de sanación con un 100% de efectividad.\n\nAire: [ Mejora : Tu siguiente Descarga de relámpagos, Cadena de relámpagos o Explosión elemental desata 3 Descargas volátiles contra tu Tótem volátil /\n\nElemental, Restauración\nEl tiempo de lanzamiento de tu siguiente hechizo de sanación se reduce un 40% ]\nTierra: [ Mejora : El daño directo de tu siguiente Choque de llamas aumenta un 300% y se aplica a 5 enemigos cercanos /\n\nElemental, Restauración\nTu siguiente Sanación en cadena aplica Vida terrestre con un 150% de efectividad a todos los objetivos golpeados ]\nMejora\n Motas elementales orbitan alrededor de tu Tótem volátil. Tus habilidades consumen las motas para potenciar sus efectos.\n\nAire: [ Mejora : Tu siguiente Descarga de relámpagos, Cadena de relámpagos o Explosión elemental desata 3 Descargas volátiles contra tu Tótem volátil /\n\nElemental, Restauración\nEl tiempo de lanzamiento de tu siguiente hechizo de sanación se reduce un 40% ]\nTierra: [ Mejora : El daño directo de tu siguiente Choque de llamas aumenta un 300% y se aplica a 5 enemigos cercanos /\n\nElemental, Restauración\nTu siguiente Sanación en cadena aplica Vida terrestre con un 150% de efectividad a todos los objetivos golpeados ]\nFuego: Tu siguiente Latigazo de lava o Nova de fuego te otorga Mano ardiente durante 6 s."}
MultiLanguageSpellData['mx'][445025] = {name = "Rebote totémico", additional_info = "[q0]Talento\nAproximadamente 10 activaciones por minuto\n[q]Restauración\n Ahora Sanación en cadena salta a un tótem cercano en un radio de 20 m cuando alcanza a su último objetivo, lo que hace que el tótem lance Sanación en cadena a un aliado herido en un radio de 30 m, lo que restablece ([150% of Spell Power]) p. de salud. Salta a 2 objetivos cercanos en un radio de 20 m.\n\nMejora\n Descarga de relámpagos, Cadena de relámpagos y Explosión elemental tienen una probabilidad de desatar una Descarga volátil hacia tu Tótem volátil, lo que aumenta un 10% el daño del tótem, y luego redirige la descarga a tu objetivo, lo que inflige ([92% of Attack Power]) p. de daño de naturaleza. El efecto de la bonificación de daño puede acumularse."}
MultiLanguageSpellData['mx'][445026] = {name = "Tótems gigantes", additional_info = "[q0]Talento\n[q]Aumenta un 15% el tamaño y el radio de tus tótems y un 30% su salud."}
MultiLanguageSpellData['mx'][445027] = {name = "Regreso rápido", additional_info = "[q0]Talento\n[q]Eliminar con éxito un efecto dañino con Tótem de tremor o Tótem de limpieza contraveneno, o controlar a un enemigo con Tótem capacitador o Tótem Pillaterra reduce 5 s el enfriamiento del tótem usado.\n\n No puede ocurrir más de una vez cada 20 s por tótem."}
MultiLanguageSpellData['mx'][445028] = {name = "Dominio del imbuimiento", additional_info = "[q0]Talento\n[q]Restauración\n Aumenta 3 s la duración de tu efecto Vida terrestre.\n\nMejora\n Aumenta la probabilidad de que Arma Viento Furioso se active un 5% y aumenta su daño un 8%.\n\n Cuando Arma Lengua de Fuego se activa con ataques de Arma Viento Furioso, tiene una probabilidad de generar un remolino de llamas alrededor del objetivo que inflige un 300% de su daño a todos los enemigos cercanos."}
MultiLanguageSpellData['mx'][445029] = {name = "Núcleo de amplificación", additional_info = "[q0]Talento\n[q]Mientras Tótem volátil está activo, tu daño y sanación aumentan un 3%."}
MultiLanguageSpellData['mx'][445030] = {name = "Sobrecarga de oleada", additional_info = "[q0]Talento\n[q]Restauración\n Tótem volátil inflige un 50% más de daño durante Ascensión.\n\nMejora\n Tótem volátil inflige un 50% más de daño durante Ascensión."}
MultiLanguageSpellData['mx'][445031] = {name = "Barrera de viento", additional_info = "[q0]Talento\n[q]Si tienes un tótem activo, tu tótem te otorga un escudo que absorbe ([Total Health] * 6 / 100) p. de daño durante 30 s cada 30 s."}
MultiLanguageSpellData['mx'][445032] = {name = "Condensador de pulsos", additional_info = "[q0]Talento\n[q]Mejora\n Aumenta un 18% el daño de Tótem volátil.\n\nRestauración\n Aumenta un 25% la sanación realizada por Tótem volátil."}
MultiLanguageSpellData['mx'][445033] = {name = "Imbuimientos de apoyo", additional_info = "[q0]Talento\n[q]Restauración\n Aprendes un nuevo imbuimiento de arma, Protección del clamamareas.\n\n Protección del clamamareas\nImbuye tu escudo con el elemento de agua durante 1 h. Tu sanación realizada aumenta un 2.0% y la duración de tu Tótem Corriente de sanación y Tótem de Ráfaga de nubes aumenta 3.0 s. \n\nMejora\n Aumenta un 25% la probabilidad de golpe crítico de Arma Lengua de Fuego, y un 100% su daño de golpe crítico."}
MultiLanguageSpellData['mx'][445034] = {name = "Tótems animados", additional_info = "[q0]Talento\n[q]Restauración\n Cuando invocas un Tótem de Marea de sanación, Tótem Corriente de sanación, Tótem de Ráfaga de nubes o Tótem Enlace de espíritu, lanzas al instante y sin costo Sanación en cadena con un 100% de efectividad.\n\nMejora\n Latigazo de lava tiene una probabilidad de invocar un Tótem abrasador para lanzar Descargas abrasadoras que infligen ([65.205% of Spell Power]) p. de daño de fuego a un enemigo cercano. Dura 8 s.\n\n Los Choques de escarcha potenciados por Granizada, Latigazo de lava y Nova de fuego hacen que tus Tótems abrasadores disparen una Salva ardiente que inflige ([92.736% of Spell Power]) p. de daño de fuego a un máximo de 5 enemigos cercanos."}
MultiLanguageSpellData['mx'][445035] = {name = "Reactividad", additional_info = "[q0]Talento\n[q]Mejora\n Mientras Mano ardiente está activa, Latigazo de lava raja la tierra y provoca un Hendimiento con un 50% de efectividad.\n\n Los Hendimientos provocados con este efecto no incapacitan.\n\nRestauración\n Tus Tótems Corriente de sanación ahora también sanan a un segundo aliado con un 100% de efectividad.\n\n Tótem de Ráfaga de nubes almacena un 25% más de sanación."}
MultiLanguageSpellData['mx'][445036] = {name = "Coordinación totémica", additional_info = "[q0]Talento\n[q]Mejora\n Aumenta un 15% la probabilidad de golpe crítico de los ataques de tu Tótem abrasador y un 30% su daño de golpe crítico.\n\nRestauración\n Las Sanaciones en cadena de Tótem animado y Rebote totémico son un 25% más efectivas."}
