MultiLanguageSpellData['mx'][445323] = {name = "[q4]Caña de piedra nula con runas", additional_info = "Hechizo de 3.5 seg 2\nHerramientas: Vara de encantamiento con runas\nComponentes:\nAgudeza del artesano (400), Lingote de las Minas Resonantes (2), Piedra nula , Polvo de tormenta (100), Esquirla brillante (10)\nComponentes opcionales:\nPersonaliza estadística de fabricación (#345) , Encantamientos y equipo (#378) , Autenticidad del artesano (#354)\nVendedor:\nLyrendal\nZona:\nDornogal\nCosto:\n150\n\n[q4]Vara de piedra nula rúnica\nSe liga al recogerlo\nHerramienta de Encantamiento\n[q2]+ 125 Estadística aleatoria 1\n[q2]Equipar: +18 p. de habilidad en encantamiento de Khaz Algar\n[q2]Equipar: Usas un 1% menos de concentración al concentrarte en las fórmulas de encantamiento de Khaz Algar.\nNecesitas ser de nivel 68\n[q]\"Sirve como una vara de encantamiento rúnica.\""}
MultiLanguageSpellData['mx'][445324] = {name = "[q3]Varita de troncolanza encantada", additional_info = "Hechizo de 3.5 seg 3\nHerramientas: Vara de encantamiento con runas\nComponentes:\nPolvo de tormenta (5), Floresta codificada\nComponentes opcionales:\nPotenciar (#342) , Agrega ornamento (#341) , Personaliza estadísticas secundarias (#365) , Encantamientos y equipo (#378) , Autenticidad del artesano (#354)\nInstructor de profesión:\nEncantamiento de Khaz Algar (40)\nCosto:\n150\n\n[q3]Varita de troncolanza encantada\nSe liga al equiparlo\nA distancia Varita\n270 - 451 p. de daño de Sombras Velocidad 2.00\n(180.3 p. de daño por segundo)\n+1.847 intelecto\n+1.162 aguante\n[q2]+ 222 Estadística aleatoria 1\n[q2]+ 222 Estadística aleatoria 2\nDurabilidad 90 / 90\nNecesitas ser de nivel 72"}
MultiLanguageSpellData['mx'][445347] = {name = "[q4]Emblema de la Emisaria rúnico encantado", additional_info = "Hechizo de 3.5 seg 2\nHerramientas: Vara de encantamiento con runas\nComponentes:\nEmblema de la Emisaria rúnico naciente , Polvo de tormenta (60), Esquirla brillante (10), Cristal refulgente\nBotín:\nAventuras en Khaz Algar\n\n[q4]Emblema de la Emisaria rúnico encantado\nSe liga al recogerlo\nComponente de fabricación opcional\n[q2]+10 Dificultad de fórmula:\n[q2]Otorga la siguiente propiedad: Fija el nivel de objeto entre 606 y 619 según la calidad de fabricación.\n[q]Puede usarse con: Recetas de Khaz Algar para equipamiento épico fabricado con una chispa de augurios.\n[q]\"Un componente poderoso creado por encantadores.\""}
MultiLanguageSpellData['mx'][445354] = {name = "[q4]Emblema de la Emisaria dorado bajo encantamiento", additional_info = "Hechizo de 3.5 seg 3\nHerramientas: Vara de encantamiento con runas\nComponentes:\nEmblema de la Emisaria dorado naciente , Polvo de tormenta (100), Esquirla brillante (15), Cristal refulgente (2)\nBotín:\nAventuras en Khaz Algar\n\n[q4]Emblema de la Emisaria dorado bajo encantamiento\nSe liga al recogerlo\nComponente de fabricación opcional\n[q2]+20 Dificultad de fórmula:\n[q2]Otorga la siguiente propiedad: Fija el nivel de objeto entre 623 y 636 según la calidad de fabricación.\n[q]Puede usarse con: Recetas de Khaz Algar para equipamiento épico fabricado con una chispa de augurios.\n[q]\"Un componente poderoso creado por encantadores.\""}
MultiLanguageSpellData['mx'][445355] = {name = "[q4]Cetro de magia radiante", additional_info = "Hechizo de 3.5 seg 3\nHerramientas: Vara de encantamiento con runas\nComponentes:\nCaja de yesca profanada (2), Esquirla brillante (6), Cristal refulgente (2), Floresta codificada , Chispa (#256)\nComponentes opcionales:\nInfunde con poder (#366) , Agrega ornamento (#341) , Personaliza estadísticas secundarias (#365) , Encantamientos y equipo (#378) , Autenticidad del artesano (#354) , Aumento mayor (#384)\nEspecialización:\nEfímeros, enriquecedores y equipamiento - Creaciones de combate\n\n[q4]Cetro de magia radiante\nSe liga al recogerlo\nA distancia Varita\n907 - 1,513 p. de daño de Fuego Velocidad 2.00\n(605.0 p. de daño por segundo)\n+6.201 intelecto\n+4.874 aguante\n[q2]+ 364 Estadística aleatoria 1\n[q2]+ 364 Estadística aleatoria 2\nDurabilidad 110 / 110\nNecesitas ser de nivel 70"}
