MultiLanguageSpellData['mx'][445475] = {name = "Ráfaga sureki", additional_info = "Instante\n[q]Saca un arco del arsenal para desatar una andanada de flechas frente a ti, lo que inflige ( 1 * 1478 ) p. de daño de las sombras a todos los enemigos en un radio de 20 m.\n\n Hasta que desenfundes la siguiente arma, permaneces en tu lugar para aumentar tu velocidad un 6% durante 6 s al moverte. Este efecto aumenta un 6% más cada 2 s, hasta 5 veces."}
MultiLanguageSpellData['mx'][445479] = {name = "[q2]Néctar de cenizas", additional_info = "Hechizo de 2 seg\nComponentes:\nBota de agua de surcabismos (3), Panal caliente\nComponentes opcionales:\nIngrediente secreto (#318)\n[q]Receta para 10 porciones. El número real de porciones varía según la habilidad en la cocina.\nVendedor:\nCendvin\nZona:\nIsla de Dorn\nCosto:\n120\n\n[q2]Néctar de cenizas\n[q2]Uso: Restaura ( 937500 / 5 * 20) p. de maná durante 20 s. Debes permanecer sentado mientras bebes.\nNecesitas ser de nivel 68"}
MultiLanguageSpellData['mx'][445480] = {name = "[q2]Energía para el día", additional_info = "Hechizo de 2 seg\nComponentes:\nBota de agua de surcabismos (5)\nComponentes opcionales:\nIngrediente secreto (#318)\n[q]Receta para 1 porciones. El número real de porciones varía según la habilidad en la cocina.\nVendedora:\nCapitana Juramitos\nZona:\nCristalia\nCosto:\n10\n\n[q2]Energía para el día\n[q2]Uso: Restaura ( 937500 / 5 * 20) p. de maná durante 20 s. Debes permanecer sentado mientras bebes.\n\n Energía para el día\n Si bebes durante al menos 10 s, obtendrás 167 p. de velocidad de movimiento y la habilidad de caminar sobre el agua durante 10 min.\nNecesitas ser de nivel 68"}
MultiLanguageSpellData['mx'][445482] = {name = "[q2]Batido rocoso", additional_info = "Hechizo de 2 seg\nComponentes:\nBota de agua de surcabismos (5), Revuelto esponjoso (3), Panal caliente , Bismuto (10)\nComponentes opcionales:\nIngrediente secreto (#318)\n[q]Receta para 10 porciones. El número real de porciones varía según la habilidad en la cocina.\nVendedora:\nCapitana Juramitos\nZona:\nCristalia\nCosto:\n10\n\n[q2]Batido rocoso\n[q2]Uso: No está para nada mezclado... (5 Min Reutilización)\nNecesitas ser de nivel 68\n[q]\"El bocadillo terráneo perfecto para un día caluroso en Khaz Algar.\""}
MultiLanguageSpellData['mx'][445483] = {name = "[q2]Bocadillo dulce pegajoso", additional_info = "Hechizo de 2 seg\nComponentes:\nRevuelto esponjoso (3), Panal caliente , Cúmulos de harina (5), Polvo del Paso Horadado (5)\nComponentes opcionales:\nIngrediente secreto (#318)\n[q]Receta para 10 porciones. El número real de porciones varía según la habilidad en la cocina.\nBotín:\nDeformalinajes Ovi'nax\nZona:\nPalacio Nerub-ar\nReceta:\nSe puede comprar en la casa de subastas\n\n[q2]Bocadillo dulce pegajoso\n[q2]Uso: ¡Un niño otra vez! (5 Min Reutilización)\nNecesitas ser de nivel 68\n[q]\"La miel de cenizabeja de los complejos de cuevas de arriba es un manjar para un joven nerubiano.\""}
MultiLanguageSpellData['mx'][445484] = {name = "[q2]Vela derretida", additional_info = "Hechizo de 2 seg\nComponentes:\nRevuelto esponjoso (3), Panal caliente , Cúmulos de harina (5)\nComponentes opcionales:\nIngrediente secreto (#318)\n[q]Receta para 10 porciones. El número real de porciones varía según la habilidad en la cocina.\nVendedora:\nCapitana Juramitos\nZona:\nCristalia\nCosto:\n10\n\n[q2]Vela derretida\n[q2]Uso: ¿Qué tiene de malo intentarlo? (5 Min Reutilización)\nNecesitas ser de nivel 68\n[q]\"Una mezcla perfecta de algo crujiente y masticable. Uno no compartiría esto con nadie.\""}
