MultiLanguageSpellData['mx'][445494] = {name = "Asalto de red", additional_info = "Rango ilimitado\nInstante\n[q]Rasha'nan cubre el área objetivo, inflige 56987520 p. de daño de naturaleza y atrae a los jugadores hacia ella. Estos efectos se dividen equitativamente entre los jugadores que están en un radio de 8 m del impacto.\n\n Si Asalto de red no golpea al menos a 4 objetivos, todos los jugadores sufren el efecto completo."}
MultiLanguageSpellData['mx'][445495] = {name = "Consumir llama", additional_info = "Alcance de 100 m\nInstante\n[q]Preservación\nEnvolver consume 2 s de Aliento de ensueño del objetivo, lo que provoca que detone y sane a todos los objetivos cercanos por un monto equivalente al 900% de la cantidad consumida. Se reduce si afecta a más de 5 objetivos.\n\nDevastación\nEnvolver consume 2 s de Aliento de fuego del objetivo, lo que provoca que detone y dañe a todos los objetivos cercanos por un monto equivalente al 900% de la cantidad consumida. Se reduce si afecta a más de 5 objetivos."}
MultiLanguageSpellData['mx'][445497] = {name = "Triturar", additional_info = "Alcance de 20 mHechizo de 2 seg 6 seg de reutilización\n[q]Tritura a un enemigo, lo que lo hace sangrar por p. de daño físico y daño físico adicional cada 1 s durante 5 s. Este efecto se acumula."}
