MultiLanguageSpellData['mx'][447867] = {name = "Kah, Rey de las profundidades", additional_info = "Hechizo de 3.2 seg\n[q]Su piel pálida y enfermiza deja entrever un cuerpo esquelético, distorsionado por la sangre de los dioses antiguos. Los pescadores de todo Khaz Algar se refieren a este pez como un emisario de la ruina que maldice a cualquiera que tenga la mala fortuna de capturarlo con su caña. Mirar a los ojos a esta criatura no hace más que reafirmar su envilecimiento: cualquier tipo de reflejo es consumido por su abismo."}
MultiLanguageSpellData['mx'][447868] = {name = "[q3]Tratado algariano sobre inscripción", additional_info = "Hechizo de 3.5 seg\nComponentes:\nResiduo de línea ley (2), Clave infinita , Tinta cobalto (2)\nEspecialización:\nBúsqueda de conocimiento\n\n[q3]Tratado algari sobre inscripción\n[q7]Se liga a la tropa\n[q2]Uso: Estudia para aumentar 1 p. tu conocimiento de inscripción en Khaz Algar. (5 Seg Reutilización)\nRequiereInscripción de Khaz Algar\n(25)"}
MultiLanguageSpellData['mx'][447869] = {name = "Polvo de huevo de primera", additional_info = "Hechizo de 2 seg\n[q]Receta para 5 porciones. El número real de porciones varía según la habilidad en la cocina.\nVendedor:\nPolo\nZona:\nCiudad de los Hilos\nCosto:\n1500"}
MultiLanguageSpellData['mx'][447870] = {name = "Todo-en-un-pincho", additional_info = "Hechizo de 2 seg\nComponentes:\nYema coagulada\n[q]Receta para 2 porciones. El número real de porciones varía según la habilidad en la cocina.\nVendedor:\nVendedores del mundo de Khaz Algar\nCosto:\n1500"}
MultiLanguageSpellData['mx'][447871] = {name = "Sorbo de proteína", additional_info = "Hechizo de 2 seg\nComponentes:\nPolvo de huevo de primera (5)\n[q]Receta para 1 porciones. El número real de porciones varía según la habilidad en la cocina.\nVendedora:\n\"Octosacudidora\" Cetrina\nZona:\nCiudad de los Hilos\nCosto:\n1500"}
MultiLanguageSpellData['mx'][447872] = {name = "[q2]Revuelto esponjoso", additional_info = "Hechizo de 2 seg\nComponentes:\nBota de agua de surcabismos , Polvo de huevo de primera (10)\nComponentes opcionales:\nIngrediente secreto (#318)\n[q]Receta para 1 porciones. El número real de porciones varía según la habilidad en la cocina.\nVendedor:\nPolo\nZona:\nCiudad de los Hilos\nCosto:\n1500\n\n[q2]Revuelto esponjoso\n[q2]Uso: Restaura ( 375000 / 5 * 20) p. de salud durante 20 s. Debes permanecer sentado mientras comes.\n\n Bien alimentado \nSi comes durante al menos 10 s, quedarás Bien alimentado y obtendrás [ 470 * (0.7)] p. de tu estadística secundaria más baja durante 15 min.\nNecesitas ser de nivel 68"}
MultiLanguageSpellData['mx'][447873] = {name = "[q3]Salsa secreta", additional_info = "Hechizo de 2 seg\nComponentes:\nPolvo de huevo de primera (5), Yema coagulada , Bota de agua de surcabismos\n[q]Receta para 1 porciones. El número real de porciones varía según la habilidad en la cocina.\nDescubrimiento:\nIngredientes preparados - Polvo de huevo de primera\n\n\n[q3]Salsa secreta\nNecesitas ser de nivel 68"}
MultiLanguageSpellData['mx'][447874] = {name = "[q2]Galletas de amiguito", additional_info = "Hechizo de 2 seg\nComponentes:\nYema coagulada , Revuelto esponjoso (4), Cúmulos de harina (5)\nComponentes opcionales:\nIngrediente secreto (#318)\n[q]Receta para 3 porciones. El número real de porciones varía según la habilidad en la cocina.\nVendedora:\nTyro Whalekk\nZona:\nCiudad de los Hilos\nCosto:\n1500\n\n[q2]Galletas de amiguito\n[q2]Uso: Sana y resucita a todas tus mascotas de duelo con un 100% de salud.\nNecesitas ser de nivel 68\n[q]\"¡Hechas con amiguitos de verdad!\""}
MultiLanguageSpellData['mx'][447875] = {name = "[q2]Especialidad de Azj-Kahet", additional_info = "Hechizo de 2 seg\nComponentes:\nBota de agua de surcabismos , Yema coagulada\nComponentes opcionales:\nIngrediente secreto (#318)\n[q]Receta para 1 porciones. El número real de porciones varía según la habilidad en la cocina.\nVendedor:\nAx'ill\nZona:\nCiudad de los Hilos\nCosto:\n1500\n\nVendedora:\nTej, la Indestructible\nZona:\nCiudad de los Hilos\nCosto:\n1500\n\n[q2]Especialidad de Azj-Kahet\n[q2]Uso: Aumenta tu velocidad de movimiento un 20% mientras estás en la Ciudad de los Hilos. Solo se puede usar en exteriores.\nNecesitas ser de nivel 68\n[q]\"¡Un paseo por la ciudad!\""}
MultiLanguageSpellData['mx'][447876] = {name = "[q3]Delicia de pez demonio", additional_info = "Hechizo de 2 seg\nComponentes:\nPez demonio preparado , Estofado simple\nComponentes opcionales:\nIngrediente secreto (#318)\n[q]Receta para 5 porciones. El número real de porciones varía según la habilidad en la cocina.\nVendedora:\nCapitana Juramitos\nZona:\nCristalia\nCosto:\n10\n\n[q3]Delicia de necrófago\nSe liga al recogerlo\n[q2]Uso: Restaura ( 375000 / 5 * 20) p. de salud durante 20 s. Debes permanecer sentado mientras comes.\n\n Bien alimentado\n Si comes durante al menos 10 s, quedarás Bien alimentado y obtendrás 30 p. de habilidad de pesca de Khaz Algar y 150 p. de percepción durante 1 h.\nNecesitas ser de nivel 75\n[q]\"Lo que para un pescador es su peor pesadilla, para un chef es un manjar\""}
