MultiLanguageSpellData['mx'][449571] = {name = "Hierbas mercúricas", additional_info = "Hechizo de 3 seg 1 día reutilización\n3 cargas\nHerramientas: Piedra filosofal\nComponentes:\nTransmutágeno de mercurio (6), Transmutágeno volátil (3)\nDescubrimiento:\nTaumaturgia"}
