MultiLanguageSpellData['mx'][449573] = {name = "Coalescencia mercúrica", additional_info = "Hechizo de 3 seg 1 día reutilización\n3 cargas\nHerramientas: Piedra filosofal\nComponentes:\nTransmutágeno volátil (6), Transmutágeno ominoso (6)\n[q]Combina transmutágenos ominosos y volátiles con el poder de tu piedra filosofal para crear un transmutágeno de mercurio.\nEspecialización:\nTaumaturgia - Materiales de mercurio"}
MultiLanguageSpellData['mx'][449574] = {name = "Coalescencia ominosa", additional_info = "Hechizo de 3 seg 1 día reutilización\n3 cargas\nHerramientas: Piedra filosofal\nComponentes:\nTransmutágeno volátil (6), Transmutágeno de mercurio (6)\n[q]Combina transmutágenos de mercurio y volátiles con el poder de tu piedra filosofal para crear un transmutágeno ominoso.\nEspecialización:\nTaumaturgia - Materiales ominosos"}
