MultiLanguageSpellData['mx'][449629] = {name = "Fervor demoníaco", additional_info = "[q0]Talento\n[q]Demonología\n Tu alma demoníaca inflige un 100% más de daño a el objetivo principal de Mano de Gul'dan.\n\nAflicción\n Tu alma demoníaca inflige un 100% más de daño a los objetivos afectados por tu Aflicción inestable."}
MultiLanguageSpellData['mx'][449631] = {name = "Estímulo malvado", additional_info = "[q0]Talento\n[q]Demonología\n El daño que inflige tu alma demoníaca aumenta un 10%.\n\n Consumir Núcleo demoníaco alimenta a la entidad demoníaca en tu interior, lo que hace que aparezca e inflija [([240.402% of Spell Power]) * 0.4] p. de daño de las sombras a tu objetivo.\n\nAflicción\n El daño que inflige tu alma demoníaca aumenta un 10%.\n\n Consumir Ocaso alimenta a la entidad demoníaca en tu interior, lo que hace que aparezca e inflija ([240.402% of Spell Power]) p. de daño de las sombras a tu objetivo."}
