MultiLanguageSpellData['mx'][450988] = {name = "Uno contra muchos", additional_info = "[q0]Talento\n[q]El daño infligido con Puños de furia y Embate con barril cuenta el doble para la generación de Carga de aluvión.\n\n El daño de Puños de furia aumenta un 20%.\n El daño de Embate con barril aumenta un 35%."}
MultiLanguageSpellData['mx'][450989] = {name = "Entrenamiento eficiente", additional_info = "[q0]Talento\n[q]Maestro cervecero\n Las habilidades que consumen energía infligen un 20% más de daño.\n Cada 50 p. de energía consumidos, se reduce 1 s el tiempo de reutilización de Armas de orden.\n\nViajero del viento\n Las habilidades que consumen energía infligen un 40% más de daño.\n Cada 50 p. de energía consumidos, se reduce 1 s el tiempo de reutilización de Tormenta, Tierra y Fuego."}
MultiLanguageSpellData['mx'][450990] = {name = "Precisión marcial", additional_info = "[q0]Talento\n[q]Tus ataques penetran un 12% de armadura."}
MultiLanguageSpellData['mx'][450991] = {name = "Acero giratorio", additional_info = "[q0]Talento\n[q]Cuando tu salud cae por debajo del 50%, invocas Acero giratorio, que aumenta un 15% tu probabilidad de parar y eludir durante 6 s.\n\n Este efecto no puede ocurrir más de una vez cada 180 s.\n(3m de reutilización)"}
MultiLanguageSpellData['mx'][450992] = {name = "Entrenamiento predictivo", additional_info = "[q0]Talento\n[q]Cuando esquivas o paras un ataque, reduces un 10% todo el daño recibido durante los próximos 6 s."}
MultiLanguageSpellData['mx'][450993] = {name = "Vigilancia alerta", additional_info = "[q0]Talento\n[q]Patada oscura inflige un 20% más de daño crítico y aumenta un 10% el daño de tu siguiente conjunto de Golpes en aluvión."}
MultiLanguageSpellData['mx'][450994] = {name = "Sabiduría del muro", additional_info = "[q0]Talento\n[q]Cada 10 Golpes en aluvión, te infunde la Sabiduría del muro y obtienes uno de los siguientes efectos durante 16 s.\n\nEl daño de golpe crítico aumenta un 30%.\n\nLa probabilidad de esquivar y de golpe crítico aumentan un 25% según tu bonificación de versatilidad.\n\nGolpes en aluvión inflige ([160% of Attack Power]) p. de daño de las sombras a todos los enemigos que no estén bajo los efectos de control de masas en un radio de 6 m.\n\nEl efecto de tu Maestría aumenta un 25%."}
MultiLanguageSpellData['mx'][450995] = {name = "Vela de expectochispas", additional_info = "Alcance de 100 m\nInstante\n[q]Ocasionalmente inflige daño de fuego adicional al atacar."}
