MultiLanguageSpellData['mx'][451016] = {name = "Destrozar existencia", additional_info = "Alcance de 70 m\nHechizo de 6 seg\n[q]Takazj se escuda a sí misma y absorbe 392587563 p. de daño.\n\n Mientras el escudo está activo, Takazj desata una Tromba entrópica cada 16 s y hace girar conos de telarañas por toda la cámara. Estas telarañas disminuyen el movimiento del jugador un 20% e infligen 230253 p. de daño de las sombras cada 1 s a los jugadores dentro del área.\n\n Las telarañas explotan periódicamente, repelen a los jugadores, y les infligen 8058841 p. de daño de las sombras y 1381516 p. de daño de las sombras más cada 3 s durante 12 s."}
MultiLanguageSpellData['mx'][451017] = {name = "Claridad de propósito", additional_info = "[q0]Talento\n[q]Maestro cervecero\n Lanzar Brebaje purificador almacena [(Poder con Hechizos * 100 / 100) * (1 + Versatilidad)] p. de vitalidad, según el nivel de Aplazar.\n\nTejedor de niebla\n Lanzar Vivificar almacena [(Poder con Hechizos * 100 / 100) * (1 + Versatilidad)] p. de vitalidad, según tus Ráfagas de niebla recientes."}
MultiLanguageSpellData['mx'][451018] = {name = "Energía oscura", additional_info = "[q0]Talento\n[q]Disciplina\n Mientras Falla entrópica está activa, te mueves un 20% más rápido.\n\nSombra\n Puedes usar Torrente del vacío en movimiento. Mientras Falla entrópica está activa, te mueves un 20% más rápido."}
MultiLanguageSpellData['mx'][451021] = {name = "Carga de aluvión", additional_info = "Instante\n[q]Cada [(Poder de ataque * 6.25 * (1 + Versatilidad))] p. de daño que infliges, generas una Carga de aluvión. Por cada 240 p. de energía que gastas, desata todas las Cargas de aluvión, lo que inflige ([60% of Attack Power]) p. de daño físico por carga."}
