MultiLanguageSpellData['mx'][451609] = {name = "Bomba de telaraña", additional_info = "Rango ilimitado\nInstante\n[q]La hilamadejas Takazj lanza telarañas explosivas contra los jugadores que infligen 20 p. de daño de naturaleza a todos los jugadores en un radio de 10m.\n\n Si más de un jugador está en el área, quedan atrapados por unas Telarañas inmovilizadoras que reducen un 20 % el movimiento.\n\n Si los jugadores atados se alejan más de 30 m o si Anub'arash atraviesa las telarañas, se romperán y se eliminarán las Telarañas inmovilizadoras ."}
MultiLanguageSpellData['mx'][451610] = {name = "Bomba de telaraña", additional_info = "Rango ilimitado\nInstante\n[q]Takazj lanza nudos de telaraña por toda la sala, lo que reduce un 20% la velocidad de movimiento de los jugadores e inflige 345379 p. de daño físico cada 1 s mientras están en el área.\n\n El nudo central hace erupción cuando lo tocan, lo que inflige 1732248 p. de daño de naturaleza a los jugadores en un radio de 10 m y ata a dos jugadores con Telarañas inmovilizadoras .\n\n Si Anub'arash arremete a través de hilos de Telarañas inmovilizadoras, queda Enredado."}
MultiLanguageSpellData['mx'][451611] = {name = "Objetivo de bomba de telaraña", additional_info = "Alcance de 100 m\nInstante\n[q]Takazj lanza nudos de telaraña por toda la sala, lo que reduce un 20% la velocidad de movimiento de los jugadores e inflige 345379 p. de daño físico cada 1 s mientras están en el área.\n\n El nudo central hace erupción cuando lo tocan, lo que inflige 1732248 p. de daño de naturaleza a los jugadores en un radio de 10 m y ata a dos jugadores con Telarañas inmovilizadoras .\n\n Si Anub'arash arremete a través de hilos de Telarañas inmovilizadoras, queda Enredado."}
