MultiLanguageSpellData['mx'][452402] = {name = "Oleada demoníaca", additional_info = "[q0]Talento\n[q]Caos\n Metamorfosis ahora también hace que Mordedura de demonio genere 15 p. más de furia.\n\n Mientras la forma de demonio está activa, el primer lanzamiento de cada habilidad potenciada genera una Oleada demoníaca que hace que explotes con energía vil e inflijas ([330% of Attack Power]) p. de daño de fuego a los enemigos cercanos. Inflige menos daño si golpea a más de 8 objetivos.\n\nVenganza\n Metamorfosis ahora también potencia enormemente Rajar alma y Bomba de espíritu.\n\n Mientras la forma de demonio está activa, el primer lanzamiento de cada habilidad potenciada genera una Oleada demoníaca que hace que explotes con energía vil e inflijas ([330% of Attack Power]) p. de daño de fuego a los enemigos cercanos. Inflige menos daño si golpea a más de 8 objetivos."}
MultiLanguageSpellData['mx'][452403] = {name = "Ola de debilitamiento", additional_info = "[q0]Talento\n[q]Nova de caos ralentiza a los enemigos un 60% y reduce la velocidad de ataque y lanzamiento un 15% durante 5 s después de que termina el aturdimiento."}
MultiLanguageSpellData['mx'][452404] = {name = "Persecución de la ira", additional_info = "[q0]Talento\n[q]La velocidad de movimiento aumenta un 1% por cada 10 p. de furia."}
MultiLanguageSpellData['mx'][452405] = {name = "Odio concentrado", additional_info = "[q0]Talento\n[q]Oleada demoníaca inflige un 50% más de daño cuando golpea a un solo objetivo.\n\n Cada objetivo adicional reduce un 10% esta bonificación."}
MultiLanguageSpellData['mx'][452406] = {name = "Dolor en llamas", additional_info = "[q0]Talento\n[q]Un 5% de todo el daño recibido que no sea de fuego se recibe como daño de Fuego durante 6 s.\n\n El daño de fuego recibido se reduce un 10%."}
MultiLanguageSpellData['mx'][452407] = {name = "Desgarre de alma mejorado", additional_info = "[q0]Talento\n[q]El robo de vida otorgado por Desgarre de alma aumenta un 2% y un 2% más mientras Metamorfosis está activa."}
MultiLanguageSpellData['mx'][452408] = {name = "Filos ardientes", additional_info = "[q0]Talento\n[q]Caos\n Tus espadas arden con energía vil, lo que hace que tus Golpe de caos, Lanzar guja y ataques automáticos inflijan un 50% más de daño como daño de fuego durante 6 s.\n\nVenganza\n Tus espadas arden con energía vil, lo que hace que tus Rajar alma, Lanzar guja y ataques automáticos inflijan un 40% más de daño como daño de fuego durante 6 s."}
MultiLanguageSpellData['mx'][452409] = {name = "Transformación violenta", additional_info = "[q0]Talento\n[q]Caos\n Cuando activas Metamorfosis, los tiempos de reutilización de tu Sigilo de la llama y Aura de inmolación se restablecen de inmediato.\n\nVenganza\n Cuando activas Metamorfosis, los tiempos de reutilización de tu Sigilo de la llama y Devastación vil se restablecen de inmediato."}
MultiLanguageSpellData['mx'][452410] = {name = "Tormento duradero", additional_info = "[q0]Talento\n[q]Caos\n Los efectos de tu Forma de demonio persisten fuera de ella en un estado debilitado, lo que aumenta un 15% el daño de Golpe de caos y Danza de hojas, y un 5% la celeridad.\n\nVenganza\n Los efectos de tu Forma de demonio persisten fuera de ella en un estado debilitado, lo que aumenta un 5% la salud máxima y un 20% la armadura."}
MultiLanguageSpellData['mx'][452411] = {name = "Furia sin ataduras", additional_info = "[q0]Talento\n[q]La furia máxima aumenta 50 p."}
MultiLanguageSpellData['mx'][452412] = {name = "Estudiante del sufrimiento", additional_info = "[q0]Talento\n[q]Sigilo de la llama te aplica Estudiante del sufrimiento, lo que aumenta un (8 * $mas)% la maestría y otorga 5 p. de furia cada 2 s durante 6 s."}
