MultiLanguageSpellData['mx'][453245] = {name = "Poción detonante de poder", additional_info = "Rango ilimitado\nInstante\n[q]Lanza una poción detonante que salpica hasta 5 aliados con una infusión explosiva que aumenta ( 44 / 5) p. su estadística principal durante 30 s.\n\n Los enemigos atrapados en la explosión sufren 255 p. de daño de fuego, que se reparten entre ellos."}
MultiLanguageSpellData['mx'][453247] = {name = "Coágulo explosivo", additional_info = "Alcance de 100 m\nInstante\n[q]Alimenta el coágulo, lo que redirige un 20% de toda la sanación realizada hasta consumir ( 10669 * 40 / 100) p. de sanación. Una vez saciado, el coágulo explota y sana [( 10669 + ( 10669 * 40 * .01 * 1.03)) / 5] p. a 5 aliados.\n\n El efluvio que persiste hace que los próximos ataques de los aliados afectados inflijan 76 p. más de daño de las sombras, lo que aumenta según la cantidad de sanación en exceso realizada por el coágulo."}
MultiLanguageSpellData['mx'][453250] = {name = "Cristalización", additional_info = "Instante\n[q]Aumenta [Primary Stat] 733 p. durante 1 h. Runa de aumento."}
MultiLanguageSpellData['mx'][453251] = {name = "Bomba viva", additional_info = "Rango ilimitado\nInstante\n[q]El objetivo se convierte en una Bomba viva y recibe 4 p. de daño de fuego durante 2 s. Luego explota para infligir ([26.8% of Spell Power]) p. más de daño de fuego al objetivo y daño reducido a todos los demás enemigos en un radio de 10 m.\n\n Otros enemigos golpeados por esta explosión también se convierten en una Bomba viva, pero no pueden propagar el efecto."}
