MultiLanguageSpellData['mx'][453377] = {name = "Efluvio persistente", additional_info = "Alcance de 100 m\nInstante\n[q]Alimenta el coágulo, lo que redirige un 20% de toda la sanación realizada hasta consumir ( 10669 * 40 / 100) p. de sanación. Una vez saciado, el coágulo explota y sana [( 10669 + ( 10669 * 40 * .01 * 1.03)) / 5] p. a 5 aliados.\n\n El efluvio que persiste hace que los próximos ataques de los aliados afectados inflijan 76 p. más de daño de las sombras, lo que aumenta según la cantidad de sanación en exceso realizada por el coágulo."}
MultiLanguageSpellData['mx'][453381] = {name = "Pizarra pulida de erosión", additional_info = "Alcance de 5 m\nHechizo de 5.3 seg\n[q]A veces, una roca es simplemente una roca. Otras veces es una roca muy bonita que merece la pena estudiar. No es de extrañar que haya muchas rocas en Khaz Algar y sus alrededores, pero algunas de ellas pueden ser útiles para perfeccionar las técnicas de minería.\n\n Podrás descubrir 5 muestra(s) más esta semana."}
MultiLanguageSpellData['mx'][453385] = {name = "Ira del fuego", additional_info = "Instante\n[q]Cuando no estás bajo el efecto de Combustión, tu probabilidad de golpe crítico aumenta un 2.5%.\n\n Mientras estás bajo el efecto de Combustión, tu daño de golpe crítico aumenta un 2.5%."}
