MultiLanguageSpellData['mx'][454426] = {name = "Fatalidad entregada", additional_info = "[q0]Talento\n[q]Cuando sale cruz en tu moneda sinoatada aumenta un 30% el daño infligido si no hay otros enemigos cerca del objetivo.\n\n Cada enemigo cercano adicional reduce un 6% esta bonificación."}
MultiLanguageSpellData['mx'][454428] = {name = "Final fatídico", additional_info = "[q0]Talento\n[q]Cuando tu moneda sinoatada sale con la misma cara por séptima vez consecutiva, conservas la moneda de la suerte y obtienes un 7% de agilidad durante 10 s hasta que abandonas el combate. Si ya tienes una moneda de la suerte, en cambio, inflige ([420% of Attack Power]) p. de daño cósmico a tu objetivo."}
MultiLanguageSpellData['mx'][454429] = {name = "Destino entrelazado", additional_info = "[q0]Talento\n[q]Forajido\n Destino entrelazado duplica un 30% del daño de golpe crítico de Despachar como daño cósmico a 2 enemigos cercanos más. Si no hay objetivos adicionales cercanos, duplica un 30% del daño al objetivo principal.\n\nAsesinato\n Destino entrelazado duplica un 30% del daño de golpe crítico de Envenenar como daño cósmico a 2 enemigos cercanos más. Si no hay objetivos adicionales cercanos, duplica un 30% del daño al objetivo principal."}
MultiLanguageSpellData['mx'][454430] = {name = "Doble riesgo", additional_info = "[q0]Talento\n[q]Tu primer lanzamiento de una moneda sinoatada después de salir del sigilo lanzará dos monedas que coincidirán con el mismo resultado."}
MultiLanguageSpellData['mx'][454431] = {name = "[q4]La cartera cortada", additional_info = "Hechizo de 2 seg 2\nComponentes:\nCinta decorativa (2), Madeja de tejido del crepúsculo (5), Madeja de tejido del alba (5)\nComponentes opcionales:\nHilo de bordado (#333)\nEspecialización:\nTejido de calidad (25)\n\n[q4]La cartera cortada\nSe liga al recogerlo\nÚnico\nBolsa de 36 casillas\n[q2]Equipar: Aumenta 1 p. la capacidad de producción máxima del deshilvanado de Khaz Algar.\n\n [ El efecto del equipamiento requiere sastrería de Khaz Algar 1 ][ El efecto del equipamiento requiere sastrería de Khaz Algar 1 ]Necesitas ser de nivel 68\n[q]\"Un contenedor tejido por los maestros artesanos de la Tejedora, capaz de maximizar el valor de telas esquivas como el tejido del alba y el tejido del crepúsculo.\""}
MultiLanguageSpellData['mx'][454432] = {name = "Marcha inexorable", additional_info = "[q0]Talento\n[q]Tu velocidad de movimiento no puede reducirse a menos de un 70% de la velocidad de movimiento normal mientras tus monedas sinoatadas tengan una racha activa de al menos 2 lanzamientos que coincidan con la misma cara."}
MultiLanguageSpellData['mx'][454433] = {name = "Llegada de la muerte", additional_info = "[q0]Talento\n[q]Forajido\n Gancho puede usarse por segunda vez en 3 s sin tiempo de reutilización, pero su tiempo de reutilización total aumenta 5 s.\n\nAsesinato\n Paso de las sombras puede usarse por segunda vez en 3 s sin tiempo de reutilización, pero su tiempo de reutilización total aumenta 5 s."}
MultiLanguageSpellData['mx'][454434] = {name = "Final inevitable", additional_info = "[q0]Talento\n[q]Forajido\n Sangre fría ahora beneficia las dos siguientes habilidades, pero solo se aplica a Despachar. Las monedas sinoatadas lanzadas por estas habilidades coincidirán con el mismo resultado del último lanzamiento.\n\nAsesinato\n Sangre fría ahora beneficia las dos siguientes habilidades, pero solo se aplica a Envenenar. Las monedas sinoatadas lanzadas por estas habilidades coincidirán con el mismo resultado del último lanzamiento."}
MultiLanguageSpellData['mx'][454435] = {name = "Destino definido", additional_info = "[q0]Talento\n[q]Forajido\n Golpe siniestro tiene un 5% más de probabilidad de golpear una vez más y tus monedas sinoatadas lanzadas tienen un 5% más de probabilidad de coincidir con la misma cara del último lanzamiento.\n\nAsesinato\n Los venenos de armas tienen un 5% más de probabilidad de aplicación y tus monedas sinoatadas lanzadas tienen un 5% más de probabilidad de coincidir con la misma cara del último lanzamiento."}
MultiLanguageSpellData['mx'][454436] = {name = "Pisotear", additional_info = "Alcance de 100 m\nInstante\n[q]Arremete contra un enemigo aleatorio e inflige 11025 p. de daño de las sombras a todos los jugadores atrapados en el camino. Las víctimas quedan aturdidas durante 10 s."}
MultiLanguageSpellData['mx'][454437] = {name = "Carga de azerita", additional_info = "Instante\n[q]¡Eres el objetivo de Carga de azerita!"}
MultiLanguageSpellData['mx'][454438] = {name = "Carga de azerita", additional_info = "Alcance de 100 m\nHechizo de 3 seg\n[q]Carga contra el objetivo enemigo y provoca una explosión de energía de azerita que inflige 4134 p. de daño arcano y 1102 p. más de daño arcano cada 1 s durante 5 s a todos los enemigos que están en un radio de 8 m del impacto."}
MultiLanguageSpellData['mx'][454439] = {name = "Carga de azerita", additional_info = "Alcance de 100 m\nInstante\n[q]Carga contra el objetivo enemigo y provoca una explosión de energía de azerita que inflige 4134 p. de daño arcano y 1102 p. más de daño arcano cada 1 s durante 5 s a todos los enemigos que están en un radio de 8 m del impacto."}
MultiLanguageSpellData['mx'][454440] = {name = "Vómito apestoso", additional_info = "Alcance de 100 m\nHechizo de 2 seg\n[q]Inflige 1654 p. de daño de naturaleza a objetivos enemigos y 1102 p. más de daño de naturaleza cada 2 s durante 12 s."}
MultiLanguageSpellData['mx'][454441] = {name = "Convertirse en pescador algari", additional_info = "Alcance de 5 m\nHechizo de 3.2 seg\n[q]¡Convertirse en pescador es fácil!\n\n Lanza tu sedal y pesca los numerosos secretos que ofrece Khaz Algar.\n\n Los peces capturados y los estanques de pesca aparecerán aquí, en tu confiable diario de pesca. ¡Los registros detallarán estos peces extravagantes y te indicarán dónde puedes encontrarlos!\nProfesión:\nPesca (1)"}
MultiLanguageSpellData['mx'][454442] = {name = "La habilidad en pesca y tú", additional_info = "Alcance de 5 m\nHechizo de 3.2 seg\n[q]A medida que mejora tu habilidad para pescar el pez perfecto, ¡también lo hace tu destreza en la pesca!\n\n Mejorar tu habilidad de pesca al máximo es la diferencia entre pescar una bota vieja o un codiciado pez trofeo.\nProfesión:\nPesca (25)"}
MultiLanguageSpellData['mx'][454443] = {name = "Lobina serena", additional_info = "Instante\n[q]Este sería un pez modesto si no fuera porque está recubierto de escamas esmeraldas resplandecientes. La lobina de río serena es abundante y apetitosa, y es muy popular en cualquier tipo de comida de mar.\n\nEspecial:\n\n Filete fresco\n\n Utilizar este pescado con la habilidad de cocina puede producir una cantidad moderada de filete fresco.\n\nÁreas donde puedes encontrar este pez:\n\n - Isla de Dorn\n - Las Minas Resonantes\n - Isla de las Sirenas\n\nEstanques de pesca:\n\n - Superficie calma con ondas\n - Estanque de lobinas de río\nProfesión:\nPesca"}
