MultiLanguageSpellData['mx'][455395] = {name = "Resucitar abominación", additional_info = "[q0]Talento\n{1 Runa / -10 Poder rúnico} {Alcance de 40 m}\n{Instante} {1.5 min de reutilización}\n[q]Resucita una Abominación durante 30 s que deambula y ataca a los enemigos. Además, aplica Herida degenerativa cuando ataca a un objetivo cuerpo a cuerpo y afecta a todos los objetivos cercanos con Peste virulenta."}
MultiLanguageSpellData['mx'][455396] = {name = "Infecciones hediondas", additional_info = "[q0]Talento\n[q]Tus enfermedades infligen un 10% más de daño y tienen un 5% más de probabilidad de golpe crítico."}
MultiLanguageSpellData['mx'][455397] = {name = "Guadaña purulenta", additional_info = "[q0]Talento\n[q]Cada 20 Heridas degenerativas que revientes, se potencia tu siguiente Golpe purulento y lo convierte en Guadaña.\n\nGuadaña purulenta\nAtaca a todos los enemigos en un radio de 14 m frente a ti, inflige ([200% of Attack Power]) p. de daño de las sombras y los infecta con 2-3 heridas degenerativas."}
