MultiLanguageSpellData['mx'][457049] = {name = "Bien alimentado", additional_info = "Instante\n[q]Bien alimentado \n\n Si comes durante al menos 10 s, quedarás Bien alimentado y obtendrás 470 p. de golpe crítico durante 1 h."}
MultiLanguageSpellData['mx'][457052] = {name = "Marca de mortacechador", additional_info = "[q0]Talento\n[q]Asesinato\n Lanzar Emboscada desde Sigilo le aplica 3 acumulaciones de Marca del mortacechador al objetivo. Cuando gastas 5 o más puntos de combo en ataques contra el objetivo marcado, consumes una aplicación de Marca del mortacechador, lo que inflige ([120% of Attack Power]) p. de daño de peste y aumenta el daño de tu siguiente Emboscada o Mutilar un 50%.\n Solo puede marcar a un objetivo a la vez.\n\nSutileza\n Lanzar Golpesombra desde Sigilo o Danza de las sombras le aplica 3 acumulaciones de Marca del mortacechador al objetivo. Cuando gastas 5 o más puntos de combo en ataques contra el objetivo marcado, consumes una aplicación de Marca del mortacechador, lo que inflige ([120% of Attack Power]) p. de daño de peste y aumenta el daño de tu siguiente un 50%.\n Solo puede marcar a un objetivo a la vez."}
MultiLanguageSpellData['mx'][457053] = {name = "Eliminar a los testigos", additional_info = "[q0]Talento\n[q]Asesinato\n Tu siguiente lanzamiento de Abanico de cuchillos después de aplicar Marca del mortacechador inflige ([100% of Attack Power]) p. más de daño de peste y genera 1 p. de combo más.\n\nSutileza\n Tu siguiente lanzamiento de Tormenta de shurikens después de aplicar Marca del mortacechador inflige ([100% of Attack Power]) p. más de daño de peste y genera 1 p. de combo más."}
MultiLanguageSpellData['mx'][457054] = {name = "Hora de cazar", additional_info = "[q0]Talento\n[q]Los ataques automáticos contra objetivos marcados infligen ([25% of Attack Power]) p. más de daño de peste."}
MultiLanguageSpellData['mx'][457055] = {name = "Enfoque singular", additional_info = "[q0]Talento\n[q]Infligir daño a objetivos aparte de tu objetivo marcado inflige un 5% de daño de peste a tu objetivo marcado."}
MultiLanguageSpellData['mx'][457056] = {name = "Oscuridad persistente", additional_info = "[q0]Talento\n[q]Sutileza\n Cuando expira Hojas de las sombras ganas 30 s de un 30% más daño de las sombras.\n\nAsesinato\n Cuando expira Marca mortal ganas 30 s de un 30% más daño de naturaleza."}
MultiLanguageSpellData['mx'][457057] = {name = "Corresombras", additional_info = "[q0]Talento\n[q]Cada vez que consumes una acumulación de Marca del mortacechador, reduces el tiempo de reutilización de Paso de las sombras 3 s."}
MultiLanguageSpellData['mx'][457058] = {name = "La noche más oscura", additional_info = "[q0]Talento\n[q]Asesinato\n Cuando consumes la última marca de Marca del mortacechador de un objetivo o cuando tu objetivo muere, obtienes 40 p. de energía, y tu siguiente lanzamiento de Envenenar con el número máximo de puntos de combo es un golpe crítico que inflige un 60% más de daño y le aplica 3 acumulaciones de Marca del mortacechador al objetivo.\n\nSutileza\n Cuando consumes la última marca de Marca del mortacechador de un objetivo o cuando tu objetivo muere, obtienes 40 p. de energía, y tu siguiente lanzamiento de Eviscerar con el número máximo de puntos de combo es un golpe crítico que inflige un 60% más de daño y le aplica 3 acumulaciones de Marca del mortacechador al objetivo."}
MultiLanguageSpellData['mx'][457059] = {name = "Flame Rift [NYI]", additional_info = "[q]Falla dimensional ahora puede invocar una poderosa Falla llameante."}
MultiLanguageSpellData['mx'][457060] = {name = "Lessons of Space-Time [NYI]", additional_info = "[q]Todo tu daño aumenta un 0% mientras tengas abierta una Falla dimensional."}
MultiLanguageSpellData['mx'][457062] = {name = "Victoria simbólica", additional_info = "[q0]Talento\n[q]Asesinato\n Además, Puyazo aumenta el daño de tu siguiente Envenenar un 18%.\n\nSutileza\n Además, Símbolos de la muerte aumenta el daño de tu siguiente Eviscerar o Polvo negro un 18%."}
MultiLanguageSpellData['mx'][457063] = {name = "Sudario de la noche", additional_info = "[q0]Talento\n[q]La duración de Embozo de encubrimiento aumenta 5 s."}
MultiLanguageSpellData['mx'][457064] = {name = "Falla inestable", additional_info = "[q0]Talento\n[q]Las saetas de Falla dimensional ahora infligen un 25% del daño infligido a los enemigos cercanos como daño de fuego."}
