MultiLanguageSpellData['mx'][457067] = {name = "Momento de desesperación", additional_info = "[q0]Talento\n[q]Si has asestado un golpe crítico con [Abanico de cuchillos / Tormenta de shurikens], aumenta la probabilidad de golpe crítico de [Abanico de cuchillos / Tormenta de shurikens] y [Tempestad carmesí / Polvo negro] un 15% y el daño de golpe crítico un 32% durante 12 s."}
