MultiLanguageSpellData['mx'][460476] = {name = "Fogonazo", additional_info = "Alcance de 40 m\nHechizo de 3.5 seg\n[q]Invoca un pilar de fuego que quema a todos los enemigos en el área y les inflige ([60% of Spell Power]) p. de daño de fuego. Inflige menos daño cuando golpea a más de 8 objetivos."}
MultiLanguageSpellData['mx'][460478] = {name = "Caminavientos", additional_info = "[q]Se divide en 3 espíritus elementales durante 15 s, cada espíritu inflige 40% del daño normal y sana.\n\n Controlas al Espíritu de tormenta directamente, mientras que los espíritus de Fuego y Tierra imitan tus ataques en enemigos cercanos.\n\n Al estar activo, lanzar Tormenta, Tierra y Fuego de nuevo causarán que los espíritus se fijen sobre tu objetivo."}
MultiLanguageSpellData['mx'][460482] = {name = "Cebo de bestia suprema", additional_info = "Alcance de 2 mHechizo de 2 seg 1 min de reutilización\n[q]Coloca el cebo y haz que una criatura elusiva suprema salga de su escondite.\n\n Solo se puede usar en los Páramos Rugientes, dentro de las Minas Resonantes."}
