MultiLanguageSpellData['mx'][460485] = {name = "Ráfaga de chi", additional_info = "[q0]Talento\nAproximadamente 1.5 activaciones por minuto\n[q]Viajero del viento, Tejedor de niebla\n Tus hechizos y habilidades que infligen daño tienen una probabilidad de activar Ráfaga de chi, lo que te permite lanzar un torrente de Energía de chi hasta un máximo de 40 m hacia adelante, lo que inflige ([280% of Attack Power]) p. de daño de naturaleza a todos los enemigos y sana ([220% of Attack Power]) p. al monje y a todos los aliados a su paso. La sanación y el daño se reducen cuando alcanza a más de 5 objetivos.\n\n\nMaestro cervecero\n Tus hechizos y habilidades que infligen daño tienen una probabilidad de activar Ráfaga de chi, lo que te permite lanzar un torrente de Energía de chi hasta un máximo de 40 m hacia adelante, lo que inflige ([280% of Attack Power]) p. de daño de naturaleza a todos los enemigos y sana ([220% of Attack Power]) p. al monje y a todos los aliados a su paso. La sanación y el daño se reducen cuando alcanza a más de 5 objetivos.\n\n\n Lanzar Ráfaga de chi no impide evitar ataques."}
MultiLanguageSpellData['mx'][460489] = {name = "Mantenimiento violento", additional_info = "Alcance de 100 m\nInstante\n[q]M.A.M.A.Z.O.T.A. energiza a todos los drones cercanos derrotados. Gasta 20) p. de energía en cada dron para darle una descarga y dejarlo nuevamente en condiciones funcionales. La descarga expulsa chispazos de electricidad que infligen 10 p. de daño de naturaleza a los jugadores que las tocan."}
MultiLanguageSpellData['mx'][460490] = {name = "Ráfaga de chi", additional_info = "Instante\n[q]Tus hechizos y habilidades que infligen daño tienen una probabilidad de activar Ráfaga de chi, lo que te permite lanzar un torrente de Energía de chi hasta un máximo de 40 m hacia adelante, lo que inflige ([280% of Attack Power]) p. de daño de naturaleza a todos los enemigos y sana ([220% of Attack Power]) p. al monje y a todos los aliados a su paso. La sanación y el daño se reducen cuando alcanza a más de 5 objetivos.\n [ Maestro cervecero : Lanzar Ráfaga de chi no impide evitar ataques ]"}
