MultiLanguageSpellData['mx'][460499] = {name = "Espada ensangrentada", additional_info = "Instante\n[q]Parar un ataque te otorga una carga de Espada ensangrentada que aumenta tu fuerza un 0.5%, hasta un máximo de 4.0% durante 15 s.\n\n Al alcanzar 8 acumulaciones, tu próxima parada consume todas las cargas, desata un Golpe en el corazón con un 300% de eficacia y aumenta tu fuerza un 10% durante 6 s."}
