MultiLanguageSpellData['mx'][461245] = {name = "Radiancia reluciente", additional_info = "[q0]Talento\n[q]Gastar poder sagrado tiene un 25% de probabilidad de activar el efecto de absorción de Salvado por la Luz con una eficacia del 33% sin activar su tiempo de reutilización.\n(750ms de reutilización)"}
MultiLanguageSpellData['mx'][461246] = {name = "Amanecer glorioso", additional_info = "[q0]Talento\n[q]Choque sagrado tiene un 12% de probabilidad de restituir una carga con el lanzamiento, y su sanación aumenta un 10%."}
MultiLanguageSpellData['mx'][461248] = {name = "Alto voltaje", additional_info = "[q0]Talento\n[q]El daño de Misiles arcanos tiene un 10% de probabilidad de otorgarte 1 Carga arcana.\n\n La probabilidad aumenta un 15% cada vez que Misiles arcanos no te otorga una Carga arcana."}
MultiLanguageSpellData['mx'][461250] = {name = "Luz del sol naciente", additional_info = "[q0]Talento\n[q][ Cruzado vengador : Tras lanzar Cruzado vengador, tu siguiente Choque sagrado se activa 2 veces más / Tras lanzar Cólera vengativa, tus siguientes 2 Choques sagrados se activan 2 veces más.]\n Tras lanzar Tañido divino, tus siguientes 2 Choques sagrados se activan 2 veces más."}
