MultiLanguageSpellData['mx'][461264] = {name = "Flujo abisal", additional_info = "[q0]Especializaciones de tanque – Talento JcJ de la fila 1\n[q]Sustituye Toque del Magi\nAlcance de 40 m\n{Instante} {15 seg de reutilización}\n[q]Marca a tu objetivo y aumenta un 40% el daño que recibe de tu próximo hechizo con objetivo.\n\nGenera 4 cargas arcanas."}
MultiLanguageSpellData['mx'][461273] = {name = "La verdad prevalece", additional_info = "[q0]Talento\n[q]Sentencia te sana ([240% of Spell Power]) p., y su costo de maná se reduce un 30%. El 50% de la sanación en exceso de este efecto se transfiere a 2 aliados en un radio de 40 m."}
MultiLanguageSpellData['mx'][461278] = {name = "Librar", additional_info = "[q0]Talento\n[q]Aumenta hasta un 30% la probabilidad de asestar un golpe crítico con Palabra de gloria y Luz del alba, según la salud actual de su objetivo. Cuanta menos salud tengan los objetivos, mayor será la probabilidad de que reciban un golpe crítico."}
